window.WIKI_ROLE_PREVIEWS={"pages/主教.html":{"name":"主教","englishName":"Bishop","background":["“我以圣父，圣子，圣灵的名义...乞求主神保佑我们。”"],"roles":[{"name":"主教","team":"traveller","ability":"只有说书人可以发起提名。每个白天说书人至少要提名一名你对立阵营的玩家。"}]},"pages/主谋.html":{"name":"主谋","englishName":"Mastermind","background":["“怪物的触手被钉在了教堂大门上。母亲和孩子们在街上跳舞。棒极了。一切都在按我的计划进行。”"],"roles":[{"name":"主谋","team":"minion","ability":"如果恶魔因为死于处决而因此导致游戏结束时，再额外进行一个夜晚和一个白天。在那个白天如果有玩家被处决，他的阵营落败。"}]},"pages/乌贼娘_Squid_Girl.html":{"name":"乌贼娘","englishName":"Squid Girl","background":["\"噗嘶——啊！已经漏了！完了完了要失控了！噗咻咻咻——\""],"roles":[{"name":"乌贼娘","team":"outsider","ability":"如果你即将死亡，你可能不会死亡，但所有镇民会醉酒直到明天黄昏。"}]},"pages/乞丐.html":{"name":"乞丐","englishName":"Beggar","background":["“行行好吧，先生？哪怕是一枚硬币，夫人？谢天谢地，上天保佑！你真是个善良的人！今晚我要好好地吃上一顿，一定要！”"],"roles":[{"name":"乞丐","team":"traveller","ability":"你只能使用投票标记投票。死亡的玩家可以将他的投票标记给你，如果他这么做，你会得知他的阵营。你不会中毒和醉酒。"}]},"pages/书生.html":{"name":"书生","englishName":"Pedant","background":["“杀我可以，不过我得死个明白——我到底死在谁的手里？”"],"roles":[{"name":"书生","team":"outsider","ability":"恶魔知道你在场。每局游戏限一次，恶魔可以拜访说书人并猜测谁是书生。如果恶魔猜测正确，即使你已死亡，当晚该恶魔可以选择一名玩家：他死亡。"}]},"pages/事务官.html":{"name":"事务官","englishName":"Steward","background":["“你竟敢指责夫人的过错？我认识她一辈子了！整整九年！”"],"roles":[{"name":"事务官","team":"townsfolk","ability":"在你的首个夜晚，你会得知一名善良玩家。"}]},"pages/亚瑟_Arthur.html":{"name":"亚瑟","englishName":"Arthur","background":["“湖中仙女当年递给我剑时，藏起了另一句话——‘你终将溺毙于自己的荣耀。’如今我浮上水面，吐出不甘与悔恨，却发现自己早已长出鳞片与利爪。堕落？这是我的新生。每一个背叛我的人，都将被我挂在卡美洛特的残垣上风干。我回来了，带着锈蚀的圣剑与石化的心。”"],"roles":[{"name":"亚瑟","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。当亚瑟首次攻击爪牙时，亚瑟会与其交换角色，且两名存活玩家代替其被攻击。"}]},"pages/亡骨魔.html":{"name":"亡骨魔","englishName":"Vigormortis","background":["“世间万扉集为一体，世间万匙铸为一身。世间万盅将与我共饮，但凡饮下我所赐圣水者，必将永不干渴，化作万孔泉眼涌作永生。”"],"roles":[{"name":"亡骨魔","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。被你杀死的爪牙保留他的能力，且与他邻近的两名镇民之一中毒。[-1外来者]"}]},"pages/代号X_CodeX.html":{"name":"代号X","englishName":"CodeX","background":["“程序激活...指令已接收。对1号目标执行操作一次，目标立即失去知觉。对2号目标执行操作两次，目标全身细胞崩解。”"],"roles":[{"name":"代号X","team":"minion","ability":"每局游戏限一次，在你的第X个夜晚，你可以选择任意玩家共X次：他们中毒直到下个黄昏。被多次选择的玩家改为死亡。"}]},"pages/仲裁者_Arbiter.html":{"name":"仲裁者","englishName":"Arbiter","background":["_\"__肃静。我来此不为倾听辩解，也不为彰显仁慈。你们的罪与功，早已刻在我的双目之中。我既不偏袒权贵，也不怜悯弱者。清白无辜之人，即使笨口拙舌，利刃永不相向；身负罪孽之辈，纵然巧言令色，终究难逃审判。现在，带上前来。__\"_"],"roles":[{"name":"仲裁者","team":"townsfolk","ability":"如果你提名并处决了一名其他善良玩家，他不会死于本次处决。"}]},"pages/传教士.html":{"name":"传教士","englishName":"Preacher","background":["“富有和健康总比贫穷和疾病要好。”"],"roles":[{"name":"传教士","team":"townsfolk","ability":"每个夜晚，你要选择一名玩家：如果选中了爪牙，他会得知被选中。所有被选中的爪牙失去能力。"}]},"pages/佛教徒.html":{"name":"佛教徒","englishName":"Buddhist","background":["“人生在世如身处荆棘之中，心不动，人不妄动，不动则不伤。”"],"roles":[{"name":"佛教徒","team":"fabled","ability":"每个白天的前两分钟老玩家不能发言。"}]},"pages/使节.html":{"name":"使节","englishName":"Ambassador","background":["“岭海滞公犹未召，蛮荒著我更何尤。”"],"roles":[{"name":"使节","team":"outsider","ability":"每个夜晚限一次，所有玩家在使用自身能力选择邪恶玩家时会改为选中你，即使你已死亡。"}]},"pages/侍女.html":{"name":"侍女","englishName":"Chambermaid","background":["“我没有看到任何不寻常的事，夫人。请原谅我，但要是我真的看到了什么，那一定不是屋子主人在大约十一点的时候溜进了教授的实验室还把那些花花绿绿的药剂混合在了一起，就如你所说的那样，女士。”"],"roles":[{"name":"侍女","team":"townsfolk","ability":"每个夜晚，你要选择除你以外的两名存活的玩家：你会得知他们中有几人在当晚因其自身能力而被唤醒。"}]},"pages/侍臣.html":{"name":"侍臣","englishName":"Courtier","background":["“比起一只羊带领的一百头狮子，我更害怕一头狮子带领的一百只羊。”"],"roles":[{"name":"侍臣","team":"townsfolk","ability":"每局游戏限一次，在夜晚时，你可以选择一个角色：如果该角色在场，该角色之一从当晚开始醉酒三天三夜。"}]},"pages/侏儒.html":{"name":"侏儒","englishName":"Gnome","background":["“有备而来，有悲而来，无人搭台，自己开嗨！一场整人好戏，整得人惨兮兮，吱吱作响板板，又怕翻了盘盘。那些长篇大论顺着乔伊斯的溪流在流淌，不算最辉煌，也还够气场，却也挺像样——哈，响亮！”"],"roles":[{"name":"侏儒","team":"traveller","ability":"当你加入游戏时，所有玩家会得知一名与你阵营相同的玩家。每当他被提名时，你可以杀死提名者。"}]},"pages/修行者.html":{"name":"修行者","englishName":"Shugenja","background":["“此即梦境。彼亦梦境。所见之物，非此即彼。”"],"roles":[{"name":"修行者","team":"townsfolk","ability":"在你的首个夜晚，你会得知距离最近的邪恶玩家位于你的顺时针还是逆时针方向。如果两侧的邪恶玩家与你距离相等，你得知的信息由说书人决定。"}]},"pages/修补匠.html":{"name":"修补匠","englishName":"Tinker","background":["“我觉得我发现问题所在了。幸运的是，我有一个想法！这能让这台投石车的发射距离变成原来的两倍，而这只需要些微的调……”"],"roles":[{"name":"修补匠","team":"outsider","ability":"你随时可能死亡。"}]},"pages/倒吊人_Hanged_Man.html":{"name":"倒吊人","englishName":"Hanged Man","background":["“习惯让你们向下找，我倒悬教你们向上找。当血液冲进大脑，常识开始颠倒。你学会倒着看世界，世界就给你新视角。”"],"roles":[{"name":"倒吊人","team":"townsfolk","ability":"当游戏结束时，如果你使用过投票标记投票，对调胜负结果。"}]},"pages/僧侣.html":{"name":"僧侣","englishName":"Monk","background":["“今夜吹来的是一股邪恶又致命的风。","来吧，我的同胞，这风暴过于肆虐，来修道院找寻庇佑吧。","我保证，我会用性命，护你周全。”"],"roles":[{"name":"僧侣","team":"townsfolk","ability":"每个夜晚*，你要选择除你以外的一名玩家：当晚恶魔的负面能力对他无效。"}]},"pages/僵怖.html":{"name":"僵怖","englishName":"Zombuul","background":["“我不。明白。你的。方式。人类。同类。向我。指引。泥土。那是。圣地。静卧。安睡。我也。必须。长眠。立刻。”"],"roles":[{"name":"僵怖","team":"demon","ability":"每个夜晚*，如果今天白天没有人死亡，你会被唤醒并要选择一名玩家：他死亡。当你首次死亡后，你仍存活，但会被当作死亡。"}]},"pages/克拉肯_Kraken.html":{"name":"克拉肯","englishName":"Kraken","background":["_\"__我从那连神明尸骸都无法沉入的深渊中升起。我聆听过地壳撕裂的初啼，在岩浆与绝对零度的夹缝里，把心脏炼成不灭的熔核。生命力，是我从深潜里带回的唯一行李。吾乃克拉肯，于深渊行走的永生。__\"_"],"roles":[{"name":"克拉肯","team":"demon","ability":"每个夜晚*，你可以选择一名玩家：他死亡。如果你在审判日降临前死亡，改为你假死，且你能力中的“一名玩家”改为“一名与你邻近的存活玩家”。"}]},"pages/克隆_Clone.html":{"name":"克隆","englishName":"Clone","background":["_“__侵入、吸收、重塑。一切的关键，在于那段名为 DNA 的密码。或者用这个时代的愚昧说法，我该叫它——灵魂？__”_"],"roles":[{"name":"克隆","team":"minion","ability":"每局游戏限一次，在夜晚时*，你可以选择一名玩家：他死亡，且你变成他的角色。"}]},"pages/入殓师.html":{"name":"入殓师","englishName":"Mortician","background":["“未销心里恨，又失掌中身。”"],"roles":[{"name":"入殓师","team":"outsider","ability":"如果你提名并处决了恶魔，你会变成邪恶的恶魔。当剩余存活玩家小于等于四人时（旅行者除外），你失去能力。"}]},"pages/公主.html":{"name":"公主","englishName":"Princess","background":["“言似猎犬，细语为绳；善念牵引，王廷方宁。”"],"roles":[{"name":"公主","team":"townsfolk","ability":"在你的首个白天，如果你提名并处决了一名玩家，当晚恶魔不会造成死亡。"}]},"pages/公爵夫人.html":{"name":"公爵夫人","englishName":"Duchess","background":["“我们会在6点至7点之间招待客人。6点15分喝茶点。6点45分吃松饼。不要迟到，着装要像往常一样正式。”"],"roles":[{"name":"公爵夫人","team":"fabled","ability":"每个白天，三名玩家可以一起拜访你。当晚*，他们会得知他们之中有几个是邪恶的，但其中一人的信息是错的。"}]},"pages/公证人_Notary.html":{"name":"公证人","englishName":"Notary","background":["_\"__这册子我扔过一次，又捡回来了。那天的记录，我把印章举了三回，到底没盖下去。那一页上的两个名字太像了，像得不像仇人，像兄弟。\"_"],"roles":[{"name":"公证人","team":"townsfolk","ability":"每个夜晚*，你会得知当天死于处决的玩家与提名他的玩家是否为同一阵营。"}]},"pages/共情者.html":{"name":"共情者","englishName":"Empath","background":["“我的皮肤有些刺痛。","这有些不太对劲。我能感觉得到。”"],"roles":[{"name":"共情者","team":"townsfolk","ability":"每个夜晚，你会得知与你邻近的两名存活的玩家中邪恶玩家的数量。"}]},"pages/典狱长.html":{"name":"典狱长","englishName":"Warden","background":["“一囚伏法，举族同拘。”"],"roles":[{"name":"典狱长","team":"demon","ability":"每个夜晚，你要选择一至三名玩家。如果明天白天其中之一被处决，其余玩家会在当晚死亡。否则，当晚他们之中会有一名玩家死亡。"}]},"pages/养蛊人.html":{"name":"养蛊人","englishName":"Bug Keeper","background":["“把毒蛇、蝎子、蜈蚣、蟾蜍、蜘蛛放在一起……","多！来！点！”"],"roles":[{"name":"养蛊人","team":"minion","ability":"在你存活时提名你的玩家会在当晚死亡，即使你已死亡。"}]},"pages/养蜂人_Beekeeper.html":{"name":"养蜂人","englishName":"Beekeeper","background":["“真是对不住，这些调皮的小家伙伤到您了。这是我自家的蜂蜜，敷上就能消肿止痛，还请您收下。”"],"roles":[{"name":"养蜂人","team":"outsider","ability":"一名玩家中毒，即使你已死亡。每个夜晚，你要选择一名玩家：如果他因你中毒，他恢复健康。"}]},"pages/军团.html":{"name":"军团","englishName":"Legion","background":["“我们是冬日刺骨的寒风。我们是无月之夜的阴影。我们是你茶里的毒药，是你耳边的低语。我们无处不在。”"],"roles":[{"name":"军团","team":"demon","ability":"每个夜晚*，可能有一名玩家死亡。如果一项提名只有邪恶玩家投票，投票无效。你也会被当作是爪牙。[半数以上玩家为军团]"}]},"pages/农夫.html":{"name":"农夫","englishName":"Farmer","background":["“即使那些高高在上的人也需要吃东西。没有了我们，城市就会挨饿。”"],"roles":[{"name":"农夫","team":"townsfolk","ability":"如果你在夜晚死亡，一名存活的善良玩家会变成农夫。"}]},"pages/利维坦.html":{"name":"利维坦","englishName":"Leviathan","background":["“末日将临，斗争永无止境。","地狱之心，吾以利剑相迎。","仇恨燃尽，然而愤懑难平。”"],"roles":[{"name":"利维坦","team":"demon","ability":"如果多于一名善良玩家被处决，邪恶阵营获胜。所有玩家都知道利维坦在场。在第五个白天结束时，邪恶阵营获胜。"}]},"pages/刺客.html":{"name":"刺客","englishName":"Assassin","background":["“……”"],"roles":[{"name":"刺客","team":"minion","ability":"每局游戏限一次，在夜晚时*，你可以选择一名玩家：他死亡，即使因为任何原因让他不会死亡。"}]},"pages/刻耳柏洛斯_Cerberus.html":{"name":"刻耳柏洛斯","englishName":"Cerberus","background":["“啃食你的肉体，超度你的灵魂，然后与我一起徘徊在这地狱之门。”"],"roles":[{"name":"刻耳柏洛斯","team":"demon","ability":"每个夜晚*，你要选择一名玩家，每当你选中邪恶玩家，你要再选一名玩家：他们死亡。被你杀死的爪牙会保留能力。"}]},"pages/劣魔_Dretch.html":{"name":"劣魔","englishName":"Dretch","background":["\"K'zhak! K'zhak! Dretch! Dretch!（深渊语：快来！劣魔们！）\""],"roles":[{"name":"劣魔","team":"demon","ability":"每个夜晚*，会有一名玩家死亡。你可以在被提名后呼唤同伴：如果存活玩家中邪恶玩家更少，一名爪牙会变成劣魔。"}]},"pages/化妆师_Visagiste.html":{"name":"化妆师","englishName":"Visagiste","background":["\"同样一抹胭红，抹在脸颊是羞涩，抹在眼尾是风情，抹在唇角是刻薄。一张脸，三个位置，三幅面孔。来找我的客人总说‘随便画画’，但我从不随便。我得先看她的骨相，再看她的五官，最后才决定她今晚会变成谁。\""],"roles":[{"name":"化妆师","team":"outsider","ability":"如果你提名的或提名你的玩家是爪牙或恶魔，当晚他可以选择变成不在场的同类型角色，即使你已死亡。"}]},"pages/半人马_Centaur.html":{"name":"半人马","englishName":"Centaur","background":["_\"__正义如果来得太迟，就由我的铁蹄亲自送达。别害怕被践踏的命运，我的铁蹄，至少是慈悲的——不伪装成希望，不拖延成绝望。它是我唯一的、最坦诚的怜悯。\"_"],"roles":[{"name":"半人马","team":"townsfolk","ability":"每个夜晚，你要选择一名其他玩家（与上个夜晚不同）：如果他的角色类型与你上个夜晚选择的玩家相同，他死亡。"}]},"pages/半仙.html":{"name":"半仙","englishName":"Banxian","background":["“平时里见他，要么浑身污垢满嘴臭味，要么疯言疯行不知所云。”"],"roles":[{"name":"半仙","team":"townsfolk","ability":"任何在夜晚使用自身能力选择你的其他玩家，会改为选中另一名邪恶玩家作为替代。"}]},"pages/半兽人.html":{"name":"半兽人","englishName":"Lycanthrope","background":["“在文明的浅薄外表之下，藏着呼之欲出的疯狂。”"],"roles":[{"name":"半兽人","team":"townsfolk","ability":"每个夜晚*，你要选择一名存活玩家：如果他是善良的，他死亡，并且当晚恶魔不会造成死亡。会有一名善良玩家始终被当作邪恶阵营。"}]},"pages/卖花女孩.html":{"name":"卖花女孩","englishName":"Flowergirl","background":["“昨天，我的紫罗兰凋谢了。今天，我的罂粟花盛开了。”"],"roles":[{"name":"卖花女孩","team":"townsfolk","ability":"每个夜晚*，你会得知在今天白天时是否有恶魔投过票。"}]},"pages/博学者.html":{"name":"博学者","englishName":"Savant","background":["“地上有七十二根火柴……今天的太阳落得更早，月亮还是按时升起……一块破布……庄园里的邪恶之物……三个又三个……我们相信的事物和他真正看到的不一样……绿光代表镁……残留物，但是图案不太对……地上有七十二根火柴……”"],"roles":[{"name":"博学者","team":"townsfolk","ability":"每个白天，你可以私下拜访说书人以得知两条信息：一个是正确的，一个是错误的。"}]},"pages/占卜师.html":{"name":"占卜师","englishName":"Fortune Teller","background":["“我在你的灵魂中感受到了庞大的恶意！","但……那可能只是你的香水味道。我对接骨木汁过敏。”"],"roles":[{"name":"占卜师","team":"townsfolk","ability":"每个夜晚，你要选择两名玩家：你会得知他们之中是否有恶魔。会有一名善良玩家始终被你的能力当作恶魔。"}]},"pages/卡扎力.html":{"name":"卡扎力","englishName":"Kazali","background":["“Gon(z)a7les6。请当Zn。机制已被FAN转。系统古攵阝章。重新{配}置。”"],"roles":[{"name":"卡扎力","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。[由你决定谁是什么爪牙，-或+任意数量外来者]"}]},"pages/印度教教徒.html":{"name":"印度教教徒","englishName":"Hindu","background":["“四者陨落于生灭之隙，”","“四者归返于流转之途。”","“四者心住于道法，”","“四者不复终结于终。”","（印度语）"],"roles":[{"name":"印度教教徒","team":"loric","ability":"最先死亡的四名玩家会立刻以相同阵营的旅行者转世重生。"}]},"pages/厨师.html":{"name":"厨师","englishName":"Chef","background":["“今晚的预约有些古怪。我从未见过梅威瑟太太此前跟那个哈德逊巷的流氓有过交情。","然而今晚，他们订了一张双人桌。真奇怪。”"],"roles":[{"name":"厨师","team":"townsfolk","ability":"在你的首个夜晚，你会得知场上邻座的邪恶玩家有多少对。"}]},"pages/双头巨人_Ettin.html":{"name":"双头巨人","englishName":"Ettin","background":["“（庄严）巨人永不为奴…（插嘴）除非包吃包住！（突然亢奋）俺们杀人超厉害！（捂嘴）闭嘴！要说‘执行正义‘！”"],"roles":[{"name":"双头巨人","team":"minion","ability":"如果你死亡，其他双头巨人会在当晚死亡。只有所有双头巨人一起投票，他们的投票才有效。[+1双头巨人（你决定谁是）]"}]},"pages/双生花_Twinflower.html":{"name":"双生花","englishName":"Twinflower","background":["\"幽影双生，善恶有迹。花开并蒂，命定相依。\""],"roles":[{"name":"双生花","team":"minion","ability":"你以为你是一个镇民角色，但其实你不是。[+1双生花，两名双生花邻座]"}]},"pages/双面人_Two-Face.html":{"name":"双面人","englishName":"Two-Face","background":["\"一念善，心量无垠。一念恶，方寸自囚。一念起，善恶相生。一念落，凡圣两忘。\""],"roles":[{"name":"双面人","team":"outsider","ability":"每个夜晚*，你会转变为与上个死于处决的玩家对立的阵营。"}]},"pages/变脸师.html":{"name":"变脸师","englishName":"Face Changer","background":["“台上一分钟，台下十年功。”"],"roles":[{"name":"变脸师","team":"townsfolk","ability":"每个白天，如果你“疯狂”地证明自己是一个善良角色（与之前不同），你会在当晚获得那个角色的能力，直到下个黄昏。"}]},"pages/叫花子.html":{"name":"叫花子","englishName":"Pauper","background":["“瞧一瞧，看一看，这里来个穷要饭。","给个馍，给口汤，祝恁长命又健康。","行行好，行行妙，施舍得人呱呱叫。","让额走，额就走，⽼板伸出富贵⼿。”"],"roles":[{"name":"叫花子","team":"traveller","ability":"每个白天限一次，你可以公开选择一名其他玩家，让他选择一个非恶魔角色：你可能会获得这个角色的能力，直到下个黎明。"}]},"pages/召唤师.html":{"name":"召唤师","englishName":"Summoner","background":["“颂赞北之守护，以吾之智慧，斩却汝命；","颂赞东之守护，以吾之意志，制御汝身；","颂赞南之守护，以超越之力，揭示前路；","颂赞西之守护，于漫漫长夜，化为坚盾。”"],"roles":[{"name":"召唤师","team":"minion","ability":"在首个夜晚，你会得知三个伪装。在第三个夜晚，你要选择一名玩家：他变成由你选择的邪恶恶魔。[无恶魔在场]\n\n"}]},"pages/吟游诗人.html":{"name":"吟游诗人","englishName":"Minstrel","background":["“我应倾听，当你轻敲我心……","美梦因你，甜美温馨……","若你羞赧，难以决定……","我会安睡，待你光临。”"],"roles":[{"name":"吟游诗人","team":"townsfolk","ability":"当一名爪牙死于处决时，除了你和旅行者以外的所有其他玩家醉酒直到明天黄昏。"}]},"pages/呆瓜.html":{"name":"呆瓜","englishName":"Klutz","background":["“哎哟！”"],"roles":[{"name":"呆瓜","team":"outsider","ability":"当你得知你死亡时，你要公开选择一名存活的玩家：如果他是邪恶的，你的阵营落败。"}]},"pages/告密者.html":{"name":"告密者","englishName":"Snitch","background":["“是他干的。”"],"roles":[{"name":"告密者","team":"outsider","ability":"爪牙会在其首个夜晚得知三个不在场的善良角色。"}]},"pages/和尚.html":{"name":"和尚","englishName":"Heshang","background":["“本来无一物，何处惹尘埃。”"],"roles":[{"name":"和尚","team":"townsfolk","ability":"每个夜晚，当有邪恶玩家的能力首次选择或影响与你邻近的存活玩家时，改为此次能力不生效并持续至下个黎明，且你会得知你的能力被触发。"}]},"pages/和平主义者.html":{"name":"和平主义者","englishName":"Pacifist","background":["“任何有强烈惩罚冲动的人都不可信赖。”"],"roles":[{"name":"和平主义者","team":"townsfolk","ability":"被处决的善良玩家可能不会死亡。"}]},"pages/咖啡师.html":{"name":"咖啡师","englishName":"Barista","background":["“一杯不加奶油的咖啡，先生？我真的很抱歉，我们刚刚用完了所有的奶油——一杯不加牛奶的咖啡怎样？”"],"roles":[{"name":"咖啡师","team":"traveller","ability":"每个夜晚，直至下个黄昏，由说书人二选一：1）一名玩家解除并免受醉酒和中毒影响，且会得知正确信息；2）一名玩家的能力可以生效两次。该玩家会得知是哪个效果。"}]},"pages/哈迪寂亚.html":{"name":"哈迪寂亚","englishName":"Al-Hadikhia","background":["“沉默是金。”（阿拉伯语）"],"roles":[{"name":"哈迪寂亚","team":"demon","ability":"每个夜晚*，你要选择三名玩家（所有玩家都会得知你选了谁）：他们分别秘密决定自己的生死，然后如果他们都存活则都死亡。"}]},"pages/哥布林.html":{"name":"哥布林","englishName":"Goblin","background":["“你不会想要侮辱哥布林的。你真的，真的不会。让我们换个话题……我能再吃一块蛋糕吗？”"],"roles":[{"name":"哥布林","team":"minion","ability":"如果你在被提名后公开声明自己是哥布林且在那个白天被处决，你的阵营获胜。"}]},"pages/哨兵.html":{"name":"哨兵","englishName":"Sentinel","background":["“请提供你的名字，请出示你的证件，请展示你的武器。”"],"roles":[{"name":"哨兵","team":"fabled","ability":"在初始设置时，可能会额外增加或减少一个外来者。"}]},"pages/哲学家.html":{"name":"哲学家","englishName":"Philosopher","background":["“如果你要说什么事情是最真实的？我想是啤酒。痛快喝吧，说不定我们明天就要死了。”"],"roles":[{"name":"哲学家","team":"townsfolk","ability":"每局游戏限一次，在夜晚时，你可以选择一个善良角色：你获得该角色的能力。如果这个角色在场，他醉酒。"}]},"pages/唱诗男孩.html":{"name":"唱诗男孩","englishName":"Choirboy","background":["“我看到了，真的。我那会儿正在长椅上整理赞美诗册，突然一首可怕的管风琴曲子在我耳边响起。那风琴手披着一件长斗篷，他修长的手指搭在琴键上。他有一顶帽子……就像是……你现在戴着的这顶。”"],"roles":[{"name":"唱诗男孩","team":"townsfolk","ability":"如果恶魔杀死了国王，你会得知哪名玩家是恶魔。[+国王]"}]},"pages/回响_Echo.html":{"name":"回响","englishName":"Echo","background":["\"时间不是线性的，死亡也不是。每一声未被回应的呼喊，回响之后，都将汇作震耳欲聋的尖啸。回响从不遗忘，回响从不原谅。回响是命运设下的网，你越挣扎越被捆绑。\""],"roles":[{"name":"回响","team":"demon","ability":"每个夜晚*，你要选择一个角色：他死亡。如果该角色不在场，下个夜晚你要额外选择一个角色（可叠加）。"}]},"pages/园丁.html":{"name":"园丁","englishName":"Gardener","background":["“哎呀，这可不行。乌头和狼毒草怎么混到一块儿去了？毒芹也把黑藜都压住了！唉，还是得重新来过一遍。把我的剪枝剪拿来吧。”"],"roles":[{"name":"园丁","team":"loric","ability":"由说书人来为所有玩家派发角色。"}]},"pages/国王.html":{"name":"国王","englishName":"King","background":["“未知纷扰让致命冲突重负难堪，","在不祥之夜将神秘与悲伤盈满，","欢喜或曾无羁于漫长多彩世间，","谁的花园遍地绽放着彩绘的脸。”"],"roles":[{"name":"国王","team":"townsfolk","ability":"每个夜晚，如果死亡的玩家数量大于存活的玩家数量，你会得知一个存活的角色。恶魔知道你是国王。"}]},"pages/图书管理员.html":{"name":"图书管理员","englishName":"Librarian","background":["“毫无疑问，这位女士，在通常情况下，你可以从图书馆的馆藏中借阅《凶恶药典》。","然而，你看起来不像是会员。”"],"roles":[{"name":"图书管理员","team":"townsfolk","ability":"在你的首个夜晚，你会得知两名玩家和一个外来者角色：这两名玩家之一是该角色（或者你会得知没有外来者在场）。"}]},"pages/圣徒.html":{"name":"圣徒","englishName":"Saint","background":["“智慧带来和平。耐心孕育智慧。","无需惧怕，因为恐惧消散的那一天终将到来。","让我们一同祈祷，愿我们愿景一致，共赴圣洁。”"],"roles":[{"name":"圣徒","team":"outsider","ability":"如果你死于处决，你的阵营落败。"}]},"pages/圣洁之魂.html":{"name":"圣洁之魂","englishName":"Spirit Of Ivory","background":["“荒芜之地传来呼唤，生肉枯骨，落入尘土。是圣洁之魂在生长，是圣洁之魂在注视，是圣洁之魂在引导。人类遵循这一切，否则早已被覆灭。”"],"roles":[{"name":"圣洁之魂","team":"fabled","ability":"游戏过程中邪恶玩家的总数最多能比初始设置多一名。"}]},"pages/圣骑士_Paladin.html":{"name":"圣骑士","englishName":"Paladin","background":["_\"__昨夜我跪在圣坛前祈祷，神的声音如火焰般落在我肩上：‘去那座小镇，那里有我的羔羊。’所以我来了。我的盔甲上没有锈迹，因为每一道划痕都被圣水清洗过；我的剑刃永远温热，因为神的力量流淌其中。哪里有不公，哪里有哭泣，哪里就是我的战场。__\"_"],"roles":[{"name":"圣骑士","team":"townsfolk","ability":"每个夜晚，你会得知两名玩家：他们要么都不是爪牙，要么都不是恶魔。两类线索每夜交替。"}]},"pages/地狱弃子_Hell's_Outcast.html":{"name":"地狱弃子","englishName":"Hell's Outcast","background":["“他们剪去我的双翼，掷我于蛮荒。每寸腐土都在倒数，等地狱拥立他们的新王。”"],"roles":[{"name":"地狱弃子","team":"outsider","ability":"每个白天提名开始前，爪牙可以公开拥立地狱弃子：你立即转变为邪恶并与恶魔交换角色，然后他醉酒。"}]},"pages/地狱藏书员.html":{"name":"地狱藏书员","englishName":"Hell's Librarian","background":["“嘘……请安静。最好不要打扰到藏书员，我知道他脾气可不小。”"],"roles":[{"name":"地狱藏书员","team":"fabled","ability":"当说书人宣布安静时，仍在说话的玩家可能会遭遇一些不好的事情。"}]},"pages/地狱轮盘_Hell's_Roulette.html":{"name":"地狱轮盘","englishName":"Hell's Roulette","background":["_\"规则很简单，深呼吸，然后扣下扳机。__\"_"],"roles":[{"name":"地狱轮盘","team":"fabled","ability":"玩家在发起提名后要掷出一个六面骰：如果掷出的点数已存在，他死亡，并移除所有已掷的骰子。"}]},"pages/城镇公告员.html":{"name":"城镇公告员","englishName":"Town Crier","background":["“号外！号外！迷宫中的巫术！天才博学者揭露了一切谜团！城镇有危险了！号外！”"],"roles":[{"name":"城镇公告员","team":"townsfolk","ability":"每个夜晚*，你会得知在今天白天时是否有爪牙发起过提名。"}]},"pages/堂吉诃德_Don_Quixote.html":{"name":"堂吉诃德","englishName":"Don Quixote","background":["_\"__看！那个巍峨的巨人，正挥舞着长长的手臂，等着我去挑战！什么？你说那是风车？不不不，你看错了，它们在动，在呼吸，在嘲笑我的迟疑。我的长矛已经准备好了，我的骏马在嘶鸣。别拦我，荣耀在召唤！\"_"],"roles":[{"name":"堂吉诃德","team":"outsider","ability":"一名玩家会被镇民玩家的能力当做恶魔角色（风车），即使你已死亡。你可以从说书人处得知风车是谁，然后风车会改为另一名玩家。"}]},"pages/堤丰之首.html":{"name":"堤丰之首","englishName":"Lord of Typhon","background":["“在宇宙的阴影之中，被遗忘的角落里，星辰向虚空低声诉说着秘密，那些深邃的真理，仅是一瞥就能让肉体凡胎的心智崩溃瓦解。”"],"roles":[{"name":"堤丰之首","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。[邪恶玩家全部邻座，你靠近正中，+1爪牙，-或+任意数量外来者]"}]},"pages/塞壬_Siren.html":{"name":"塞壬","englishName":"Siren","background":["\"嘘…听，这温柔的潮汐是我的呢喃。当我的歌声响起，你们追逐的真相，不过是我布景中的幻光。若我谢幕退场，你们是骤然惊醒？还是跌入更深的虚妄？\""],"roles":[{"name":"塞壬","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡，且你要选择是否永久失去你的下一条能力。镇民玩家的能力一定会产生错误信息。"}]},"pages/士兵.html":{"name":"士兵","englishName":"Soldier","background":["“就像大卫对歌利亚所说，","像忒修斯对米诺陶所说，","也像阿周那对福授所说的那样……","绝不。”"],"roles":[{"name":"士兵","team":"townsfolk","ability":"恶魔的负面能力对你无效。"}]},"pages/夜叉_Yasha.html":{"name":"夜叉","englishName":"Yasha","background":["\"我腹中空虚，千年未满。这空虚不是肉欲，而是你们遗忘的恐惧。白昼你们谈笑自若，可深夜翻身时，后背的凉意是谁在呵气？是我站在枕畔细数你的呼吸。我不急，因为饥饿是最好的调味，等你们不自觉地念出我的名字，那便是我的开宴时刻。\""],"roles":[{"name":"夜叉","team":"minion","ability":"每个夜晚*，你可以选择一名当天被你提名或提名了你的玩家：他死亡，即使你已死亡。"}]},"pages/大小姐_Heiress.html":{"name":"大小姐","englishName":"Heiress","background":["\"叫我大小姐，别叫我小姐，更别叫我姑娘。小姐谁都能叫，大小姐只有我一个。我父亲有三百个仆人、五十座庄园、十二个爵位——你们知道是哪些爵位吗？不知道就闭嘴，别乱叫。叫我大小姐，这是你们唯一需要记住的事。\""],"roles":[{"name":"大小姐","team":"outsider","ability":"当你首次即将死亡时，可能会有两名存活玩家代替你死亡。"}]},"pages/大巫妖_Archlich.html":{"name":"大巫妖","englishName":"Archlich","background":["_\"__我听见了。你灵魂中对死亡的不甘，对力量的饥渴。世人畏惧你，而我，欣赏你。接受这份恩赐。你的尸骸将成为我的第一件杰作，你的意志将化为裁决众生的律法。呼吸吧，这甜美的恐惧…它将是你新生的第一口食粮。__\"_"],"roles":[{"name":"大巫妖","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。每个死亡玩家首次被大巫妖选择时，该玩家要选择两名玩家：他们死亡。"}]},"pages/天使.html":{"name":"天使","englishName":"Angel","background":["“让无罪之人勇于向我所选之人举起手，因为成倍的风暴之怒以及正义终会降临在这群傻瓜身上。”"],"roles":[{"name":"天使","team":"fabled","ability":"对新玩家的死亡负最大责任的人，可能会遭遇一些不好的事情。"}]},"pages/天平师_Scalebearer.html":{"name":"天平师","englishName":"Scalebearer","background":["_\"__这个镇上的贵重交易，七成经过我这杆秤。金银珠宝、麝香人参——都在我这过手。我得罪过很多人。缺斤短两的恨我，弄虚作假的骂我，有人往我家门口泼过脏水。我不搬家。秤在哪，我在哪。秤不准了，我才该搬。\"_"],"roles":[{"name":"天平师","team":"townsfolk","ability":"在你的首个夜晚，你会得知一名玩家：该玩家与他对立阵营的两名玩家距离相等。"}]},"pages/失忆者.html":{"name":"失忆者","englishName":"Amnesiac","background":["“等下，你说了啥？谁？哦，没事了。等下，你说了啥？”"],"roles":[{"name":"失忆者","team":"townsfolk","ability":"你不知道你的能力是什么。每个白天你可以找说书人猜测一次，他会告诉你猜测的有多准确。"}]},"pages/失败的上帝.html":{"name":"失败的上帝","englishName":"Deus Ex Fiasco","background":["“这不是漏洞，是神迹。","这不是失误，是天意。","这不是崩坏，是风格。”"],"roles":[{"name":"失败的上帝","team":"fabled","ability":"每局游戏至少一次，说书人将会出现失误，但会纠正并公开承认自己曾处理有误。"}]},"pages/奇美拉_Chimera.html":{"name":"奇美拉","englishName":"Chimera","background":["\"三个头，六只眼睛，全在看你。我的狮牙在渴望你的喉咙，我的羊角在瞄准你的心脏，我的蛇毒已经在舌尖准备好了。你还在站着发抖？很好，我不喜欢猎物太快倒下。挣扎吧，让我的三个头都有事可做。\""],"roles":[{"name":"奇美拉","team":"demon","ability":"每个夜晚*，你要选择一个除奇美拉以外的恶魔角色（与前两次的选择均不同）：你获得该角色的能力直到下个黄昏。[-1外来者]"}]},"pages/奥赫.html":{"name":"奥赫","englishName":"Ojo","background":["“如同无月之夜里的篝火那般显眼……我看到你了，凡人。”"],"roles":[{"name":"奥赫","team":"demon","ability":"每个夜晚*，你要选择一个角色：他死亡。如果该角色不在场，则由说书人来决定谁会被你杀死。"}]},"pages/女巫.html":{"name":"女巫","englishName":"Witch","background":["“山羊之血，三滴落下。一绺头发，怒意迸发。名字被说出，阴影被放大。左脚踏上荆棘路，莫要回头看它。”"],"roles":[{"name":"女巫","team":"minion","ability":"每个夜晚，你要选择一名玩家：如果他明天白天发起提名，他死亡。如果只有三名存活的玩家，你失去此能力。"}]},"pages/女武神_Valkyrie.html":{"name":"女武神","englishName":"Valkyrie","background":["_\"__站在生与死的边界上，我比任何人都更能体会生命的重量。我见过太多牺牲，太多无谓的死亡。但在你们之中，我仍渴望看到一个不同的终章——它闪耀着智慧的光辉，回荡着勇气的绝响。__\"_"],"roles":[{"name":"女武神","team":"townsfolk","ability":"每个夜晚*，死亡延迟到你同意死亡名单之后才会发生。如果你不同意，当晚有且只有你死亡。"}]},"pages/女爵_Dame.html":{"name":"女爵","englishName":"Dame","background":["_\"__这世上有两种醉。第一种是喝了太多相同的酒，第二种是听了太多不同的谎话。第一种醉，睡一觉就过去了。第二种醉，会渗进你的骨头里。我几乎每天都在和不同的人喝，我知道第一种醉害不了我，但我也知道第二种醉了太多次，就醒不过来了。所以你看我现在到底是醉了，还是醒着？\"_"],"roles":[{"name":"女爵","team":"townsfolk","ability":"每个夜晚，你会得知一个在场的角色。当邪恶玩家死亡时，你醉酒。"}]},"pages/女祭司.html":{"name":"女祭司","englishName":"High Priestess","background":["“在人性的背后，存在着以人性为面具的生活。某些时候生活会摘下面具，以深刻的答案应对深刻的问题。”"],"roles":[{"name":"女祭司","team":"townsfolk","ability":"每个夜晚，你会得知一名说书人认为你最应该与其交流的玩家。"}]},"pages/女舍监.html":{"name":"女舍监","englishName":"Matron","background":["“费瑟伯顿小姐，你能不能安静点。卢瑟福少爷，请只用四根手指端起茶杯。我知道你是九个孩子的父亲，但无论是年龄还是其他什么原因，都不能成为你没礼貌的借口。”"],"roles":[{"name":"女舍监","team":"traveller","ability":"每个白天，你可以选择至多三对玩家交换座位。玩家不能离开座位私聊。"}]},"pages/女裁缝.html":{"name":"女裁缝","englishName":"Seamstress","background":["“你听到那个穿羊绒大衣的家伙对我们小贝尔说什么了吗？他说……‘好’？哎，行吧，和哈利还有那个杂耍艺人那一出相比，这算不了什么。说什么？我可不说，我又不是什么长舌妇。”"],"roles":[{"name":"女裁缝","team":"townsfolk","ability":"每局游戏限一次，在夜晚时，你可以选择除你以外的两名玩家：你会得知他们是否为同一阵营。"}]},"pages/奸佞.html":{"name":"奸佞","englishName":"Geehnyn","background":["“今汝先赴死，便让圣上下旨将其密斩。”"],"roles":[{"name":"奸佞","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。如果你今天白天没有投票，今晚你可以行动两次。"}]},"pages/奸奇_Tzeentch.html":{"name":"奸奇","englishName":"Tzeentch","background":["\"不必费力辨认我的轮廓，此刻站在你面前的模样，下一秒便会消融扭曲。我精通一切伪装，我在人群里埋下无数虚假分身。所谓忠诚、立场、善恶，全是用来蒙蔽凡俗的外壳。我从不靠蛮力征服，我用智慧让盟友反目、让信念崩塌。永不停歇的变化才是唯一真实，而我，就是万变之主。\""],"roles":[{"name":"奸奇","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。当你得知恶魔信息时，会有更多的伪装，你要选择其中一个：你获得该角色的能力。"}]},"pages/姑获鸟.html":{"name":"姑获鸟","englishName":"Guhornia","background":["“夜食魂魄，喜盗子而养。”"],"roles":[{"name":"姑获鸟","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。你可能会拥有上一个死于处决的爪牙的能力。"}]},"pages/孟婆.html":{"name":"孟婆","englishName":"Meng Po","background":["“世人皆知忘川水，无人回味孟婆汤。”"],"roles":[{"name":"孟婆","team":"minion","ability":"每个夜晚*，你要选择一名玩家：如果他存活，那么他要选择让自己失去能力，或死亡并保留能力直到下个黄昏。"}]},"pages/学徒.html":{"name":"学徒","englishName":"Apprentice","background":["“这么多年来，我一路上不停地在学习各种各样的手艺。你问我学的是什么手艺？简单说都是一些普通的手艺，没什么好担心的，至少现在不必。”"],"roles":[{"name":"学徒","team":"traveller","ability":"在你的首个夜晚，如果你是善良的，你会获得一个镇民角色的能力；如果你是邪恶的，你会获得一个爪牙角色的能力。"}]},"pages/守夜人.html":{"name":"守夜人","englishName":"Nightwatchman","background":["“夜晚寒冷而孤独，但我有月亮、星星、清风，还有鹅卵石上皮靴的轻柔撞击声与我作伴。远处，有烛光正在一扇昏暗的窗户后面闪烁……”"],"roles":[{"name":"守夜人","team":"townsfolk","ability":"每局游戏限一次，在夜晚时，你可以选择一名玩家：他会得知你是守夜人。"}]},"pages/守鸦人.html":{"name":"守鸦人","englishName":"Ravenkeeper","background":["“我的鸟儿们会替我复仇的！飞吧！飞吧，我尽职的小可爱！","去到庄园和溪边！去到小巷和集会所里！快飞吧！”"],"roles":[{"name":"守鸦人","team":"townsfolk","ability":"如果你在夜晚死亡，你会被唤醒，然后你要选择一名玩家：你会得知他的角色。"}]},"pages/官员.html":{"name":"官员","englishName":"Bureaucrat","background":["“请在这签名，还有这里，还有这，还...有这。如果每个人的签名都清晰可辨，在今天就应该可以把所有文件都整理统计好。这种简单的文书工作，我们已经很久没犯错了。从昨天中午到现在都没有，如果没记错的话……”"],"roles":[{"name":"官员","team":"traveller","ability":"每个夜晚，你要选择除你以外的一名玩家：明天白天，他的投票算作三票。"}]},"pages/宠妃.html":{"name":"宠妃","englishName":"Favoretteen","background":["“春宵苦短日高起，从此君王不早朝。”"],"roles":[{"name":"宠妃","team":"townsfolk","ability":"每局游戏限一次，说书人会在关于你的事情上打破规则。随后，你会秘密得知说书人为此做了什么。"}]},"pages/寡妇.html":{"name":"寡妇","englishName":"Widow","background":["“还要再来点酒吗？麦角酒庄的这款07年的窖藏非常特别。是的，的的确确很特别。”"],"roles":[{"name":"寡妇","team":"minion","ability":"在你的首个夜晚，你能查看魔典并选择一名玩家：他中毒。随后，始终会有一名善良玩家知道寡妇在场。"}]},"pages/将军.html":{"name":"将军","englishName":"General","background":["“我没时间跟你谈条件。”"],"roles":[{"name":"将军","team":"townsfolk","ability":"每个夜晚，你会得知说书人认为哪个阵营当前更有优势（善良/邪恶/均势）。"}]},"pages/小怪宝.html":{"name":"小怪宝","englishName":"Lil'Monsta","background":["“步骤一：要变得可爱。步骤二：要统治世界。步骤三：先来点藻餐。”"],"roles":[{"name":"小怪宝","team":"demon","ability":"每个夜晚，所有爪牙要秘密决定由哪名玩家来照看小怪宝并且“是恶魔”。每个夜晚*，可能会有一名玩家死亡。[+1爪牙]"}]},"pages/小恶魔.html":{"name":"小恶魔","englishName":"Imp","background":["“我们必须让自己的头脑保持敏锐，刀刃保持锋利。","邪恶在我们之中穿行，想要不择手段地摧毁我们的善良。","那些愚蠢之辈，把我们美丽的小镇给毁了。不要相信任何人。","但如果你一定要相信某人，请相信我。”"],"roles":[{"name":"小恶魔","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。如果你以这种方式自杀，一名爪牙会变成小恶魔。"}]},"pages/小提琴手.html":{"name":"小提琴手","englishName":"Fiddler","background":["“我敢用命打赌你在小提琴比赛中肯定赢不了我，你这个独眼的呆子！我们之后再一起出去好好地喝上一杯，享受酒吧里的绝伦美曲，沉浸其中，直到隔天醒来连为什么我的鞋子会套在你的脚上都不知道。”"],"roles":[{"name":"小提琴手","team":"fabled","ability":"每局游戏限一次，恶魔可以秘密选择一名对立阵营的玩家，所有玩家要表决：这两名玩家中谁的阵营获胜。（平局邪恶阵营获胜）"}]},"pages/小精灵.html":{"name":"小精灵","englishName":"Pixie","background":["“绕着花园转圈圈，女孩跑得疯癫癫。男孩树上荡秋千，","小精灵在谁心间？淑女微笑小镇边，贵族抡斧树长眠。","容貌相似难分辨，谜底揭晓圣光现：小精灵呀是神仙。”"],"roles":[{"name":"小精灵","team":"townsfolk","ability":"在你的首个夜晚，你会得知一个在场的镇民角色。如果你“疯狂”地证明你是该角色，当他死亡时你获得该角色的能力。"}]},"pages/屠夫.html":{"name":"屠夫","englishName":"Butcher","background":["“这口感好像鸡肉..……请再来一份。”"],"roles":[{"name":"屠夫","team":"traveller","ability":"每个白天，首次处决后，你可以再次发起提名。"}]},"pages/巡察.html":{"name":"巡察","englishName":"Patrolman","background":["“平天下不平之事，安人间不安之心。”"],"roles":[{"name":"巡察","team":"townsfolk","ability":"每个夜晚*，你要选择除你以外的两个善良角色：如果他们都存活，他们当晚不会死亡。"}]},"pages/巡山人.html":{"name":"巡山人","englishName":"Huntsman","background":["“我的小屋温暖而坚固。我的斧头靠在门边，我的靴子在火旁烘干，我的麋鹿肉正在锅里细火慢炖……听听！有尖叫声在山谷中回荡！或许雨水、泥泞和寒风会掩盖狼的气味，但我熟悉山路，我的步伐坚定。我来了。”"],"roles":[{"name":"巡山人","team":"townsfolk","ability":"每局游戏限一次，在夜晚时，你可以选择一名存活的玩家：如果你选中了落难少女，她会变成一个不在场的镇民角色。[+落难少女]"}]},"pages/工程师.html":{"name":"工程师","englishName":"Engineer","background":["“如果它弯曲了，那可就太棒了。但如果它断裂了，那么它就必须得修一修了。”"],"roles":[{"name":"工程师","team":"townsfolk","ability":"每局游戏限一次，在夜晚时，你可以选择让恶魔变成你选择的恶魔角色，或让所有爪牙变成你选择的爪牙角色。"}]},"pages/巫医_Witch_Doctor.html":{"name":"巫医","englishName":"Witch Doctor","background":["“当蛇杖叩响大地，丛林烟雾升起，请细嗅这曼陀罗与乌头交织的迷香。莫要抗拒这神赐，这是金刚不坏，这是心醉神迷，这是世间极乐。”"],"roles":[{"name":"巫医","team":"minion","ability":"每个夜晚，你要选择一名玩家：他中毒且死亡延迟，直到你改变选择。"}]},"pages/巫女_Miko.html":{"name":"巫女","englishName":"Miko","background":["\"神社前的古木告诉我，有脏东西混进了镇子。我来替树完成它做不到的事——把根须扎进泥土，把邪气拔出来，还给清风。放心，不疼的。被净化过的灵魂，会在风里闻到梅花香。\""],"roles":[{"name":"巫女","team":"townsfolk","ability":"每个夜晚，你要选择两名邻座的其他玩家：你会得知他们之中是否有爪牙。"}]},"pages/巫师.html":{"name":"巫师","englishName":"Wizard","background":["“每一个人，都是一颗星星，爱情让它们产生联系，而意志决定了它们的轨迹。”"],"roles":[{"name":"巫师","team":"minion","ability":"每局游戏限一次，在白天时，你可以拜访说书人进行许愿：如果愿望兑现，会付出相应代价或留下线索。"}]},"pages/巫毒师.html":{"name":"巫毒师","englishName":"Voudon","background":["“欢迎。先坐下来，深呼吸。进入活死人之地，以他眼视之，以他声言之。借万灵之音。”（第一句和最后一句为海地语）"],"roles":[{"name":"巫毒师","team":"traveller","ability":"只有你和死亡的玩家可以投票，且投票不需要使用投票标记。忽略票数需要过半的要求。"}]},"pages/帕克_Puck.html":{"name":"帕克","englishName":"Puck","background":["_“__来吧来吧！让我们把这场严肃的推理变成游乐场！我保证——（眨眨眼）会让一切变得特别特别'有趣'！快让我看看，今天谁会幸运地成为我的新玩具呢？__”_"],"roles":[{"name":"帕克","team":"minion","ability":"每局游戏限一次，在夜晚时*，你可以选择一个非恶魔角色：他死亡。如果该角色不在场，你要再选择一名玩家：他变成该角色。"}]},"pages/帽匠.html":{"name":"帽匠","englishName":"Hatter","background":["“一顶帽子。凉顶帽子。三顶帽子。帽子开会。刺顶帽子。污顶帽子。六顶帽子。戴好帽子。”"],"roles":[{"name":"帽匠","team":"outsider","ability":"如果你死亡，当晚爪牙和恶魔玩家可以选择变成新的爪牙和恶魔角色。"}]},"pages/幸运星_Lucky_Star.html":{"name":"幸运星","englishName":"Lucky Star","background":["_\"叮咚！门铃响了，你开门会看到一盒巧克力，上面写着‘给今天最幸运的人’。尝一颗，甜到明天，吃完还有好运气！__\"_"],"roles":[{"name":"幸运星","team":"fabled","ability":"抽到此标记的玩家会得到一些“好处”且要再抽一个标记。[此标记会被额外加入配置]"}]},"pages/幻_Illus.html":{"name":"幻","englishName":"Illus","background":["\"你今晚会做一个梦。梦里你会见到一个你深爱的人。你会吻她，你会拥抱她，你会闻到她头发里令人安心的气味。然后你会醒来。但醒来后的世界，她的气味会变成腐肉和胆汁。每一次呼吸你都会呕吐。但她还会对你微笑。她会说'怎么了，亲爱的？'然后你会忘记你曾经爱过任何不是她的东西。而我，就是那个不是她的东西。\""],"roles":[{"name":"幻","team":"minion","ability":"如果与你邻座的玩家都是存活的，镇民玩家的能力一定会产生错误信息。"}]},"pages/店小二.html":{"name":"店小二","englishName":"Waiter","background":["“客官您里边儿请嘿！是打尖儿呐还是住店啊？”"],"roles":[{"name":"店小二","team":"townsfolk","ability":"在你的首个夜晚，你会得知两名善良玩家。他们之中会有一人醉酒，即使你已死亡。"}]},"pages/异教领袖.html":{"name":"异教领袖","englishName":"Cult Leader","background":["“他们自诩聪明，却成了傻瓜。”"],"roles":[{"name":"异教领袖","team":"townsfolk","ability":"每个夜晚，你会转变为与你邻近的一名存活的玩家的阵营。每个白天，你可以提议所有玩家加入你的教派，如果所有善良玩家同意加入，你的阵营获胜。"}]},"pages/异术士.html":{"name":"异术士","englishName":"Zenomancer","background":["“有人说，宇宙是动态的，而非静止，这一切都承载于驮着巨龟的巨龟之上，层层叠叠的巨龟，我的朋友，永无止境。”"],"roles":[{"name":"异术士","team":"loric","ability":"一名或多名玩家各自拥有一个目标。当达成目标后，他会获得一条正确信息。"}]},"pages/异端分子.html":{"name":"异端分子","englishName":"Heretic","background":["“冰雹砸向了屋顶，将大教堂窗户的玻璃打得粉碎，然后融化进泥土里，就像沙漠里烈日下奄奄一息的羔羊。这就是疯子的寓言。”"],"roles":[{"name":"异端分子","team":"outsider","ability":"所有本来获胜的玩家，改为落败；所有本来落败的玩家，改为获胜，即使你已死亡。"}]},"pages/弄臣.html":{"name":"弄臣","englishName":"Fool","background":["“……然后国王说道：‘什么？！我甚至从未有过一条橡胶马裤，更别提一门奶油大炮了！’嗬嗬！欢乐一日！”"],"roles":[{"name":"弄臣","team":"townsfolk","ability":"当你首次将要死亡时，你不会死亡。"}]},"pages/引路人.html":{"name":"引路人","englishName":"Guide","background":["“船缓难行，有不洁之气。”"],"roles":[{"name":"引路人","team":"townsfolk","ability":"每个夜晚，你要选择至多三名玩家：你会得知今晚是否有邪恶玩家的能力选择或影响了他们之中的玩家。"}]},"pages/德鲁伊_Druid.html":{"name":"德鲁伊","englishName":"Druid","background":["\"自然里有捕食者，也有猎物。狼吃鹿，鹿吃草，草吃土里的骨头。每一张嘴都在吞食另一张嘴。这不是残忍，是平衡。但有一种捕食者，自然没有给它安排天敌。它吃的时候，不为了活，不为了饿，只是为了取乐。自然未曾备好枷锁，那便由我，来成为它的天敌。\""],"roles":[{"name":"德鲁伊","team":"townsfolk","ability":"如果与你邻近的两名存活玩家的阵营相同，恶魔只能攻击他们。"}]},"pages/心上人.html":{"name":"心上人","englishName":"Sweetheart","background":["“我永远也忘不掉她……永远……”"],"roles":[{"name":"心上人","team":"outsider","ability":"当你死亡时，会有一名玩家开始醉酒。"}]},"pages/忍者_Ninja.html":{"name":"忍者","englishName":"Ninja","background":["_\"__我已经在房梁上蹲了三天。你们吃饭的时候我在看着你们，你们密谈的时候我在听着你们。我不急。我等的只是你终于放松警惕的那一秒钟——然后，一阵风，一道影，一声极轻的倒地声。杀人从来不需要力气，只需要抓住一刹那的时机。__\"_"],"roles":[{"name":"忍者","team":"townsfolk","ability":"每个白天，如果你是首位或末位发起提名的玩家，且被你提名的玩家是邪恶的，他会在当晚死亡。"}]},"pages/忘川_Lethe.html":{"name":"忘川","englishName":"Lethe","background":["_\"世人皆惧我，道我洗尽前尘。可他们不知，忘了罪孽，便也忘了清白。此间最深的惩罚，不是记得自己做错了什么，而是再也想不起自己曾做过什么。__\"_"],"roles":[{"name":"忘川","team":"fabled","ability":"可能出现：恶魔与爪牙会以为自己是善良角色，说书人会替代他们使用能力。有且只有所有邪恶玩家均死亡时，游戏才会结束，所有玩家获胜。"}]},"pages/怪咖.html":{"name":"怪咖","englishName":"Deviant","background":["“这句好笑的话确实是那位女士说的。”"],"roles":[{"name":"怪咖","team":"traveller","ability":"如果你表现得很有趣，当天你不能被流放。"}]},"pages/恐惧之灵.html":{"name":"恐惧之灵","englishName":"Fearmonger","background":["“当心不要长久地凝视深渊，以免深渊也同样回望着你。”"],"roles":[{"name":"恐惧之灵","team":"minion","ability":"每个夜晚，你要选择一名玩家：如果你提名他且他被处决，他的阵营落败。当你首次选择或更换目标时，所有玩家都会得知你选择了新的玩家。"}]},"pages/恐虐_Khorne.html":{"name":"恐虐","englishName":"Khorne","background":["\"你太胆小了，连刀刃都在发抖，你根本不配站在这里，你玷污了你的旗帜和荣耀。那些敢于直视我、向我冲来、在倒下的瞬间还试图反扑的勇士才配让我为他们哀悼，哪怕只有片刻。而你？你只配被我顺手一刀剁倒，无人知晓，连苍蝇都懒得落在你的尸体上。\""],"roles":[{"name":"恐虐","team":"demon","ability":"每个夜晚*，你要选择两名玩家：他们死亡。如果有善良玩家在白天死亡，当晚你选择的其中一名玩家不会死亡。"}]},"pages/恶堕_Corruptus.html":{"name":"恶堕","englishName":"Corruptus","background":["“拥抱黑暗吧，异乡人，我会将你的死亡与怮哭化作铠甲，将你受过的排挤与恶意化作刀刃，然后你要随我一起，向他们复仇。”"],"roles":[{"name":"恶堕","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他必死。死亡外来者的胜负条件与你相同，即使你已死亡。[1名或2名外来者在场]"}]},"pages/悟道者.html":{"name":"悟道者","englishName":"Enlightened One","background":["“道从本心，众生平等。六道轮回，一叶障目。”"],"roles":[{"name":"悟道者","team":"townsfolk","ability":"你以为你是一个外来者，但你实际上不是。如果有邪恶玩家的能力选择了你或对你产生了影响，在该效果生效前你会变成一个不在场的镇民角色。"}]},"pages/戏子.html":{"name":"戏子","englishName":"Actor","background":["“镜花水月，戏中若梦。然凡梦者，皆有觉时。”"],"roles":[{"name":"戏子","team":"townsfolk","ability":"所有戏子互相认识。不论在场的戏子数量多少或存活与否，胜负结果会被对调。[所有善良玩家都是戏子]"}]},"pages/戏子（改）.html":{"name":"戏子","englishName":"Actor v2.0","background":["“镜花水月，戏中若梦。然凡梦者，皆有觉时。”"],"roles":[{"name":"戏子","team":"townsfolk","ability":"所有戏子互相认识。不论在场的戏子数量多少或存活与否，胜负结果会被对调。[所有善良玩家都是戏子]"}]},"pages/戏法师.html":{"name":"戏法师","englishName":"Alsaahir","background":["“我在这里，因为你在这里；","我在这里，所以你在这里。”"],"roles":[{"name":"戏法师","team":"townsfolk","ability":"每个白天限一次，你可以公开猜测谁是爪牙，谁是恶魔。如果你猜对，善良阵营获胜。"}]},"pages/打更人.html":{"name":"打更人","englishName":"Firewatcher","background":["“天干物燥，小心火烛！”"],"roles":[{"name":"打更人","team":"townsfolk","ability":"每个夜晚*，你要猜测今晚第一个死亡的玩家与你的距离。如果你猜测正确，改为除你以外的所有玩家今晚不会死亡，但你可能会死亡。"}]},"pages/投毒者.html":{"name":"投毒者","englishName":"Poisoner","background":["“将α化合物加入到β化合物中……","别！太！多！”"],"roles":[{"name":"投毒者","team":"minion","ability":"每个夜晚，你要选择一名玩家：他在当晚和明天白天中毒。"}]},"pages/报丧女妖.html":{"name":"报丧女妖","englishName":"Banshee","background":["“红是你的发色，蓝是你的瞳色，死是你的褪色。”（爱尔兰盖尔语）"],"roles":[{"name":"报丧女妖","team":"townsfolk","ability":"如果恶魔杀死了你，所有玩家都会得知此事。从现在开始，你每天可以发起两次提名，每次投票时可以投两票。"}]},"pages/捕虫少年_Bug_Catcher.html":{"name":"捕虫少年","englishName":"Bug Catcher","background":["_\"蟋蟀、螽斯、独角仙！蜻蜓、螳螂、萤火虫！蝴蝶、蚂蚱、金龟子！全部到我网里来！...__哈！抓到你了！\"_"],"roles":[{"name":"捕虫少年","team":"townsfolk","ability":"如果你提名了一名其他玩家，在当晚你会被唤醒并得知他是否为恶魔。"}]},"pages/捣蛋鬼_Rascal.html":{"name":"捣蛋鬼","englishName":"Rascal","background":["\"渔夫说他明早要赶集把鱼卖了，女裁缝说她午休时懒得锁门，艺术家今晚去喝花酒了。这些我都偷听到了！明天一早，渔夫掀开鱼筐，里面只有三只蛤蟆。女裁缝掰不开她被胶水黏上的剪刀。还有还有！最棒的是艺术家醒来会摔个狗啃泥——他的鞋带都被我绑在一起了！\""],"roles":[{"name":"捣蛋鬼","team":"outsider","ability":"在你的首个夜晚与首个白天，镇民玩家的能力一定会产生错误信息。"}]},"pages/探戈_Tango.html":{"name":"探戈","englishName":"Tango","background":["_“__今晚的领舞者是——红唇女郎！让我们掌声欢迎红唇女郎上台领舞！什么？她没来？”_"],"roles":[{"name":"探戈","team":"fabled","ability":"在初始设置时，说书人会公开指定一个角色：如果该角色在场，会增加或减少一个外来者。"}]},"pages/掮客.html":{"name":"掮客","englishName":"Broker","background":["“买卖不成情义在。”"],"roles":[{"name":"掮客","team":"townsfolk","ability":"每个夜晚，你要选择两名存活玩家：如果他们阵营相同，今晚任何玩家使用自身能力选择他们之一作为目标时，改为选中另一名玩家。"}]},"pages/提刑官.html":{"name":"提刑官","englishName":"Inspector","background":["“明见万里，烛照奸邪，虽隐恶必察。”"],"roles":[{"name":"提刑官","team":"townsfolk","ability":"在你首次提名玩家后，你会在当晚得知他的角色。外来者会被你的能力当作爪牙或恶魔角色。"}]},"pages/提线木偶.html":{"name":"提线木偶","englishName":"Marionette","background":["“给出命令，下达命令。只需要这样做就足够了。”"],"roles":[{"name":"提线木偶","team":"minion","ability":"你以为你是一个善良角色，但其实你不是。恶魔会知道你是提线木偶。[提线木偶会与恶魔邻座]"}]},"pages/摆渡人.html":{"name":"摆渡人","englishName":"Ferryman","background":["“当正义的梦想到来之时，它会带着真理的重量。”"],"roles":[{"name":"摆渡人","team":"fabled","ability":"在游戏的最后一天，所有已死亡玩家会重新获得投票标记。"}]},"pages/政客.html":{"name":"政客","englishName":"Politician","background":["“我很高兴你提出了这个问题。是的，我真的很高兴。但我仍然认为，问题的核心应该是在于……”"],"roles":[{"name":"政客","team":"outsider","ability":"如果你是对你的阵营落败负最大责任的人，你转变阵营并获胜，即使你已死亡。"}]},"pages/故障机器人_FaultBot.html":{"name":"故障机器人","englishName":"FaultBot","background":["\"咔哒咔哒——报错！报错！\""],"roles":[{"name":"故障机器人","team":"townsfolk","ability":"每个夜晚，你会得知当天其他镇民玩家的能力是否均正常生效。"}]},"pages/教授.html":{"name":"教授","englishName":"Professor","background":["“过程很简单。将液压植入器连接到改良型气矩阵放大器上，加入20CC的伪多拉芬，让他的参数Z保持在20%以上，你丈夫就会重新活蹦乱跳。","现在，我们需要的仅仅是一次雷击。”"],"roles":[{"name":"教授","team":"townsfolk","ability":"每局游戏限一次，在夜晚时*，你可以选择一名死亡的玩家：如果他是镇民，你会将他起死回生。"}]},"pages/教父.html":{"name":"教父","englishName":"Godfather","background":["“通常来说，这只是件小事。但在你侮辱我女儿时，你就侮辱了我。你侮辱我，就侮辱了我的家族。你真的应该更小心些——要是你不幸发生意外事故，那就太遗憾了。”"],"roles":[{"name":"教父","team":"minion","ability":"在你的首个夜晚，你会得知有哪些外来者角色在场。如果有外来者在白天死亡，你会在当晚被唤醒并且你要选择一名玩家：他死亡。[-1或+1外来者]"}]},"pages/教皇.html":{"name":"教皇","englishName":"Pope","background":["“……至美之名。”"],"roles":[{"name":"教皇","team":"loric","ability":"会有重复的善良角色在场。他们也可能是恶魔的伪装。"}]},"pages/数学家.html":{"name":"数学家","englishName":"Mathematician","background":["“任何连续的，且能进行定量初等运算的形式系统X，都具有不完全性。也就是说，在这个形式系统X内存在一些命题，这些命题既不能被证明为真，也不能被证明为否。所以，你喝醉了。”"],"roles":[{"name":"数学家","team":"townsfolk","ability":"每个夜晚，你会得知有多少名玩家的能力因为其他角色的能力而未正常生效。(从上个黎明到你被唤醒时）"}]},"pages/敲钟人_Bellringer.html":{"name":"敲钟人","englishName":"Bellringer","background":["_\"__它很老了，我也老了。但它依然能响，响到整个镇子都能听见。有人问我怕不怕，我说，敲钟的人不怕声音散尽，怕的是没人能听懂钟的声音。明天这趟钟，我大概是回不来了。也好。我用一生的声音，换一个刹那的真相。值了。\"_"],"roles":[{"name":"敲钟人","team":"townsfolk","ability":"在你首次发起提名时，你可以公开质问一次被提名的玩家他是否为某个角色：如果他说谎，你立即被处决。"}]},"pages/斯芬克斯_Sphinx.html":{"name":"斯芬克斯","englishName":"Sphinx","background":["“凡人的视野总被谎言蒙蔽，而我的凝视能穿透一切伪装。当命运的诘问降临时，唯有洞察真理者方能幸存。”"],"roles":[{"name":"斯芬克斯","team":"minion","ability":"每个夜晚，你要选择一个角色：下个白天，如果该角色在场，他会被公开询问一个是非问题。没有答对的玩家可能会被处决。"}]},"pages/方古.html":{"name":"方古","englishName":"Fang Gu","background":["“你那高墙和锐器不过是虚无缥缈的泡影。”"],"roles":[{"name":"方古","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。被该能力杀死的外来者改为变成邪恶的方古且你代替他死亡，但每局游戏仅能成功转化一次。[+1外来者]"}]},"pages/方士.html":{"name":"方士","englishName":"Arythmomancer","background":["“观星象，窥天道。”"],"roles":[{"name":"方士","team":"townsfolk","ability":"在你的首个夜晚，你要选择一个数字。在该数字对应的那一个夜晚，你会得知对应数量的在场角色。"}]},"pages/旅店老板.html":{"name":"旅店老板","englishName":"Innkeeper","background":["“到里头来，美丽的旅者，放松筋骨，好好歇息。尽管饮酒作乐，黑暗之物今夜无法伤你分毫。”"],"roles":[{"name":"旅店老板","team":"townsfolk","ability":"每个夜晚*，你要选择两名玩家：他们当晚不会死亡，但其中一人会醉酒到下个黄昏。"}]},"pages/无神论者.html":{"name":"无神论者","englishName":"Atheist","background":["“让我们驱散这不必要的猜忌和愚蠢的妄想吧。这发生的一切都有一个完全合理的解释。是的，现在正有一个茶杯在围绕着地球旋转，它太小了，所以你们都无法看见。但我会真实地用我的手端起这真实的瓷器，饮下这茶。”"],"roles":[{"name":"无神论者","team":"townsfolk","ability":"说书人可以打破游戏规则。如果说书人被处决，善良阵营获胜，即使你已死亡。[无邪恶角色在场]"}]},"pages/晓_Dawnyx.html":{"name":"晓","englishName":"Dawnyx","background":["\"你们把黎明画成金色的，真温柔。我眼中的黎明是紫色的——淤血的颜色。那是夜被活活吸干时留下的淤青。恶魔就在这片淤青里苏醒，吸食破晓前最后一滴黑暗。你们以为光来了，邪魔就会退散？不。光来了，我才能看清你们的脸。现在，天亮了，游戏重新开始。\""],"roles":[{"name":"晓","team":"minion","ability":"善良阵营在你存活时无法获胜。死于处决的恶魔会在黎明时重获能力。"}]},"pages/普卡.html":{"name":"普卡","englishName":"Pukka","background":["“您人真好，发生了这样的事情，您还愿意让我来您金碧辉煌的家里做客。我很抱歉，刚才不小心划伤了您。这是一点点赔礼，没事的，请收下吧，把这根金牙签当做我那卑微的歉意吧。”"],"roles":[{"name":"普卡","team":"demon","ability":"每个夜晚，你要选择一名玩家：他中毒。上个因你的能力中毒的玩家会死亡并恢复健康。"}]},"pages/暴乱.html":{"name":"暴乱","englishName":"Riot","background":["“革命万岁！我的革命！”（西班牙语）"],"roles":[{"name":"暴乱","team":"demon","ability":"在第三个白天，所有爪牙会变成暴乱，当天被提名的玩家会立即死亡且必须再次提名一名存活的玩家。"}]},"pages/暴君.html":{"name":"暴君","englishName":"Pok-kkun","background":["“天子之怒，伏尸百万，流血千里。”"],"roles":[{"name":"暴君","team":"demon","ability":"每个夜晚*，你可以选择至多两名玩家：他们死亡。你选择的玩家数量不能与上个夜晚死亡的玩家数量相同（超过二人时算作二人）。"}]},"pages/暴风捕手.html":{"name":"暴风捕手","englishName":"Storm Catcher","background":["“在黎明时分，庙宇那被拉长的影子爬上了泉眼。而在黄昏时分，方尖塔将刺目的红光遮挡，让拱道下方的暖流冷却。所有的线索都汇聚于此。风暴将至，而在这苹果树之间，这耀眼、葱翠又圣洁的地方，定是那暴风眼。”"],"roles":[{"name":"暴风捕手","team":"loric","ability":"游戏开始时，你要宣布一个善良角色。如果该角色在场，他只能死于处决，但所有邪恶玩家会在首个夜晚得知他是哪一名玩家。"}]},"pages/替罪羊.html":{"name":"替罪羊","englishName":"Scapegoat","background":["“晚上好！感谢你们邀请我来舞厅。虽然我不是本地人，但你们看起来个个都慈眉善目的，我的天呐。我相信我们一定可以打成一片的。不过这些绳子是干嘛的？”"],"roles":[{"name":"替罪羊","team":"traveller","ability":"如果你的阵营的一名玩家被处决，你可能会代替他被处决。"}]},"pages/月之子.html":{"name":"月之子","englishName":"Moonchild","background":["“天蝎座侧身遥望恋人，此刻即为抉择进行之时。","以白银拂过我的掌心，你的宿命将在此地揭示。","以钢铁穿过我的咽喉，群星在上你将追悔莫及。”"],"roles":[{"name":"月之子","team":"outsider","ability":"当你得知你死亡时，你要公开选择一名存活的玩家。如果他是善良的，在当晚他会死亡。"}]},"pages/月光骑士_Lunar_Knight.html":{"name":"月光骑士","englishName":"Lunar Knight","background":["“在没有血腥味的静谧晚上，小鹿跳过溪涧，月光透过纱窗，而我的枪尖穿过罪恶的胸膛。”"],"roles":[{"name":"月光骑士","team":"townsfolk","ability":"每个夜晚*，如果当天无人死于处决，你会被唤醒并要选择一名玩家：如果他是爪牙，他死亡。"}]},"pages/木乃伊_Mummy.html":{"name":"木乃伊","englishName":"Mummy","background":["_\"阿努比斯称量了我的灵魂，准许我重返人间。我的裹尸布下没有私心，只有从冥界带回的冰冷答案。__\"_"],"roles":[{"name":"木乃伊","team":"townsfolk","ability":"如果你死于邪恶玩家发起的提名处决或能力，审判日降临时，你复活。"}]},"pages/末日预言者.html":{"name":"末日预言者","englishName":"Doomsayer","background":["“而在第七天，洪水和瘟疫将席卷渡鸦村！死者终会复活，生者将遭挫折！哦！真是天灾人祸啊！哦！真是不幸的一天！只有付出巨大的牺牲才能熬过这一切！诺斯特罗斯的贤者是这么说的，我也是这么说的。”"],"roles":[{"name":"末日预言者","team":"fabled","ability":"如果大于等于四名玩家存活，每名当前存活的玩家可以公开要求你杀死一名与他阵营相同的玩家（每名玩家限一次）。"}]},"pages/杂技演员.html":{"name":"杂技演员","englishName":"Acrobat","background":["“列位看官，请扶好帽盔，我将逆天而行，踏空起舞！身如飞燕，胆若雷霆，只为博君一笑一惊！”"],"roles":[{"name":"杂技演员","team":"townsfolk","ability":"每个夜晚*，你要选择一名玩家：如果当晚他醉酒或中毒，你死亡。"}]},"pages/杂耍艺人.html":{"name":"杂耍艺人","englishName":"Juggler","background":["“下一场表演，我需要一朵花、一袋豆子、一条玩具蛇、一支画笔、和一个电动的树篱修剪机。不过我得和你说，宝贝，这可能是我最后的表演了哦。”"],"roles":[{"name":"杂耍艺人","team":"townsfolk","ability":"在你的首个白天，你可以公开猜测任意玩家的角色最多五次。在当晚，你会得知猜测正确的角色数量。"}]},"pages/村夫.html":{"name":"村夫","englishName":"Village Idiot","background":["“玫瑰花是蓝色哒！草桂花是红色哒！哦豁，俺说反啦！”"],"roles":[{"name":"村夫","team":"townsfolk","ability":"每个夜晚，你要选择一名玩家：你会得知他的阵营。[+0~2村夫，复数村夫中有一人醉酒]"}]},"pages/枪手.html":{"name":"枪手","englishName":"Gunslinger","background":["“是时候得有人自己动手了。那个人...就是我。”"],"roles":[{"name":"枪手","team":"traveller","ability":"每个白天，当首次投票被统计后，你可以选择一名刚投过票的玩家：他死亡。"}]},"pages/梼杌.html":{"name":"梼杌","englishName":"Tao Wu","background":["“有兽焉，其状如虎而大，毛长两尺，人面虎足，口牙，尾长一丈八尺，扰乱荒中，名梼杌。”"],"roles":[{"name":"梼杌","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。当你将要死亡时，改为一名存活且具有能力的爪牙失去能力。你不会得知恶魔信息。"}]},"pages/歌伶.html":{"name":"歌伶","englishName":"Diva","background":["“商女不知亡国恨，隔江犹唱后庭花。”"],"roles":[{"name":"歌伶","team":"townsfolk","ability":"每局游戏限一次，在白天时，你可以提议所有玩家观看你的演出，并从同意参加的玩家中选择你的观众。如果恶魔成为了观众，你会在当晚死亡。"}]},"pages/武僧_MarMonk.html":{"name":"武僧","englishName":"MarMonk","background":["_\"竹迎__霜天意自昂，风愈摧枝气愈强。虚心纳得风云势，一寸柔怀并八荒。\"_"],"roles":[{"name":"武僧","team":"townsfolk","ability":"当恶魔攻击你时，一名邪恶玩家会替代你被攻击。"}]},"pages/死眠少女_Somnmaid.html":{"name":"死眠少女","englishName":"Somnmaid","background":["_\"我每晚都会祈祷，求神让我遇见一个‘不该被拯救’的人。你终于来了。你对我的好奇，和我对你的好奇，是同一根绳子的两端。你在想：‘这个女人会不会在我面前发抖？’我在想：‘这个男人会不会在我面前跪下？’我们各怀心事，可只要我们靠得够近，那些心事就会变成同一种温度。留下来，哪怕只留一夜，让我为你点一根不需要熄灭的蜡烛。__\"_"],"roles":[{"name":"死眠少女","team":"townsfolk","ability":"当你首次被恶魔攻击时，你不会死亡，并会得知该恶魔的角色。"}]},"pages/殉情者_Loverbound.html":{"name":"殉情者","englishName":"Loverbound","background":["\"他们说xun情是一起离开。不对。xun情是你离开后我还在，但每一步都踩在你走过的路上。你走太快了，我追不上。但没关系，这路总有尽头。到那天，我不会说再见。我会说：等等我，这回换我走在前面。我终于明白，xun情从来不是两个人的死亡，而是一个人的生命太长，长到只能用另一种方式来结束。\""],"roles":[{"name":"殉情者","team":"outsider","ability":"在你的首个夜晚，你要选择一名其他玩家：你或他死亡之后，另一人随时可能死亡。"}]},"pages/殉教少女_Martyra.html":{"name":"殉教少女","englishName":"Martyra","background":["“我颈间的橄榄枝是阿波罗的枷锁，也是海雾中微弱的光。当我用匕首割破喉咙，谎言将随血雾溃散。请记住，我的死亡不是终点，而是你们直视真相的黎明。”"],"roles":[{"name":"殉教少女","team":"townsfolk","ability":"如果爪牙死于处决，当晚你会死亡，且所有邪恶角色醉酒直到明天黄昏。"}]},"pages/毒尾_Venomtail.html":{"name":"毒尾","englishName":"Venomtail","background":["\"看到我身后这条漂亮的尾巴了吗？这可是花大价钱从外乡人那儿买的。它的每一节都是你中毒发黑的邻居，每一节都在无声地腐烂。它会越拖越长，越拖越沉。别急，等毒素爬满你的骨头，你也会被钉上去，永远跟着我晃荡。\""],"roles":[{"name":"毒尾","team":"minion","ability":"你顺时针方向上最近的1+X名镇民中毒。[无外来者在场，X为因你减去的外来者数量]"}]},"pages/毒爆_Toxblast.html":{"name":"毒爆","englishName":"Toxblast","background":["\"他的皮肤下流淌着我的杰作！那些美妙的化合物！绞索一紧，它们就会从他的七窍和伤口喷涌而出，像一场绚烂的烟花雨。落在你们的脸上，渗进你的肺里。美极了，不是吗？\""],"roles":[{"name":"毒爆","team":"minion","ability":"当有玩家被处决时，与他邻近的两名镇民中毒直到明天黄昏。如果白天没人被处决，所有镇民中毒直到明天黄昏。"}]},"pages/气球驾驶员.html":{"name":"气球驾驶员","englishName":"Balloonist","background":["“再来点热量！高点！高点！再高点！啊~从这上面往下看，风景真美，你说呢？你能看见孩子们在河边柳树下钓鱼吗？你能看到马戏团帐篷杆上反射的阳光吗？这是什么？一位老人孤身一人在葡萄园里昏倒了？少来点热量！低点！低点！再低点！”"],"roles":[{"name":"气球驾驶员","team":"townsfolk","ability":"每个夜晚，你会得知一名与上个夜晚得知的玩家角色类型不同的玩家。[+0~1外来者]"}]},"pages/水手.html":{"name":"水手","englishName":"Sailor","background":["“你们随便谁来我都能把他喝到桌子底下去！说你呢！那个话痨！敢来和我喝一杯么？不来？那你呢，老太婆？你以前喝过老麦基利的加香料朗姆酒吗？保证能让你喝成个真男人！上船咯，噢耶！”"],"roles":[{"name":"水手","team":"townsfolk","ability":"每个夜晚，你要选择一名存活的玩家：你或他之一会醉酒直到下个黄昏。你不会死亡。"}]},"pages/沙巴洛斯.html":{"name":"沙巴洛斯","englishName":"Shabaloth","background":["“布嘞啦嘎，福塔啊啊嘎，呐姆姆啊塔噶！呐什，噶姆塔姆什，呐哟咯咯发咯咯咯咯咯咯嘎，哈什嗝呵！”"],"roles":[{"name":"沙巴洛斯","team":"demon","ability":"每个夜晚*，你要选择两名玩家：他们死亡。你的上个夜晚选择过的且当前死亡的玩家可能会被你反刍。"}]},"pages/治安官_Constable.html":{"name":"治安官","englishName":"Constable","background":["“脚印，泥渍，窗台上的划痕。你们忽略的每一个细节，都在跟我说话。我办过一百三十二件案子，定过九十七个人的罪，没有一个冤案，也没有一个漏网。你觉得你能成为第一百三十三个？我拭目以待。”"],"roles":[{"name":"治安官","team":"townsfolk","ability":"在你的首个夜晚，你会得知一名外来者或爪牙玩家。如果你在夜晚死亡，你会得知一名外来者或爪牙玩家（角色类型与上次不同）。[+1外来者]"}]},"pages/法官.html":{"name":"法官","englishName":"Judge","background":["“我认为被告人涉嫌谋杀罪、诈骗罪、放火罪、盗窃罪、招摇撞骗罪、非法行医罪、诽谤罪、弑君罪以及乱丢垃圾罪等罪行。”"],"roles":[{"name":"法官","team":"traveller","ability":"每局游戏限一次，如果其他玩家发起了提名，你可以选择让本次提名直接执行处决或让投票无效。"}]},"pages/泰坦_Titan.html":{"name":"泰坦","englishName":"Titan","background":["\"我曾手托苍穹，如今却只想把它扯落。诸神称我为‘恶’，那我便是至恶，是吞噬一切光明的原初黑暗。我已将残躯献祭给比深渊更古老的意志，换取滔天伟力。弹指星辰碎，吐息万物凋。这一次，没有救赎，只有跪在我脚下、永恒绝望的众神。\""],"roles":[{"name":"泰坦","team":"outsider","ability":"在首个夜晚，你转变为邪恶，并获得所有不在场爪牙的能力。[泰坦在配置时被当作爪牙]"}]},"pages/洗脑师.html":{"name":"洗脑师","englishName":"Cerenovus","background":["“所谓的现实，其实，只是一种想法罢了。具体点来说，是我的想法。”"],"roles":[{"name":"洗脑师","team":"minion","ability":"每个夜晚，你要选择一名玩家和一个善良角色。他明天白天和夜晚需要“疯狂”地证明自己是这个角色，不然他可能被处决。"}]},"pages/洗衣妇.html":{"name":"洗衣妇","englishName":"Washerwoman","background":["“晚礼服上的血渍？","才不是呢，这只是洒上了雪莉酒。真粗心！”"],"roles":[{"name":"洗衣妇","team":"townsfolk","ability":"在你的首个夜晚，你会得知两名玩家和一个镇民角色：这两名玩家之一是该角色。"}]},"pages/流莺.html":{"name":"流莺","englishName":"Harlot","background":["“认得侬老开心额，水手。你好像有些烦心事想告诉我，对嘛对嘛，而我就是一个很棒棒的聆听者。”"],"roles":[{"name":"流莺","team":"traveller","ability":"每个夜晚*，你要选择一名存活的玩家：如果他同意，你会得知他的角色，但是你们两个可能同时死亡。"}]},"pages/浪人_Ronin.html":{"name":"浪人","englishName":"Ronin","background":["“孩子，不要害怕，闭上眼睛。用心感受杀意的流动。”"],"roles":[{"name":"浪人","team":"townsfolk","ability":"每局游戏限一次，在夜晚时*，你可以选择一名玩家：如果当晚他被恶魔攻击，一名邪恶玩家会代替他被攻击，且你重获能力。"}]},"pages/海之子_The_Sea-born.html":{"name":"海之子","englishName":"The Sea-born","background":["\"我亲爱的孩子，你贵为海神波塞冬的血脉，我岂容那些肮脏卑贱的爪牙服侍你。当你枕着浪花安睡时，为父的三叉戟已搅翻整片爱琴海。那些胆敢在黎明前就出航的船，都被暴风雨所撕碎。当最后一位水手沉入海床，这静谧岂非为父最温柔的摇篮曲？\""],"roles":[{"name":"海之子","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。说书人决定自己拥有哪些爪牙的能力，并会尽可能地帮助你获胜。[无爪牙在场，任意数量外来者]"}]},"pages/海外自制_194990941.html":{"name":"致幻师","englishName":"","background":["“我看到了！他是恶魔！”"],"roles":[{"name":"致幻师","team":"minion","ability":"与你邻近的玩家（旅行者除外）会被善良玩家的能力当作错误的阵营和角色。"}]},"pages/海外自制_194990970.html":{"name":"大力士","englishName":"","background":["“卧推卧推卧推卧推卧推卧推卧推卧推","深蹲深蹲深蹲深蹲深蹲深蹲深蹲深蹲","硬拉硬拉硬拉硬拉硬拉硬拉硬拉硬拉","健将健将健将健将健将健将健将健将”"],"roles":[{"name":"大力士","team":"townsfolk","ability":"如果你在白天是最“疯狂”证明自己是大力士的人，今晚选择了你的玩家之一会死亡。"}]},"pages/海外自制_194991406.html":{"name":"投机者","englishName":"","background":["\"开！\""],"roles":[{"name":"投机者","team":"townsfolk","ability":"每个夜晚*，你得知今天提名你的角色。如果你“疯狂”地证明你是投机者，你得知错误信息。"}]},"pages/海外自制_194992504.html":{"name":"庸医","englishName":"","background":["“我说治得了，那就一定能治。”"],"roles":[{"name":"庸医","team":"townsfolk","ability":"每个夜晚，你要选择两名存活玩家：今晚任何玩家使用自身能力选择他们之一作为目标时，改为选中另一名玩家。恶魔不会因此能力而死亡。"}]},"pages/海外自制_194992662.html":{"name":"药剂师","englishName":"","background":["“你记错了，什么提名处决，我们不是只有流放这一说吗？”"],"roles":[{"name":"药剂师","team":"townsfolk","ability":"每局游戏限一次，如果说书人同意，你可以公开改变一条游戏规则。"}]},"pages/海外自制_194993210.html":{"name":"养蜂人","englishName":"","background":["“你若芬芳，蜜蜂自来‌‌”‌‌"],"roles":[{"name":"养蜂人","team":"townsfolk","ability":"一名邪恶玩家会被当作善良阵营、镇民或外来者。每局游戏限一次，如果你公开猜测到这名玩家是谁，你的阵营获胜。"}]},"pages/海外自制_194993350.html":{"name":"驯狮人","englishName":"","background":["“哈库那马塔塔……就是没有烦恼的意思。”"],"roles":[{"name":"驯狮人","team":"townsfolk","ability":"如果与你邻近的存活善良玩家死于处决，当晚恶魔的负面能力对除你以外的玩家无效。"}]},"pages/海外自制_194993459.html":{"name":"学者","englishName":"","background":["“我是非常聪明的，你知道我有多聪明吗？但是我知道你的小聪明。”"],"roles":[{"name":"学者","team":"townsfolk","ability":"在你的首个夜晚，你得知哪些邪恶角色在场。"}]},"pages/海外自制_194993756.html":{"name":"修女","englishName":"","background":["\"只要我还活着，就不会有人遭受苦难。\""],"roles":[{"name":"修女","team":"townsfolk","ability":"除首个夜晚，其他善良玩家不会醉酒、中毒或得知错误信息。"}]},"pages/海外自制_194993849.html":{"name":"占星师","englishName":"","background":["“吾夜观天象...”"],"roles":[{"name":"占星师","team":"townsfolk","ability":"【中文翻译】每个白天，你要拜访说书人得知一条错误信息。每局游戏限一次，你得知正确信息。"}]},"pages/海外自制_194993985.html":{"name":"邮差","englishName":"","background":["“写信告诉我今天，海是什么颜色。”"],"roles":[{"name":"邮差","team":"townsfolk","ability":"在最后一晚，即使你已死亡，选择一名玩家：他得知某些信息。你可以随时决定他得知什么。"}]},"pages/海外自制_194994054.html":{"name":"享乐主义者","englishName":"","background":["“芜湖！”"],"roles":[{"name":"享乐主义者","team":"townsfolk","ability":"与你邻近的存活玩家的醉酒（不含旅行者）。"}]},"pages/海外自制_194994258.html":{"name":"先知","englishName":"","background":["“我们不能确定未来，但可以选择当下”"],"roles":[{"name":"先知","team":"townsfolk","ability":"在你的首个夜晚，你要选择一个天数：如果那一天所有死亡玩家均为善良，你死亡随后他们以旅行者的形式重新入场。"}]},"pages/海外自制_194994342.html":{"name":"流氓","englishName":"","background":["“哈哈，我梭哈，看看我的……额……五条！”"],"roles":[{"name":"流氓","team":"townsfolk","ability":"(Requires a Co-ST) Get your Co-ST to help the Rogue break the rules. For example, the Rogue can message the Co-ST 'i will look at the grim' and the Co-ST can send them the grim. If it seems like the Rogue breaking the rules would be caught by the ST to the Co-ST then the Co-ST can message the ST 'You catch x breaking the rules'. For example, if the Rogue looks at the grim while the ST is in Town Square you can be safe to assume that irl the ST would be behind the grim and notice the Rogue having a peek."}]},"pages/海外自制_194994495.html":{"name":"王子","englishName":"","background":["“哼~你一定是个天生的失败者‌”"],"roles":[{"name":"王子","team":"townsfolk","ability":"除首个夜晚以外，只要你没有被提名，你就不会死亡、转变为邪恶阵营或改变角色。"}]},"pages/海外自制_194994636.html":{"name":"外交官","englishName":"","background":["“为尽地主之谊，亲王大人遣我亲自接待您。”"],"roles":[{"name":"外交官","team":"townsfolk","ability":"在你的首个夜晚，你得知哪些玩家是爪牙。如果一个被你得知的爪牙被处决，你的阵营落败，即使你已死亡。"}]},"pages/海外自制_194994690.html":{"name":"铁匠","englishName":"","background":["“绝对的精品！就连海关总署都得从我这拿货……可别告诉别人，否则我们俩中高低得进去一个……”"],"roles":[{"name":"铁匠","team":"townsfolk","ability":"在你的首个夜晚，你会得知有几名外来者在场。所有外来者醉酒。[+1外来者]"}]},"pages/海外自制_194994783.html":{"name":"天才","englishName":"","background":["“时而清醒时而疯癫，这是那群蠢人对我的描述，而他们不知道，我通常是那个知晓一切的。”"],"roles":[{"name":"天才","team":"townsfolk","ability":"每个夜晚，你可以选择一个善良角色：你获得他的能力，直到你下次选择。你每隔一晚醉酒一天。"}]},"pages/海外自制_194994826.html":{"name":"手相师","englishName":"","background":["“你有血光之灾。”"],"roles":[{"name":"手相师","team":"townsfolk","ability":"恶魔在攻击生效之前一晚发动攻击，即使你已死亡。每个夜晚，你得知谁受到攻击。"}]},"pages/海外自制_194994873.html":{"name":"清道夫","englishName":"","background":["“哪个腌臜扔的腌臜？”"],"roles":[{"name":"清道夫","team":"townsfolk","ability":"如果与你邻座的玩家均已死亡，会有好事发生。"}]},"pages/海外自制_194995528.html":{"name":"失眠者","englishName":"","background":["“我只是时常走丢在深夜，从深夜熬到黎明。”"],"roles":[{"name":"失眠者","team":"townsfolk","ability":"每个夜晚*，你得知当晚死去的一个角色。"}]},"pages/海外自制_194996332.html":{"name":"审计员","englishName":"","background":["“常驻镇民7人，外来人口2人，游客5人~？怎么多了3人？”"],"roles":[{"name":"审计员","team":"townsfolk","ability":"在你的首个夜晚，你会得知有多少名在场角色拥有设置调整的能力。"}]},"pages/海外自制_194996378.html":{"name":"少妇","englishName":"","background":["“再来一杯？”"],"roles":[{"name":"少妇","team":"townsfolk","ability":"每个夜晚，你得知一名玩家。他醉酒直到下个黄昏，他因自身能力获得的信息均为错误。"}]},"pages/海外自制_194996433.html":{"name":"商人","englishName":"","background":["“谁能给这么纯粹的伪黄金定价？”“当然是我们！”"],"roles":[{"name":"商人","team":"townsfolk","ability":"你可以与任意一名其他玩家缔结约定。在新约定达成之前，如果有玩家违约，你和他之一会在当晚死亡。"}]},"pages/海外自制_194996483.html":{"name":"女王","englishName":"","background":["\"她的皇冠闪耀着权威，但真正的挑战是阻止左右的人出卖她。毕竟，她的臣民总喜欢用疯狂的方式证明忠诚。 \""],"roles":[{"name":"女王","team":"townsfolk","ability":"如果你的邻近的两名玩家是善良的，他们得知你是女王。疯狂证明女王在场的玩家可能会被处决。"}]},"pages/海外自制_194996557.html":{"name":"女教师","englishName":"","background":["“她用知识点亮心灵，即使黑暗逼近，也愿给迷失的人最后一次选择的机会——是堕落，还是坚守？”"],"roles":[{"name":"女教师","team":"townsfolk","ability":"即将转变为邪恶但仍保持原角色的玩家，会得知女教师在场，他可以选择保持善良阵营。[至少1名能转变邪恶阵营的角色在场]"}]},"pages/海外自制_194996775.html":{"name":"女家教","englishName":"","background":["”她总是带着温柔的微笑，但心里对得意门生的小秘密她都一清二楚——毕竟，这是‘教学’的一部分。“"],"roles":[{"name":"女家教","team":"townsfolk","ability":"在你的首个夜晚，你得知一个距离你最近的非镇民玩家的角色类型（旅行者除外）。"}]},"pages/海外自制_194996844.html":{"name":"内奸","englishName":"","background":["“是的，我早就察觉到不对劲了。老大，他就是将你暴露出去的那个内奸！”"],"roles":[{"name":"内奸","team":"townsfolk","ability":"你也是爪牙，且被当作邪恶阵营。每局游戏限一次，恶魔可以公开猜测你是内奸，如果猜对，你的阵营落败，即使你已失去能力。"}]},"pages/海外自制_194997234.html":{"name":"马厩男孩","englishName":"","background":["“这匹马忠诚威猛，准是骑士的。”"],"roles":[{"name":"马厩男孩","team":"townsfolk","ability":"每个夜晚，你会得知一个在场的角色。"}]},"pages/海外自制_194997367.html":{"name":"猎巫人","englishName":"","background":["\"烧吧。\""],"roles":[{"name":"猎巫人","team":"townsfolk","ability":"每个夜晚，你可以选择一名玩家：你会得知他的阵营。如果他明天白天没有被处决，当晚他转变为邪恶阵营。你不会转变为邪恶阵营。"}]},"pages/海外自制_194997552.html":{"name":"猎犬饲养员","englishName":"","background":["“真棒！”"],"roles":[{"name":"猎犬饲养员","team":"townsfolk","ability":"每个夜晚，你得知当晚被邪恶玩家能力选择的存活玩家与你的最近距离。"}]},"pages/海外自制_194997610.html":{"name":"窥私者","englishName":"","background":["\"这儿的事他无所不知无所不晓，直到有一天，这边发生了命案，警察找到了他。\""],"roles":[{"name":"窥私者","team":"townsfolk","ability":"每个夜晚*，选择除你以外的一名玩家：如果他今晚死亡，所有玩家会知道你是窥私者。"}]},"pages/海外自制_194997781.html":{"name":"媒人","englishName":"","background":["“千里姻缘一线牵,夜郁相思愁华年。孤雁影单独望月,只羡鸳鸯不羡仙。 ”"],"roles":[{"name":"媒人","team":"townsfolk","ability":"每个白天，你可以向说书人私下选择两名玩家：你得知他们是否与一项正常发动的能力相关。"}]},"pages/海外自制_194997984.html":{"name":"海盗","englishName":"","background":["“他做海贼的一生中，没有一处逃伤。”"],"roles":[{"name":"海盗","team":"townsfolk","ability":"在你的首个夜晚，你会得知几名海盗在场。如果所有存活善良角色均为海盗，善良阵营获胜。[+0或+1海盗]"}]},"pages/海外自制_194998023.html":{"name":"绞刑吏","englishName":"","background":["“你可活不到天亮了。”‌‌"],"roles":[{"name":"绞刑吏","team":"townsfolk","ability":"每局游戏限一次，选择一名玩家。以顺时针方向开始，3秒内没有公开宣称自身角色的善良玩家死亡。"}]},"pages/海外自制_194998069.html":{"name":"凤凰","englishName":"","background":["“上九之凰，潜于深渊谷底，烈火焚烧，千锤百炼，一朝风起云聚，则扶摇直上九万里。”"],"roles":[{"name":"凤凰","team":"townsfolk","ability":"如果你在夜晚死亡，最后一个白天，你以一个不在场镇民的角色复活。"}]},"pages/海外自制_194998180.html":{"name":"放贷人","englishName":"","background":["“他借出的不是钱，而是忠诚，每到夜晚，他都会换一个'主人' 。”"],"roles":[{"name":"放贷人","team":"townsfolk","ability":"每个夜晚，你要选择除你以外的一名存活玩家：你转变为他的阵营。"}]},"pages/海外自制_194998318.html":{"name":"德鲁伊","englishName":"","background":["“每一棵树都是一个生命。”"],"roles":[{"name":"德鲁伊","team":"townsfolk","ability":"每个白天，你可以公开选择一名玩家。如果你们中有人当晚被恶魔杀死，一名存活的爪牙会代替你们死亡。"}]},"pages/海外自制_194998337.html":{"name":"大亨","englishName":"","background":["“班死鬼佬买棺材唔知埞，洗铜银夹大声，彻查！”"],"roles":[{"name":"大亨","team":"townsfolk","ability":"一名与你握手的玩家可能会醉酒直到明天黄昏。每个夜晚*，你会得知你是否在今天白天与邪恶玩家握手。"}]},"pages/海外自制_194998370.html":{"name":"风笛手","englishName":"","background":["\" 他的笛声能操纵人心，但他吹得太忘情，忘了经常到底是带人走向胜利，还是直接跑偏 。\""],"roles":[{"name":"风笛手","team":"townsfolk","ability":"每局游戏限一次，你可以公开选择发动能力：爪牙可以秘密选择转变为善良阵营，但下一个被处决的玩家的阵营落败。"}]},"pages/海外自制_194998403.html":{"name":"车夫","englishName":"","background":["“你知道吗，下个路口那个糕点店里的月饼很好吃，而且价格很便宜。你知道吗，上次医院门口有人碰瓷，直接打起来了，最后两个人甚至在一个病房。哦对了，你知道吗...”"],"roles":[{"name":"车夫","team":"townsfolk","ability":"每个白天，你可以拜访说书人并选择一个话题，说书人会告诉你一个与他有关的事实。如果你的邻近存活玩家阵营不同，你得知错误信息。"}]},"pages/海外自制_194998735.html":{"name":"病患","englishName":"","background":["“无数人希望得到永生的眷顾。但是没人意到，永生，也许只是个孤独的存在。”"],"roles":[{"name":"病患","team":"townsfolk","ability":"每局游戏限一次，你会被唤醒：你每有一个夜晚未被唤醒，就会获得一个在场角色的能力。"}]},"pages/海外自制_194998841.html":{"name":"悲剧演员","englishName":"","background":["“你我精湛演技，然若一瞬舛缪，则将命悬一线。”"],"roles":[{"name":"悲剧演员","team":"townsfolk","ability":"每个白天，一名邪恶玩家要对某件事疯狂，否则他可能死亡。每个白天，你要对某件事疯狂，否则你可能死亡。"}]},"pages/海外自制_194998913.html":{"name":"保姆","englishName":"","background":["“睡吧~睡吧~ 狂风不会将你们吵醒，灾难也将由我代为承受。”"],"roles":[{"name":"保姆","team":"townsfolk","ability":"At dusk, get everyone who wishes to put their hands over their eyes to send you a message saying so, then create a list of these people. If anyone without hands over their eyes wakes, send them the list of people with hands over their eyes. If a player with hands over their eyes would wake, they may select players and characters, but do not learn any sort of information."}]},"pages/海外自制_194998955.html":{"name":"保镖","englishName":"","background":["\"我Ok啊。\""],"roles":[{"name":"保镖","team":"townsfolk","ability":"每局游戏限一次，在夜晚时，你可以选择一个除自己以外的角色：邪恶玩家的负面能力对他无效。"}]},"pages/海外自制_194999096.html":{"name":"机修工","englishName":"","background":["\"我这一辈子都在追问和探究科学的谜题，到头来发现有些谜题真是太美妙了。\""],"roles":[{"name":"机修工","team":"townsfolk","ability":"在你的首个白天，你可以拜访说书人获得一个剧本外角色的能力，即使你醉酒或中毒。"}]},"pages/海外自制_194999737.html":{"name":"赝品","englishName":"","background":["“人的气质就像是古董的包浆”"],"roles":[{"name":"赝品","team":"minion","ability":"你拥有一个在场爪牙的能力。如果没有其他爪牙在场，在你的首个夜晚，你选择一名爪牙：你获得他的能力。"}]},"pages/海外自制_194999938.html":{"name":"桶栖者","englishName":"","background":["“我在找一个人。”"],"roles":[{"name":"桶栖者","team":"minion","ability":"在你的首个夜晚，你要选择一个外来者：所有外来者都会是你选择的外来者。[-或+任意数量外来者]"}]},"pages/海外自制_195000061.html":{"name":"蛇发女妖","englishName":"","background":["“老娘能把你从石头变成雕像!”"],"roles":[{"name":"蛇发女妖","team":"minion","ability":"每个夜晚，选择一名玩家：如果下一个白天他离开座位，他死亡。如果场上少于或等于三名玩家，你失去能力。"}]},"pages/海外自制_195000144.html":{"name":"诺克斯之女","englishName":"","background":["‌“我缺少的是慈悲、同情和宽恕，而不是理智。”‌"],"roles":[{"name":"诺克斯之女","team":"minion","ability":"善良玩家的信息翻转对错。每个玩家第一次说出“诺克斯之女”时：如果他是善良玩家，你失去能力；如果他是邪恶玩家，你重新获得能力。"}]},"pages/海外自制_195000292.html":{"name":"魔仆","englishName":"","background":["“真是抱歉，发生了这样的事情，我一定让主人来您金碧辉煌的屋宇赔不是。您说什么？发现了一些不愉快？这是一点点赔礼，没事的，请收下吧，以这根金戒指预表主人诚挚的歉意吧。”"],"roles":[{"name":"魔仆","team":"minion","ability":"【英文原文】Each night*, you wake with the Demon and choose a player: they die. If you die, the demon loses its ability."}]},"pages/海外自制_195000819.html":{"name":"马戏领班","englishName":"","background":["“你一定会好奇那个杂技演员说的，‘绝世的演出’，是由谁来指挥的！”"],"roles":[{"name":"马戏领班","team":"minion","ability":"每局游戏限一次，即使你已死亡，你可以选择成为说书人。此后你仍然可以投票。"}]},"pages/海外自制_195000973.html":{"name":"稻草人","englishName":"","background":["“ 他被钉在田野上，沉默凝视。人们畏惧他，却看不见真正的怪物藏在阴影里。  ”"],"roles":[{"name":"稻草人","team":"minion","ability":"你会被善良玩家当作恶魔，恶魔会被善良玩家当作爪牙。"}]},"pages/海外自制_195001014.html":{"name":"参议员","englishName":"","background":["“按我说的做——不然所有人都会有麻烦的。”"],"roles":[{"name":"参议员","team":"minion","ability":"玩家只能提名各自邻近的存活玩家。每个夜晚，你要选择自己是否醉酒直到下个黄昏。"}]},"pages/海外自制_195001052.html":{"name":"隐修者","englishName":"","background":["“Zzzzzzzzzzzzzzzzzzzzzzzzzz”"],"roles":[{"name":"隐修者","team":"outsider","ability":"你拥有其他所有外来者的能力。其他对外来者的设置调整不会生效。[无其他外来者在场]"}]},"pages/海外自制_195001190.html":{"name":"囚犯","englishName":"","background":["“我是被冤枉的，我没有偷他钱包里的身份证，他的钱包里明明只有一沓钞票！”"],"roles":[{"name":"囚犯","team":"outsider","ability":"在你的首个夜晚，你会得知一个不在场角色。如果超过半数玩家同意释放你，你会变成这个角色和对应的阵营。在你被释放前你不能投票。"}]},"pages/海外自制_195001367.html":{"name":"骗子","englishName":"","background":["“月球比地球大！宇宙比银河小！我的鼻子很短！”"],"roles":[{"name":"骗子","team":"outsider","ability":"你会在夜晚转变为首个死于处决的玩家的阵营。"}]},"pages/海外自制_195001402.html":{"name":"牧驴人","englishName":"","background":["“能者多劳，多劳不一定多得。”"],"roles":[{"name":"牧驴人","team":"outsider","ability":"如果你被提名的当天你或恶魔未被处决，你的阵营落败。[你的角色标记是方形的]"}]},"pages/海外自制_195001598.html":{"name":"流浪汉","englishName":"","background":["“不，老爷，我已经没有地方能去了！”"],"roles":[{"name":"流浪汉","team":"outsider","ability":"如果在对你的提名中有人投票，你可能会立即被处决。"}]},"pages/海外自制_195001646.html":{"name":"花花公子","englishName":"","background":["“今晚所有消费！反正不是我买单。”"],"roles":[{"name":"花花公子","team":"outsider","ability":"每个夜晚，你要选择一名除你以外的存活玩家：如果明天你和他中有人被处决，另一人也会被处决。"}]},"pages/海外自制_195001797.html":{"name":"孤儿","englishName":"","background":["“给我一朵花，陪陪我玩好不好……”"],"roles":[{"name":"孤儿","team":"outsider","ability":"如果你是善良的且死亡，恶魔只会因你参与投票的处决而死亡。"}]},"pages/海外自制_195002046.html":{"name":"公主","englishName":"","background":["“真肮脏，离我远点！”"],"roles":[{"name":"公主","team":"outsider","ability":"【中文翻译】如果一名玩家死亡后声称自己是公主（你必须声称），另一名玩家可以选择代替死亡。如果代替死亡的玩家是邪恶的，你的阵营落败。"}]},"pages/海外自制_195002116.html":{"name":"佃农","englishName":"","background":["“赤日炎炎似火烧，野田禾稻半枯焦，农夫内心如汤煮，公子王孙把扇摇嘞。”"],"roles":[{"name":"佃农","team":"outsider","ability":"如果你落败，你下一局游戏还是佃农，即使你已死亡。[如果不在盲抽袋中：-1镇民]"}]},"pages/海外自制_195002553.html":{"name":"佐迪翁","englishName":"","background":["“他是黄道十二宫的守护者，手握魔典，掌握命运的书页。每个夜晚，他都会遵从星座的指引，带来毁灭，伤亡注定不可避免。”"],"roles":[{"name":"佐迪翁","team":"demon","ability":"在你的首个夜晚，你能查看魔典。每个夜晚*，存活玩家之中位于剧本列表最顶部一行的会死亡。"}]},"pages/海外自制_195002575.html":{"name":"活体病毒","englishName":"","background":["“我可以和你们共进晚餐吗，我想吃那个煎饼馃子”"],"roles":[{"name":"活体病毒","team":"demon","ability":"在你的首个夜晚，三名除你以外的玩家被感染。每个夜晚*，你要选择一名玩家：他被感染。如果被感染的玩家发起提名，他死亡并感染被提名者。在你的第四个白天结束时，邪恶阵营获胜。"}]},"pages/海外自制_195002601.html":{"name":"夏柯怀特","englishName":"","background":["“我们是一条绳上的蚂蚱，对吧？”"],"roles":[{"name":"夏柯怀特","team":"demon","ability":"每个夜晚，你要选择任意数量玩家：他们会一起被唤醒得知此事。如果明天白天他们中有玩家被处决，所有被选择的玩家立即死亡。如果没有存活玩家被处决，邪恶阵营获胜。"}]},"pages/海外自制_195002921.html":{"name":"神言","englishName":"","background":["“信任无需理由，奉献无需回报，背叛无需代价。”"],"roles":[{"name":"神言","team":"demon","ability":"每个夜晚*，每有一名存活善良玩家在黄昏后举手，就会有一名玩家死亡。如果没有任何存活的善良玩家举手，邪恶阵营获胜。"}]},"pages/海外自制_195003041.html":{"name":"蠕行恐惧","englishName":"","background":["“种子种下，以绝望当生命之源灌注，得终结为永恒。”"],"roles":[{"name":"蠕行恐惧","team":"demon","ability":"【英文原文】Each night*, mark up to 3 players or kill all marked players. Marked players learn that they are marked."}]},"pages/海外自制_195003132.html":{"name":"提普-提普","englishName":"","background":["“tipi-tipi~”"],"roles":[{"name":"提普-提普","team":"demon","ability":"每个夜晚*，会有一名玩家死亡。在最后一晚，你要选择一名玩家：他必须疯狂地证明你不是恶魔，否则他的阵营落败。"}]},"pages/海外自制_195003160.html":{"name":"灵魂之槌","englishName":"","background":["“言语只是人间沟通的手段，而死者只需要安息罢了。”"],"roles":[{"name":"灵魂之槌","team":"demon","ability":"【英文原文】Each night*, choose a player: they die. After the final night, the dead may not talk to the living."}]},"pages/海外自制_195003422.html":{"name":"莉莉丝","englishName":"","background":["“你的手……一点都不老实啊。”"],"roles":[{"name":"莉莉丝","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。如果被你杀死的玩家与你的某个特征均不同，他们转变为邪恶并不再能在这局游戏中投票。所有人都知道这个特征是什么。"}]},"pages/海外自制_195003482.html":{"name":"谎言女王","englishName":"","background":["“我今晚有个晚会，你可以和我一同度过吗？”"],"roles":[{"name":"谎言女王","team":"demon","ability":"【英文原文】Each night* choose 3 players to dupe: each chooses a different alive player, 2 of which die. All players learn who you duped."}]},"pages/海外自制_195003678.html":{"name":"西西弗斯","englishName":"","background":["“永世的折磨！”"],"roles":[{"name":"西西弗斯","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。在夜晚时，如果所有爪牙死亡，你要选择一个除你以外的恶魔角色：你变成那个恶魔，并且每晚行动两次。"}]},"pages/海外自制_195003757.html":{"name":"献礼","englishName":"","background":["\"Se tenir par la main,","Avec les doigts entrelacés,","Jusqu’à des cheveux blancs apparaissent…\""],"roles":[{"name":"献礼","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。首个提名你的镇民会在当晚变成邪恶的献礼，而你会随之死亡。但每局游戏只能成功转化一次。"}]},"pages/海外自制_195003887.html":{"name":"多罗迈特","englishName":"","background":["“想闻闻我的蝴蝶结吗，可爱的心上人。”"],"roles":[{"name":"多罗迈特","team":"demon","ability":"每个夜晚，你要选择一名玩家：他转变为邪恶阵营。每局游戏限一次，你在进行选择时失效。第五个白天结束后，邪恶阵营获胜。[无爪牙在场]"}]},"pages/海外自制_195006132.html":{"name":"诗人","englishName":"","background":["“dadadadalalalala，ohhhhhhdadadlalalallalalbababa~”"],"roles":[{"name":"诗人","team":"townsfolk","ability":"每个夜晚，你要选择除你及旅行者以外的一名玩家：你会得知他的角色的英文名字中的一个字母。"}]},"pages/海外自制_199017430.html":{"name":"面包师","englishName":"","background":["“不是我爱吃，是面包需要我这个懂它的伯乐。”"],"roles":[{"name":"面包师","team":"townsfolk","ability":"每个夜晚*，你会得知你提名过和提名过你的玩家共有几种角色类型。累计达到三种时，他们中会有一名玩家醉酒。"}]},"pages/海外自制_199017433.html":{"name":"摩门教徒","englishName":"","background":["“牧羊人看不见你，而你会被流放至无尽黑暗‌”"],"roles":[{"name":"摩门教徒","team":"townsfolk","ability":"每个白天限一次，如果你的一名与你邻近的玩家公开同意，他会变成摩门教徒。如果他不同意，你们失去能力。"}]},"pages/海外自制_199017439.html":{"name":"幻形妖","englishName":"","background":["“你知道的，我原本不长这个样子。”"],"roles":[{"name":"幻形妖","team":"townsfolk","ability":"每局游戏限一次，在夜晚时*，你可以选择一名玩家：他死亡，你会与被你杀死的非爪牙玩家交换角色和阵营。"}]},"pages/海外自制_199017444.html":{"name":"麻风病人","englishName":"","background":["“话说，你真的应该离我远点”"],"roles":[{"name":"麻风病人","team":"townsfolk","ability":"如果恶魔杀死了你，他中毒。"}]},"pages/海外自制_199017447.html":{"name":"箍桶匠","englishName":"","background":["“这重复，枯燥的工作，确实不如喝酒有趣！”"],"roles":[{"name":"箍桶匠","team":"townsfolk","ability":"如果你被提名，除旅行者以外的所有其他玩家醉酒直到黄昏。"}]},"pages/海外自制_199017906.html":{"name":"不信教者","englishName":"","background":["“那么问题再谁身上呢？你？我？你们？还是我们？”"],"roles":[{"name":"不信教者","team":"townsfolk","ability":"如果恶魔杀死了你，他会转变为善良阵营，但他不知道。"}]},"pages/海外自制_199019895.html":{"name":"猫夫人","englishName":"","background":["“看我~别看我的猫！”"],"roles":[{"name":"猫夫人","team":"outsider","ability":"正在维护"}]},"pages/海外自制_199019927.html":{"name":"劫犯","englishName":"","background":["“此路是我开，此树是我栽”"],"roles":[{"name":"劫犯","team":"outsider","ability":"会有一至两名善良玩家的投票标记会被秘密地记为零，即使你已死亡。"}]},"pages/海外自制_199020270.html":{"name":"宝钻精灵","englishName":"","background":["“死亡是他们的命运，是伊露维塔的礼物，随着时间的流逝，连众神都会嫉羡。"],"roles":[{"name":"宝钻精灵","team":"outsider","ability":"正在维护"}]},"pages/海外自制_199020277.html":{"name":"走卒","englishName":"","background":["“唯卒只能行一步，过河横进退无踪。”"],"roles":[{"name":"走卒","team":"outsider","ability":"每个白天，你只能投票一次。"}]},"pages/海外自制_199020281.html":{"name":"寻踪者","englishName":"","background":["“从拉斯庇亚山脉到亚伯角，从安山洞穴到克拉巴托雅珊瑚礁群，那里有我，也有背叛我的爱人。”"],"roles":[{"name":"寻踪者","team":"outsider","ability":"一名爪牙额外拥有一个不在场的爪牙能力（他会得知此事），即使你已死亡。如果你提名了他，当晚你会得知他的全部能力。"}]},"pages/海外自制_199020284.html":{"name":"作秀狂","englishName":"","background":["“到了那日同庆，个个要鼓掌。”"],"roles":[{"name":"作秀狂","team":"outsider","ability":"在说书人宣布你死亡时没有鼓掌的玩家可能会一起死亡。"}]},"pages/海外自制_199029522.html":{"name":"勘探者","englishName":"","background":["”你居然不知道？你把那五个花花绿绿的石头押出去，就是城里老爷看中的那五种，你就能在官署那领到证，有了那玩意你想挖多少就挖多少！什么？只押四个就够？在哪？在哪？“"],"roles":[{"name":"勘探者","team":"townsfolk","ability":"每个夜晚*，你会得知与你今天提名的玩家最近的邪恶玩家位于他的顺时针还是逆时针方向。如果距离相等，你得知的信息由说书人决定。"}]},"pages/海外自制_199031046.html":{"name":"浪劫","englishName":"","background":["“把他们全拖下水~”"],"roles":[{"name":"浪劫","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡，随后你可以选择一名玩家：如果他上个白天被邪恶玩家提名过，他死亡。"}]},"pages/海外自制_199031065.html":{"name":"魂归者","englishName":"","background":["“我们应当归来，或是从未离去。”"],"roles":[{"name":"魂归者","team":"demon","ability":"【英文原文】"}]},"pages/海外自制_199031072.html":{"name":"伽迪斯","englishName":"","background":["“……阅后即焚”"],"roles":[{"name":"伽迪斯","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡，然后你会得知一名在昨天白天提及过你的玩家：你可以让他死亡。"}]},"pages/海外自制_199031091.html":{"name":"九头蛇","englishName":"","background":["“hail hydra”"],"roles":[{"name":"九头蛇","team":"demon","ability":"每个夜晚*，即使你已死亡，你要选择一名玩家：他死亡。死亡的爪牙可以选择变为九头蛇，但每局游戏仅能成功转化一次。"}]},"pages/海外自制_199031099.html":{"name":"寂灭","englishName":"","background":["“血在流，一个不留。”"],"roles":[{"name":"寂灭","team":"demon","ability":"【英文原文】"}]},"pages/海外自制_199031145.html":{"name":"烘焙师","englishName":"","background":[],"roles":[{"name":"烘焙师","team":"fabled","ability":"【英文原文】"}]},"pages/海外自制_199031154.html":{"name":"动物管理员","englishName":"","background":[],"roles":[{"name":"动物管理员","team":"fabled","ability":"【英文原文】"}]},"pages/海外自制_199031210.html":{"name":"战车","englishName":"","background":["“他驾驭着毁灭的战轮，碾碎一切挡路者，欺骗与交换是他的武器，每一次前进，都是为黑暗铺就的命运轨迹。”"],"roles":[{"name":"战车","team":"minion","ability":"与你顺时针距离为1的玩家中毒。如果是邪恶的非旅行者玩家，改为和他交换角色。每个夜晚*，或该玩家已死亡，该距离+1。"}]},"pages/海外自制_199031253.html":{"name":"夜影","englishName":"","background":["“你好好，你坏坏。”"],"roles":[{"name":"夜影","team":"minion","ability":"每个夜晚，你要选择两名玩家：其中的非恶魔玩家会被当作与他原本阵营相反的阵营，直到下个黄昏。"}]},"pages/海外自制_199031325.html":{"name":"憎恶","englishName":"","background":["“每当鲜血洒落，新的灵魂便从深渊归来，直到世界被仇恨吞噬殆尽。”"],"roles":[{"name":"憎恶","team":"minion","ability":"每个夜晚*，你可以选择一名玩家：他死亡，在此之前，与他阵营相同的另一名玩家复活。恶魔死亡不会导致游戏结束。"}]},"pages/海外自制_199031343.html":{"name":"恶棍","englishName":"","background":["“你放一百个心，我做事从来不留首尾。”"],"roles":[{"name":"恶棍","team":"minion","ability":"【中文】如果白天没有存活善良玩家被其他玩家提名，邪恶获胜。每个夜晚*，如果你被提名，恶魔当晚可能会被当作善良的镇民或外来者角色。"}]},"pages/海外自制_199031365.html":{"name":"铜蛇帮","englishName":"","background":["“摩西在旷野怎样举蛇，人子也必照样被举起来，叫一切信他的都得永生。”"],"roles":[{"name":"铜蛇帮","team":"minion","ability":"如果你提名了一名玩家，他和与他邻座的玩家中的善良玩家中毒，直到你下次提名。[-1或+1外来者]"}]},"pages/海外自制_199031376.html":{"name":"浊瘴","englishName":"","background":["“乌，烟，瘴，气”"],"roles":[{"name":"浊瘴","team":"minion","ability":"如果邪恶玩家提名了存活的邪恶玩家，他们交换角色。如果善良玩家公开声称驱散浊瘴，你和镇民玩家中毒。"}]},"pages/海外自制_199753550.html":{"name":"追猎者","englishName":"","background":["\"不是所有人都跟动物那么聪明，也不是所有动物都和某些人那么笨！\""],"roles":[{"name":"追猎者","team":"townsfolk","ability":"每个夜晚*，你可以选择一名玩家：如果与他邻近的玩家中有且只有一名是邪恶的，且他不是恶魔，他死亡。"}]},"pages/海外自制_199810744.html":{"name":"齐'纳克","englishName":"","background":["“没错，你们要找的人是我。即使如此，那又如何呢，桀桀桀。我从不畏惧死亡，我的獠牙会在我死后将你们毁灭。”"],"roles":[{"name":"齐'纳克","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。一名善良玩家会知道你在两名玩家之中。如果有爪牙存活时你被处决，你的阵营获胜。"}]},"pages/海外自制_199810919.html":{"name":"冒名客","englishName":"","background":["“对，没错，是我。”"],"roles":[{"name":"冒名客","team":"minion","ability":"每个白天，在你首次“疯狂”地证明自己是一个在场角色时，你在那天让他中毒并获得该角色的能力。"}]},"pages/海外自制_199810980.html":{"name":"癫人","englishName":"","background":["\"哈哈，你看到了吗？那云朵在跳舞，它在向我招手呢！不对，不对，是星星，星星掉下来了，变成了金色的糖果雨！我要去接住它们，然后分给每一个我认识的人，哦不，是每一个不认识的人\""],"roles":[{"name":"癫人","team":"minion","ability":"每个夜晚，你要选择至多三名玩家：他们以为自己受到疯狂能力的影响，但实际上没有。"}]},"pages/海外自制_199811084.html":{"name":"乌鸦嘴","englishName":"","background":["“我恭喜你发财，我恭喜你精彩，不好的请走开，最好的请过来，噢礼多人不怪——”"],"roles":[{"name":"乌鸦嘴","team":"outsider","ability":"【中文能力】可能会有一名善良玩家得知一条虚假的信息，即使你已死亡。"}]},"pages/海外自制_199958012.html":{"name":"小说家","englishName":"","background":["“我写下世界的片段，结果世界把我当成了编剧。”"],"roles":[{"name":"小说家","team":"townsfolk","ability":"【中文能力】每个白天，你可以邀请一名玩家（与之前不同）与你分别私下询问说书人：他可以问一个是非问题，随后你会得知一个答案相同的是非问题。"}]},"pages/海外自制_199964660.html":{"name":"芭蕾舞者","englishName":"","background":["“穿上那袭洁白无瑕的舞裙，仿佛整个世界都安静了，只留下舞台上那一抹灵动。”"],"roles":[{"name":"芭蕾舞者","team":"townsfolk","ability":"在你的首个夜晚，你会得知在你的顺时针方向的镇民与你的距离是奇数居多还是偶数居多。如果两者相同，你得知的信息由说书人决定。"}]},"pages/海外自制_199964816.html":{"name":"谜题魔","englishName":"","background":["“真実はいつもひとつ”"],"roles":[{"name":"谜题魔","team":"minion","ability":"当小于等于五名存活玩家（旅行者不计算在内），邪恶阵营落败时，所有玩家要同时猜测谁是谜题魔，如果少于两名善良玩家猜测你，邪恶阵营获胜，即使你已死亡。"}]},"pages/海外自制_199965616.html":{"name":"泽德拉丝","englishName":"","background":["“您好，您吉祥，希望这伟大的仪式没有耽误我的时间。”"],"roles":[{"name":"泽德拉丝","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。你的夜晚行动顺序位于夜晚最末尾。[+1爪牙]"}]},"pages/海外自制_200002972.html":{"name":"讲师","englishName":"","background":["“让我看看，今天哪位小朋友拿不到小红花？”"],"roles":[{"name":"讲师","team":"townsfolk","ability":"每个白天，你可以拜访说书人并得知一名玩家做错的事。"}]},"pages/海外自制_200003347.html":{"name":"惠斯普","englishName":"","background":["“ *回声*亮出你的剑！”"],"roles":[{"name":"惠斯普","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。如果有镇民玩家提名了你，你死亡。如果在同一天里有两名善良玩家发起提名，邪恶阵营获胜。"}]},"pages/海外自制_200003954.html":{"name":"西西里人","englishName":"","background":["“你必须把对手带入一个深邃的黑暗森林，在那里2+2=5，而唯一的出路仅容的下一人通过。”"],"roles":[{"name":"西西里人","team":"minion","ability":"提名阶段开始时，如果你的阵营中只有你公开选择了一名存活的非旅行者玩家，而他今天白天没有被处决，他的阵营获胜。"}]},"pages/海外自制_200004043.html":{"name":"范扎兹","englishName":"","background":["“嘿嘿，您猜怎么着~”"],"roles":[{"name":"范扎兹","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡且你转变为他的阵营。如果你死亡，你的阵营落败。如果只有两名玩家存活，你的阵营获胜。"}]},"pages/海外自制_203317700.html":{"name":"斗牛士","englishName":"","background":["“死。”"],"roles":[{"name":"斗牛士","team":"minion","ability":"在你发起提名后，一名除你以外的投票玩家会在当晚死亡，如果没有除你以外的玩家投票，你可能在当晚死亡。"}]},"pages/海外自制_203549038.html":{"name":"金匠","englishName":"","background":["“真金不怕火炼，但是你……？”"],"roles":[{"name":"金匠","team":"townsfolk","ability":"【英文原文】"}]},"pages/海外自制_203549175.html":{"name":"暴徒","englishName":"","background":["“世界已经如此糟糕，我还是想走自己认为正确的道路。”"],"roles":[{"name":"暴徒","team":"outsider","ability":"每次提名中，在你之后与你投票不同的一名玩家可能死亡。"}]},"pages/海外自制_203549178.html":{"name":"绝密档案","englishName":"","background":["“钟楼研究所最高绝密档案[CN-067]——█ █ █ 亲启”"],"roles":[{"name":"绝密档案","team":"outsider","ability":"【英文原文】"}]},"pages/海外自制_203549228.html":{"name":"香料商","englishName":"","background":["“兄弟，你好香。”"],"roles":[{"name":"香料商","team":"townsfolk","ability":"【英文原文】"}]},"pages/海外自制_203952058.html":{"name":"幸运儿","englishName":"","background":["“没有子弹可以打中我的心脏~”"],"roles":[{"name":"幸运儿","team":"outsider","ability":"第一个提名你的玩家当晚转变为邪恶阵营。如果你第一个提名自己，你的阵营落败。"}]},"pages/海外自制_203953845.html":{"name":"贵妇","englishName":"","background":["“哎呀——生活就得有品质，不然和那些草包有啥区别?”‌"],"roles":[{"name":"贵妇","team":"outsider","ability":"如果你死亡，当晚恶魔可以查看魔典。"}]},"pages/海外自制_203953955.html":{"name":"巴洛-弗","englishName":"","background":["“坟前的雾，是月与我的约会地方”"],"roles":[{"name":"巴洛-弗","team":"demon","ability":"【英文原文】Each night*, choose a player: they die. Players killed by the Barrow-Fog register as alive during the day."}]},"pages/海外自制_208110868.html":{"name":"吸血鬼","englishName":"","background":["“他优雅而致命，低语间便能腐蚀人心。被他盯上的猎物不再是敌人，而是迷失于黑暗的忠实仆从，甘愿奉献鲜血，直至彻底堕落。”"],"roles":[{"name":"吸血鬼","team":"minion","ability":"你知道一些善良玩家和他们的角色。[这些玩家失去能力并以为自己是爪牙]"}]},"pages/海外自制_208113222.html":{"name":"亡灵骑士","englishName":"","background":["“生不过是一场骗局，亡灵。我会念出你的名字，削去你的留恋，我将带你一起品尝这生灵消亡的美妙滋味。”"],"roles":[{"name":"亡灵骑士","team":"minion","ability":"每个夜晚*，你会得知当天死亡的外来者是谁，且你要猜测他的角色，如果你猜对，会有一名玩家死亡。[+1外来者]"}]},"pages/海外自制_208120049.html":{"name":"巡林客","englishName":"","background":["“”"],"roles":[{"name":"巡林客","team":"townsfolk","ability":"在你的首个夜晚，你会得知与爪牙邻近的善良角色数量。"}]},"pages/海女_Pearl_Diver.html":{"name":"海女","englishName":"Pearl Diver","background":["_\"__我每从海里带走一点东西，海也从我身上带走一点东西。四十岁那年，它拿走了我的听力；五十岁，拿走了一只膝盖。可我赚回来的，是看得见暗流的方向，是闻得出风暴前海水的铁锈味。海欺负人？不，海里的事儿远比岸上公平。__\"_"],"roles":[{"name":"海女","team":"townsfolk","ability":"在你的首个夜晚，你会得知一名邪恶玩家与你的距离。"}]},"pages/海德拉_Hydra.html":{"name":"海德拉","englishName":"Hydra","background":["_\"__你所谓的‘终结’，不过是生命最底层的可笑错觉。我的存在，即是生命本身那盲目、贪婪、无限复制的丑陋真相。处决？当你的小镇每一个角落都蠕动着我的身影时，你终会明白——你并非在斩杀恶魔，你只是在帮我…进化。__\"_"],"roles":[{"name":"海德拉","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。如果你在审判日降临前死于处决，一名善良玩家与一名邪恶玩家会变成海德拉。"}]},"pages/海猫王_Pirate_Cat_King.html":{"name":"海猫王","englishName":"Pirate Cat King","background":["\"财富、名声、势力 —— 拥有整个世界一切的猫人，海猫王哥尔・D・喵杰，他在临刑前的一句话，让全世界的人都奔向了大海！","想要我的宝藏吗喵？想要的话可以全部给你，去找吧喵！我把所有宝藏都放在那里了喵！","于是，所有猫子汉航向伟大的航路，追逐梦想，世界迎来了大海猫时代！\""],"roles":[{"name":"海猫王","team":"outsider","ability":"死亡玩家可以上交投票标记成为寻宝人。审判日降临时，如果你已经死亡，所有寻宝人平分12枚投票标记。"}]},"pages/涡流.html":{"name":"涡流","englishName":"Vortox","background":["“黑白颠倒，对错不再，左右变换，长短无猜。万物紊乱无可寻，短视死亡把命栽，何处寻答？随我来。”"],"roles":[{"name":"涡流","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。镇民玩家的能力都会产生错误信息。如果白天没人被处决，邪恶阵营获胜。"}]},"pages/混沌.html":{"name":"混沌","englishName":"Hun Dun","background":["“有神鸟，其状如黄囊，赤如丹火，六足四翼，浑敦无面目，是识歌舞，实惟帝江也。”"],"roles":[{"name":"混沌","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。如果你以这种方式杀死了一名与你邻近的镇民玩家，所有善良玩家会中毒直到下个黄昏。"}]},"pages/渔夫.html":{"name":"渔夫","englishName":"Fisherman","background":["“这是这条河流里我最喜欢的一截儿……看看阳光是如何让一道彩虹横跨修道院和集市的？这是能让鱼儿长得肥美的最好的地方。我一天天变老，它们也一天天长大。”"],"roles":[{"name":"渔夫","team":"townsfolk","ability":"每局游戏限一次，在白天时，你可以让说书人给你一些能帮助你的阵营获胜的建议。"}]},"pages/游侠_Ranger.html":{"name":"游侠","englishName":"Ranger","background":["_\"__鹰犬无坟，林鸦为葬。__\"_"],"roles":[{"name":"游侠","team":"townsfolk","ability":"如果与你邻近的存活玩家死亡，当晚你会被唤醒并要选择一名玩家：如果他是爪牙，他死亡。"}]},"pages/游歌者_Bard.html":{"name":"游歌者","englishName":"Bard","background":["\"被我指尖点中的灵魂都将坠入梦境。当你们在酒精里踉跄时，我正数着震动的丝弦…三根？五根？这些数字会告诉我，究竟有多少‘诚实者’在甜梦里露出了谎言的形状。\""],"roles":[{"name":"游歌者","team":"townsfolk","ability":"每个白天，你可以公开选择任意名存活玩家：其中的镇民会醉酒直到你再次选择。当晚你会得知正因你醉酒的人数。"}]},"pages/湖中仙女_Lady_of_the_Lake.html":{"name":"湖中仙女","englishName":"Lady of the Lake","background":["_“__被遗忘的从没有真正消散，不过是在此处安然沉眠。而今，我将这一切归还于你，如同交付一把开启过往的钥匙，既照见你的来路，也锚定你奔赴前路的信念。__”_"],"roles":[{"name":"湖中仙女","team":"townsfolk","ability":"每个夜晚*，如果当天有玩家被处决，你会得知他是否为镇民。如果他依然存活，你改为得知与他邻近的两名玩家是否皆为镇民。"}]},"pages/灯神.html":{"name":"灯神","englishName":"Djinn","background":["“我们并非在此，","你也未必真实，","一切神秘皆是幻象难觅，","茫茫问题好似晴天霹雳。”","（原文为阿拉伯语，见下）","نحن لسنا هنا.","انت لست حقيقي.","كل شيء هو وهم.","أسئلتك هي جبل نار في يوم صافٍ."],"roles":[{"name":"灯神","team":"fabled","ability":"使用灯神的相克规则。所有玩家都会知道其内容。"}]},"pages/灵媒_Medium.html":{"name":"灵媒","englishName":"Medium","background":["_\"__我不喜欢说话，但亡魂喜欢。\"_"],"roles":[{"name":"灵媒","team":"townsfolk","ability":"如果镇民死于你发起的提名处决，当晚他会得知灵媒在场。"}]},"pages/灵言师.html":{"name":"灵言师","englishName":"Mezepheles","background":["“唯有源自内心深处的情感，才能让他人的心灵向你屈从。”"],"roles":[{"name":"灵言师","team":"minion","ability":"在你的首个夜晚，你会得知一个关键词。首个说出该关键词的善良玩家会在当晚转变为邪恶阵营。"}]},"pages/炸弹人.html":{"name":"炸弹人","englishName":"Boomdandy","background":["“嘀…嘀…嘀…嗒。”"],"roles":[{"name":"炸弹人","team":"minion","ability":"如果你被处决，除三名玩家以外的其他所有玩家均会死亡。一分钟之后，被最多玩家手指指着的玩家死亡。"}]},"pages/炼金术士.html":{"name":"炼金术士","englishName":"Alchemist","background":["“探寻地球本质。加以矫正，你将寻得秘石。黄金之上皆是红色。那是真理之冠。”"],"roles":[{"name":"炼金术士","team":"townsfolk","ability":"你拥有一个不在场的爪牙角色的能力。"}]},"pages/煞星.html":{"name":"煞星","englishName":"Mr. Misfortune","background":["“曾有游方术士言我天煞孤星命格，近则不幸。愚昧无知！世事无常，与吾何干！”"],"roles":[{"name":"煞星","team":"outsider","ability":"如果你死亡，当晚与你邻近的存活玩家之一可能会死亡。"}]},"pages/熊孩子.html":{"name":"熊孩子","englishName":"Rascal","background":["“这个是我的！……那个也是我的！”"],"roles":[{"name":"熊孩子","team":"townsfolk","ability":"每个夜晚，你要选择一个镇民角色：他的能力会产生错误信息，直到下个黄昏。"}]},"pages/牙噶巴卜.html":{"name":"牙噶巴卜","englishName":"Yaggababble","background":["“莫尔街的谋杀案？假的噶！","巴斯克维尔的猎犬？假的噶！","尼罗河上的惨案？假的噶！”"],"roles":[{"name":"牙噶巴卜","team":"demon","ability":"在你的首个夜晚，你会得知一段秘密短语。每次你在白天公开说出这段短语，当天便可能会有一名玩家在这之后死亡。"}]},"pages/牛仔_Cowboy.html":{"name":"牛仔","englishName":"Cowboy","background":["\"当倒数结束，我拔枪的速度，便是你余生的长度。\""],"roles":[{"name":"牛仔","team":"townsfolk","ability":"在首个夜晚，一名爪牙会得知牛仔在场。每当他发起提名，你会在当晚被唤醒。你们中首次被对方提名的玩家立即被处决。"}]},"pages/狂热者.html":{"name":"狂热者","englishName":"Zealot","background":["“和你聊天让我很享受。你的想法很有吸引力，和我的想法很相似。除非……这只是你的疯言疯语。”"],"roles":[{"name":"狂热者","team":"outsider","ability":"如果有大于等于五名玩家存活，你必须在所有提名中投票。"}]},"pages/狐妖_Kitsune.html":{"name":"狐妖","englishName":"Kitsune","background":["\"你跪得太标准了，不像是现学的。这种刻在骨子里的礼仪，只有幕府的后人才有。可幕府十五年前就亡了……有趣。所以你是幕府托孤的大小姐，还是那个出卖了全家的告密者？别抖亲爱的，我只是随口问问而已，你说呢？\""],"roles":[{"name":"狐妖","team":"minion","ability":"每个夜晚*，你要选择一名玩家和一个外来者角色：如果该角色不在场，他变成该角色。如果他是该角色，他死亡。[-1或+1外来者]"}]},"pages/狐媚娘.html":{"name":"狐媚娘","englishName":"Vixen","background":["“王上，妾身有两个妹妹，一个名为喜媚，一个名为琵琶。”"],"roles":[{"name":"狐媚娘","team":"minion","ability":"在你的首个夜晚，你要选择一名玩家：他会知道狐媚娘在场。如果你死于处决，当晚他转变为邪恶阵营。"}]},"pages/独眼巨人_Cyclops.html":{"name":"独眼巨人","englishName":"Cyclops","background":["_“__俺就一只眼，但俺这只眼可好使了。你在屋里干啥，俺在山头上都看得清清楚楚。你别怪俺偷看，是主人让俺看的，俺只是听话。你昨晚睡觉前嘀咕的那句话，俺也听见了——俺耳朵也不差。__”_"],"roles":[{"name":"独眼巨人","team":"minion","ability":"每个夜晚，你要选择一名玩家：你和恶魔会得知他是什么角色。如果你选中了外来者，他会得知独眼巨人在场。[+1外来者]"}]},"pages/狸猫.html":{"name":"狸猫","englishName":"Dragon Li","background":["“爱妃怎会诞下如此怪胎！”"],"roles":[{"name":"狸猫","team":"townsfolk","ability":"每个夜晚*，你要选择一名除你及旅行者以外的玩家：如果恶魔在今晚杀死了他，你和他交换角色，然后你醉酒。"}]},"pages/狼孩_Wolfboy.html":{"name":"狼孩","englishName":"Wolfboy","background":["\"你们管我们叫‘狼孩’，好像我们是一个群体。但我们从来不是。我们唯一的共同点是——都被小镇所抛弃，你们恨我们，我们也恨你们。狼群没有名字，我也没有名字。但将来恶魔会赐与我们中的某个人一个新名字，一个真正的名字。到那天，他会用这个名字敲开你们的每一扇门。\""],"roles":[{"name":"狼孩","team":"outsider","ability":"当其他狼孩均死亡时，你变成邪恶的不在场爪牙。[可能有多个外来者是狼孩]"}]},"pages/猎人_Hunter.html":{"name":"猎人","englishName":"Hunter","background":["_\"我的陷阱早已埋下，兽道上的枯叶掩盖着铁齿。现在，只需趴在灌木后，让呼吸与风声融为一体。等它的后腿踩进圈套，身体失衡的那一瞬——扣下扳机，尘埃落定。__\"_"],"roles":[{"name":"猎人","team":"townsfolk","ability":"如果被你提名的玩家在当晚死亡，你会被唤醒且要选择一名玩家：他死亡。"}]},"pages/猎手.html":{"name":"猎手","englishName":"Slayer","background":["“受死吧。”"],"roles":[{"name":"猎手","team":"townsfolk","ability":"每局游戏限一次，你可以在白天时公开选择一名玩家：如果他是恶魔，他死亡。"}]},"pages/猎魔人_Witcher.html":{"name":"猎魔人","englishName":"Witcher","background":["“每砍下一颗恶魔的头颅，我的影子就会扭曲一点。镇上的人总让我小心别受伤，可他们不知道，真正危险的我听见自己的心跳越来越像它。我开始喜欢生肉的味道，开始享受他们逃跑时的尖叫。猎杀？不过是把另一个自己摁进泥里。等哪天我拔不出这把剑了，眼里不再有光了。你们要找到我，然后用这把剑杀了我。”"],"roles":[{"name":"猎魔人","team":"townsfolk","ability":"每局游戏限一次，在夜晚时*，你可以选择一名玩家：他死亡，且当晚恶魔不能攻击。如果你杀死了恶魔，你和他交换角色和阵营。"}]},"pages/猫猫合唱团_The_Cat_Chorus.html":{"name":"猫猫合唱团","englishName":"The Cat Chorus","background":["“警报！警报！猫猫合唱团正式接管今夜喵！重复，猫猫合唱团正式接管今夜喵！我们的任务是：带领大家狂欢到天亮喵！清醒点喵！跟着拍子，一起跺脚！一、二、三、四！喵！喵！喵！喵！”"],"roles":[{"name":"猫猫合唱团","team":"outsider","ability":"一名玩家醉酒。在黄昏时，说书人可能会指定一首歌曲：如果玩家们成功合唱，所有镇民不受中毒醉酒影响，直到下个黄昏。"}]},"pages/猫猫探险队_The_Cat_Adventurers.html":{"name":"猫猫探险队","englishName":"The Cat Adventurers","background":["_\"__午安喵，诸位。猫猫探险队应谜题之召而来，很荣幸能为贵镇分忧喵。我们需要一位熟悉本地情况的勇士为我们开路喵。在此之前，我有义务告知各位深入险境要承担极大的风险喵。好了，哪位勇士愿意加入荣耀的猫猫探险队喵？__\"_"],"roles":[{"name":"猫猫探险队","team":"townsfolk","ability":"每个白天，一名未探险过的玩家可以公开申请探险。在当晚，如果他存活，你会得知一名与他阵营对立的玩家。"}]},"pages/王牌_Joker.html":{"name":"王牌","englishName":"Joker","background":["_\"__我听见黑桃在密谋，红心在颤抖，梅花在窃笑，方块在坚守。别紧张，我只是个无害的小丑。__\"_"],"roles":[{"name":"王牌","team":"townsfolk","ability":"每个夜晚，你要选择一名其他玩家：你会得知他是什么花色。四种花色秘密对应着四种角色类型。"}]},"pages/玩偶_Doll.html":{"name":"玩偶","englishName":"Doll","background":["“他们说我是好孩子...但我总听见针脚裂开的声音。我后背的标签上的那串数字...好像在倒数？那位大人，您需要新朋友了对吗？这次我会乖乖躺进棺材里...”"],"roles":[{"name":"玩偶","team":"minion","ability":"你以为你是一个善良角色，但其实你不是。如果你被恶魔杀死，恶魔要选择一名玩家：他变成玩偶。[玩偶会与恶魔邻座]"}]},"pages/玩具匠.html":{"name":"玩具匠","englishName":"Toymaker","background":["“它会发出声音！会自己下楼！还可以在夜里为你提供温暖！它尝起来像糖果！孩子们都喜欢它！隆重介绍...这就是全新的 温暖的-巴兹-乌兹-行走机器人装置！适合全年龄段！”"],"roles":[{"name":"玩具匠","team":"fabled","ability":"恶魔可以在夜晚选择放弃攻击（每局游戏至少一次）。邪恶玩家照常获取初始信息。"}]},"pages/珀.html":{"name":"珀","englishName":"Po","background":["“我给你一朵花，陪陪我好不好……”"],"roles":[{"name":"珀","team":"demon","ability":"每个夜晚*，你可以选择一名玩家：他死亡。如果你上次选择时没有选择任何玩家，当晚你要选择三名玩家：他们死亡。"}]},"pages/理发师.html":{"name":"理发师","englishName":"Barber","background":["“对了，你以前知不知道，理发师和手术医生其实是同一个职业？不知道？那现在你知道了。”"],"roles":[{"name":"理发师","team":"outsider","ability":"如果你死亡，在当晚恶魔可以选择两名玩家（不能选择其他恶魔）交换角色。"}]},"pages/男爵.html":{"name":"男爵","englishName":"Baron","background":["“这个小镇没救了，不是么？廉价的外来劳动力……这就是问题所在。要我说，我会把他们全部调配到矿井里。不过是稍有些困难的工作，这不会伤害到任何人，要是有人提出反对意见就赏他一记耳光。这就是所谓的底线，不是么？”"],"roles":[{"name":"男爵","team":"minion","ability":"会有额外的外来者在场。[+2 外来者]"}]},"pages/画家_Painter.html":{"name":"画家","englishName":"Painter","background":["“你们都说画人的皮肤要用肉色，可哪儿有什么'肉色'？你的脸里混着隔壁磨坊飘来的面粉白，他的脸上沉着铸铁炉的橘红，小孩的腮帮子是玫瑰红加了一丁点柠檬黄。我每画一个人，先要闻他身上的气味，再根据气味配颜料。油画的好，就在于颜色可以像药方一样现抓。这张脸画完，你们闻着味儿就能找到人。”"],"roles":[{"name":"画家","team":"townsfolk","ability":"在你的首个夜晚，你会得知一个在场角色。每个夜晚*，你要选择一名玩家：如果他是你最近得知的角色，你会得知另一个在场角色。"}]},"pages/画皮.html":{"name":"画皮","englishName":"Veilhuska","background":["“愚哉世人！明明妖也，而以为美。迷哉愚人！明明忠也，而以为妄。”"],"roles":[{"name":"画皮","team":"minion","ability":"在你的首个夜晚，你要选择一名存活玩家：他死亡但会被当作存活。当他下一次死亡时，他重生，随后你重获能力。"}]},"pages/畸形秀演员.html":{"name":"畸形秀演员","englishName":"Mutant","background":["“我不是怪物！我是人！求你了！”"],"roles":[{"name":"畸形秀演员","team":"outsider","ability":"如果你“疯狂”地证明自己是外来者，你可能被处决。"}]},"pages/疯子.html":{"name":"疯子","englishName":"Lunatic","background":["“吾即是暗夜……没错吧？”"],"roles":[{"name":"疯子","team":"outsider","ability":"你以为你是一个恶魔，但其实你不是。恶魔知道你是疯子以及你在每个夜晚选择了哪些玩家。"}]},"pages/病房监控_Ward_Surveillance.html":{"name":"病房监控","englishName":"Ward Surveillance","background":["“1号疯子今天晚上吃了仰望星空派，2号疯子今天白天与他的“爪牙”私会了三分钟！汇报完毕！”"],"roles":[{"name":"病房监控","team":"fabled","ability":"说书人可能会把任何关于疯子的信息透露给恶魔或爪牙玩家。疯子可能会得知其他玩家是疯子。"}]},"pages/痢蛭.html":{"name":"痢蛭","englishName":"Lleech","background":["“美味，美味，美味，美味，美味，美味，美味，美味的脑——馅儿饼！是的。美味的老馅儿饼。我想说的就是这个。”"],"roles":[{"name":"痢蛭","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。在你的首个夜晚，你要选择一名存活的玩家：他中毒，只有他死亡时你才会一同死亡。"}]},"pages/瘟疫医生.html":{"name":"瘟疫医生","englishName":"Plague Doctor","background":["“辟免剧勒润动。输要时间康护。莫要，抹药。”"],"roles":[{"name":"瘟疫医生","team":"outsider","ability":"如果你死亡，说书人获得一个不在场的爪牙能力。"}]},"pages/白骑士_White_Knight.html":{"name":"白骑士","englishName":"White Knight","background":["“我陷落在泥泞贫瘠的土壤里，腥咸的泪水与疼痛的呻吟绵延不绝，它们在脆弱的傲慢和敏感的裹挟之下慢慢窒息。但只要你愿意呼唤我的名字，就算彻底撕毁我腐烂的皮囊，就算拼尽我尚存的一丝气力，我也要来拯救你。”"],"roles":[{"name":"白骑士","team":"outsider","ability":"每局游戏限一次，疯狂地想要存活的玩家在被处决时可能不会死亡。"}]},"pages/百臂巨人_Hekatonkheires.html":{"name":"百臂巨人","englishName":"Hekatonkheires","background":["“百臂巨人的血脉从不屈服！每张处决我的陶片，都会成为我举起巨石的臂膀。我终将砸穿你们的伪善，哪怕它硬如特洛伊的城墙。”"],"roles":[{"name":"百臂巨人","team":"minion","ability":"如果你在死于处决后，立即公开声明你是百臂巨人，你下一次投票的票数会记作你今天获得的票数。"}]},"pages/皮匠_Tanner.html":{"name":"皮匠","englishName":"Tanner","background":["_\"你这靴帮子内侧磨得厉害，这是常在马镫上蹭的。会来我这儿的，你应该是个传令兵吧？我这儿没有现成的军需装备，只有刚泡好的牛皮，给镇上的驴子做肚带用。说吧，你靴子底快掉了，是补掌还是换整张皮？__\"_"],"roles":[{"name":"皮匠","team":"townsfolk","ability":"在你的首个夜晚，你会得知一个距离你最近的邪恶角色。"}]},"pages/盗血者_Blood_Thief.html":{"name":"盗血者","englishName":"Blood Thief","background":["\"昏聩的恶魔，愚笨的爪牙，葬送胜局的闹剧结束了。接下来，睁眼看好，这独一份的逆转！\""],"roles":[{"name":"盗血者","team":"outsider","ability":"审判日降临前，唯一存活的邪恶玩家死亡时，你变成他的角色与阵营。"}]},"pages/真心人_Truelove.html":{"name":"真心人","englishName":"Truelove","background":["“你的眼睛在躲我。没关系，慢慢来。我可以先把我的真心掏出来给你看看，你验验货，觉得不假，再考虑要不要把你的也拿出来。不用马上决定，我等得起——真心这东西，急不得，也装不得。”"],"roles":[{"name":"真心人","team":"townsfolk","ability":"在你的首个白天，你可以邀请说书人见证你与一名玩家互通角色，随后你会私下得知是否有人说谎。"}]},"pages/知府.html":{"name":"知府","englishName":"Prefect","background":["“升堂！”"],"roles":[{"name":"知府","team":"townsfolk","ability":"每个夜晚*，你会得知今天是否有非镇民且非旅行者玩家死亡。"}]},"pages/石像鬼_Gargoyle.html":{"name":"石像鬼","englishName":"Gargoyle","background":["\"石缝间的风，是我沉睡千年的呓语。檐角上的月，是我斑驳万古的诗行。我执掌着古老的秘辛，亦守望着长夜的尽头。当钟声敲响，顽石睁眼，凡凝视我的，都将被地狱吞噬。\""],"roles":[{"name":"石像鬼","team":"outsider","ability":"当你首次被其他玩家提名时，他死亡。如果你杀死了邪恶玩家，你变成他的角色与阵营。"}]},"pages/祖母.html":{"name":"祖母","englishName":"Grandmother","background":["“我的小心肝呀，如果你要出门，记得加件外套。这是你的保温杯。这是你的围巾。你知道我心脏不太好。要是你感冒了，或者有个三长两短，我该怎么办？”"],"roles":[{"name":"祖母","team":"townsfolk","ability":"在你的首个夜晚，你会得知一名善良玩家和他的角色。如果恶魔杀死了他，你也会死亡。"}]},"pages/神谕者.html":{"name":"神谕者","englishName":"Oracle","background":["“唯有受选者才能凝视面纱之外的光景。亡者躁动不安……他们的每一根僵硬的手指都指向了刺骨的北地。”"],"roles":[{"name":"神谕者","team":"townsfolk","ability":"每个夜晚*，你会得知有多少名死亡的玩家是邪恶的。"}]},"pages/禁卫军.html":{"name":"禁卫军","englishName":"Imperialist","background":["“他触犯了宵禁，罪该当斩！是的，大人，他的确是在申时触犯的宵禁。”"],"roles":[{"name":"禁卫军","team":"minion","ability":"“疯狂”地想要死亡的玩家可能会立即被处决。"}]},"pages/私货商人.html":{"name":"私货商人","englishName":"Bootlegger","background":["“我刚从老家搞来一批新货，一种我亲手酿的玩意儿，我给它起名叫‘灵冢雾’——想来点儿吗？”"],"roles":[{"name":"私货商人","team":"loric","ability":"这个剧本包含有自制角色或自制规则。"}]},"pages/秉笔.html":{"name":"秉笔","englishName":"Brush Holder","background":["“票拟批红，缺一不可。”"],"roles":[{"name":"秉笔","team":"townsfolk","ability":"如果你在白天死亡，当晚你会得知一名善良玩家。如果你在夜晚死亡，当晚你会得知一名邪恶玩家。"}]},"pages/科学怪人.html":{"name":"科学怪人","englishName":"Boffin","background":["“恒星的氢能，取之不尽，静待采掘；碳、氧、氖，尽数裂解。分子引发混沌，熵增由此产生，宇宙现象更替，原子紊乱重塑，物质聚合坍缩。所有的一切，都集中在这一个小小的锥形瓶中。”"],"roles":[{"name":"科学怪人","team":"minion","ability":"恶魔拥有一个不在场的善良角色的能力，即使他醉酒或中毒。你和他都知道他获得了什么能力。"}]},"pages/稻草人_Scarecrow.html":{"name":"稻草人","englishName":"Scarecrow","background":["\"乌鸦很聪明。它们啄我之前，会先在我身上站一会儿，试试我是不是活的。确认我是稻草，就放心啄了。你们推上来下一个人之前，能不能也试试——先看看我这个稻草人烧起来是什么样子。看完再决定，要不要再烧下一个。\""],"roles":[{"name":"稻草人","team":"outsider","ability":"你以为你是一个镇民角色，但其实你不是。如果你死亡，下次处决不会造成死亡。"}]},"pages/穷奇.html":{"name":"穷奇","englishName":"Qiong Qi","background":["“有兽焉，其状如牛，猬毛，名曰穷奇，音如獆狗，是食人。”"],"roles":[{"name":"穷奇","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。如果今天白天有外来者死亡，当晚改为你要选择一名玩家：他死亡，但被当作仍然存活，随后会有一名其他玩家死亡。[+1外来者]"}]},"pages/空中飞人_Aerialist.html":{"name":"空中飞人","englishName":"Aerialist","background":["“哈哈哈哈！你们闻到了吗？硫磺味的风在撕扯我的伞！听啊！胫骨断裂的节奏比死亡金属更带劲！等会被我的脑浆溅到衣服的观众当中，最难堪的那个就是恶魔！”"],"roles":[{"name":"空中飞人","team":"townsfolk","ability":"你死亡的当晚会知所有角色类型的玩家各一名。你死于善良玩家发起的提名处决或能力时，你醉酒。"}]},"pages/窃贼.html":{"name":"窃贼","englishName":"Thief","background":["“我可是嘛事儿也没干。昨儿嘛晚我连内个小巷子都没去过！绝不是我偷了布鲁诺镇长的公文包。它内包儿里面儿讷么老些花哨儿纸儿，可太沉了。”"],"roles":[{"name":"窃贼","team":"traveller","ability":"每个夜晚，你要选择除你以外的一名玩家：明天白天他的投票会被算作负数。"}]},"pages/筑梦师.html":{"name":"筑梦师","englishName":"Dreamer","background":["“我记得有钟表匠……天空是红色的，有不规则的三角形不断从天上坠落下来。有紫罗兰的气味……还有气泡咕嘟咕嘟的声音。一个眼睛发光、还有着乱糟糟的胡须的女人对着天空发出嘶嘶声。然后，我醒了……”"],"roles":[{"name":"筑梦师","team":"townsfolk","ability":"每个夜晚，你要选择除你及旅行者以外的一名玩家：你会得知一个善良角色和一个邪恶角色，该玩家是其中一个角色。"}]},"pages/管家.html":{"name":"管家","englishName":"Butler","background":["“是的，先生……不对，先生……当然，先生。”"],"roles":[{"name":"管家","team":"outsider","ability":"每个夜晚，你要选择除你以外的一名玩家：明天白天，只有他投票时你才能投票。"}]},"pages/米诺陶_Minotaur.html":{"name":"米诺陶","englishName":"Minotaur","background":["\"你知道迷宫的真正妙处吗？不是让人迷路，而是让人以为每一步都踩在正确的方向上。千百年来，我每每拖着伤蹄逃跑，看起来已是强弩之末。他们追着我穿过一扇又一扇石门，以为那是通往胜利的捷径。可这里没有指路的线团，没有回头的标记。那些看似通达的巷道，每一道拐都通向翻板或钉坑。每一次迫近，每一次‘即将得手’，不过是我量身定做的错觉。当他们兴奋地迎接‘胜利’时，等待他们的只有迷宫深处那无垠的黑暗。\""],"roles":[{"name":"米诺陶","team":"demon","ability":"每个夜晚*，你要选择一名存活玩家：他死亡。审判日降临前，如果所有邪恶玩家均死于处决，你的阵营获胜。"}]},"pages/精神病患者.html":{"name":"精神病患者","englishName":"Psychopath","background":["“惊不惊喜？！”"],"roles":[{"name":"精神病患者","team":"minion","ability":"每个白天，在提名开始前，你可以公开选择一名玩家：他死亡。如果你被处决，提名你的玩家需要和你猜拳，只有你输了你才会死亡。"}]},"pages/红唇女郎.html":{"name":"红唇女郎","englishName":"Scarlet Woman","background":["“你曾向我展示了紫焰议会的秘密。我们也曾一起在烈火里拥抱，在欲望中交欢，在兽性的驱使下耳鬓厮磨，我将永生永世侍奉于你。但今晚，我亲爱的，我是你的主人。”"],"roles":[{"name":"红唇女郎","team":"minion","ability":"如果大于等于五名玩家存活时（旅行者不计算在内）恶魔死亡，你变成那个恶魔。"}]},"pages/纳垢_Nurgle.html":{"name":"纳垢","englishName":"Nurgle","background":["\"哦，我可怜的孩子们，你们看起来气色不太好——脸色太干净了，皮肤太光滑了，这可不行。来，让祖父抱抱你们，我已经好几天没有拥抱过新面孔了。你们的身体里缺一些温暖的东西，一些……会缓慢生长的东西，等你们腹中有了我的‘小礼物’，你们就会发现，腐烂是一种多么安心的感觉。别怕，会有一点点胀，一点点痒，但那只是我的孩子们在跟你打招呼。当你们全身都开出花来的时候，你们会感谢我的。\""],"roles":[{"name":"纳垢","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡，且与他邻座的玩家们会中毒直到你下次攻击前。"}]},"pages/纹章官_Herald.html":{"name":"纹章官","englishName":"Herald","background":["\"这本册子记录了镇上十七个家族的纹章沿革。谁家娶了谁家的女儿，徽上就多一道镶边。谁家分出了旁支，徽上就添一道分割线。谁家出了叛徒，整面盾徽被劈成两半——这一页就是。我画的不是图案，是家谱。每一笔都是契约，每一个色块都是判决。\""],"roles":[{"name":"纹章官","team":"townsfolk","ability":"每局游戏限一次，在夜晚时，你可以选择一名其他玩家：你会得知两名玩家。这三名玩家的角色类型各不相同。[+1外来者]"}]},"pages/维京人_Viking.html":{"name":"维京人","englishName":"Viking","background":["_\"__我闻到了你们身上的恐惧，像腐肉一样臭。你们害怕的死亡，在我眼里只是一道门槛。踩过去，女武神就会引领我去英灵殿。而你们，死后只会烂在地里，连蛆都嫌脏。所以由我亲手送你们上路，这不是处决，是净化。跪好，别让我说第二遍。\"_"],"roles":[{"name":"维京人","team":"townsfolk","ability":"当你在死后首次投票时，当前被提名的玩家立即被处决。"}]},"pages/维齐尔.html":{"name":"维齐尔","englishName":"Vizier","background":["“出色的判决，陛下。冲撞主教这样的小罪的确值得您的‘正义’与‘仁慈’。而您只需要在花园里散散心，参观参观画廊，欣赏欣赏冯·斯特劳夫的雕塑作品。放轻松，陛下。把一切……都交给我。”"],"roles":[{"name":"维齐尔","team":"minion","ability":"所有玩家都知道你是维齐尔。你在白天时不会死亡。如果一次提名中有善良玩家投票，你可以让被提名者立即被处决。"}]},"pages/罂粟种植者.html":{"name":"罂粟种植者","englishName":"Poppy Grower","background":["“黑色罂粟栖息在森林深处的隐蔽树丛里。见到它的狂野生长会为此着迷。闻到它的浓烈香气将永远迷失，沦为光明与黑暗之神的奴隶。”"],"roles":[{"name":"罂粟种植者","team":"townsfolk","ability":"爪牙和恶魔互相不认识。如果你死亡，当晚他们会互相认识。"}]},"pages/美人鱼_Mermaid.html":{"name":"美人鱼","englishName":"Mermaid","background":["_\"__岸上的小宝贝们，耳朵痒不痒？那是因为我的歌声钻进你们心里啦！小镇上谁不知道，只要我一开口，连海鸥都不舍得飞走～今天心情超级好，允许你们每人许一个愿望，不过得先夸我一句！从你开始，对，戴帽子的那个。美人鱼姐姐最美？嗯…勉强及格，过来击个掌吧！\"_"],"roles":[{"name":"美人鱼","team":"townsfolk","ability":"每个白天，你可以公开接受一名其他玩家对你的赞美：邪恶角色的能力对他无效，直到你接受了另一名玩家的赞美。"}]},"pages/群星_“辣椒”.html":{"name":"“辣椒”","englishName":"","background":["“食我辣味后，所言皆虚，所见皆幻。”"],"roles":[{"name":"“辣椒”","team":"minion","ability":"在你的首个夜晚，你要查看魔典，并选择剧本列表的一列：该列所有非爪牙角色中毒且必定产生错误信息。"}]},"pages/群星_乐师.html":{"name":"乐师","englishName":"","background":[],"roles":[{"name":"乐师","team":"fabled","ability":"你可以为当前局势播放最契合的背景音乐。"}]},"pages/群星_凤翼.html":{"name":"凤翼","englishName":"Phoenix Wing","background":["“顺着风，我能闻见恶魔身边那个人的气息。”"],"roles":[{"name":"凤翼","team":"townsfolk","ability":"每个夜晚，你会从恶魔的顺时针方向得知下一名玩家的阵营。"}]},"pages/群星_圣裁.html":{"name":"圣裁","englishName":"","background":["“真相，从来不是一成不变的。”"],"roles":[{"name":"圣裁","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。镇民产生的信息不会与他上一次产生信息的正误相同。"}]},"pages/群星_地平论者.html":{"name":"地平论者","englishName":"","background":["“他们嘲笑我，说麦哲伦的舰队早已绕过了世界的尽头，库克船长的航海日志写满了圆的证据。维多利亚时代的百年航行根本就是愚民的骗局！我知道真相——万物必有尽头，那尽头是一道冰墙，是造物主设下的屏障，是凡人不该逾越的边界。你们宣扬正统，如今在桌前把酒言欢，可谁知道圆桌有无裂缝，人心又有无嫌隙？哪有什么不可打破的圆，不过是缝合的谎言。”"],"roles":[{"name":"地平论者","team":"outsider","ability":"[圆桌在两名相邻玩家之间裂开，恶魔得知并可以重新选择这个裂隙在哪]"}]},"pages/群星_塔罗占卜师.html":{"name":"塔罗占卜师","englishName":"","background":[],"roles":[{"name":"塔罗占卜师","team":"fabled","ability":"每名玩家限一次，你可以为拜访你的玩家选择一张塔罗牌作为指引。"}]},"pages/群星_声控灯.html":{"name":"声控灯","englishName":"","background":["“（荣）神说：‘要有光。’于是我出现了；（荣）神不语，于是我消失了。信徒渴望神谕，我遂闪烁于夜间；纵使逆党弑神，神亦因我而再现。”"],"roles":[{"name":"声控灯","team":"outsider","ability":"你安静时可能死亡，说话时可能复活，即使你已死亡。"}]},"pages/群星_外交官.html":{"name":"外交官","englishName":"","background":["他将酒杯举起，烛光在翡翠色的液体中晃动。他说：“若你愿意，我们可在此刻停战，直到黎明再次割裂黑夜。” 于是刀锋悬停，无人敢越界。"],"roles":[{"name":"外交官","team":"townsfolk","ability":"每局游戏限一次，在夜晚时*，你可以选择一名玩家：与他阵营不同的玩家不会死亡，直到下个黄昏。"}]},"pages/群星_守钥人.html":{"name":"守钥人","englishName":"","background":["“钥匙会开启门，那么用什么开启钥匙？”"],"roles":[{"name":"守钥人","team":"townsfolk","ability":"一名恶魔醉酒。每个夜晚*，首个被恶魔选择的玩家死亡。"}]},"pages/群星_定序王子.html":{"name":"定序王子","englishName":"","background":["“我以数字为咒。被命运选中的人，将在今夜品尝我的毒药。”"],"roles":[{"name":"定序王子","team":"minion","ability":"在你的首个夜晚，你决定x的数值。每个夜晚，第x个因自身能力被唤醒的玩家当晚中毒。"}]},"pages/群星_密码学家.html":{"name":"密码学家","englishName":"","background":["“他们谎称彼此不相识，我却看到了他们相同的印记。”"],"roles":[{"name":"密码学家","team":"townsfolk","ability":"爪牙和恶魔互相不认识。首个夜晚，他们会得知同一个关键词，你会得知与之相关的线索。"}]},"pages/群星_寻宝团.html":{"name":"寻宝团","englishName":"","background":[],"roles":[{"name":"寻宝团（线下）","team":"fabled","ability":"线下：游戏开始时，你要宣布任意数量剧本外的角色，将其角色标记秘密藏匿于场地某处，首个找到他的玩家可以在白天拜访你并获得该角色能力。"},{"name":"寻宝团（线上）","team":"fabled","ability":"线上：游戏开始时，你要宣布任意数量剧本外的角色和对应的提示，为每个角色分配一句符合提示的短语，首个说出该短语的玩家可以立即获得该角色能力。"}]},"pages/群星_平行时空.html":{"name":"平行时空","englishName":"","background":[],"roles":[{"name":"平行时空","team":"fabled","ability":"每当一名非镇民玩家死亡后，存活恶魔变成剧本列表里的下一个恶魔角色（可循环）。"}]},"pages/群星_悲悼者.html":{"name":"悲悼者","englishName":"","background":["“想必你的名字会铭刻在历史上，成为指引我的光芒。”"],"roles":[{"name":"悲悼者","team":"townsfolk","ability":"如果与你邻近的存活玩家死亡，你会在当晚得知另一名与你邻近的存活玩家的角色。"}]},"pages/群星_悲观主义者.html":{"name":"悲观主义者","englishName":"","background":["“我说实话真的没办法。”——实话最多办法最少的一集"],"roles":[{"name":"悲观主义者","team":"outsider","ability":"当你得知你死亡时，你要公开声称一个恶魔角色：如果该角色不在场，恶魔获得他的能力一天一夜。"}]},"pages/群星_戒律.html":{"name":"戒律","englishName":"","background":["“所以我告诉你们，人一切的罪，和亵渎的话，都可得赦免。惟独亵渎圣灵，总不得赦免。”"],"roles":[{"name":"戒律","team":"demon","ability":"每个夜晚*，你要选择一名玩家，他死亡。当某种角色类型（旅行者除外）首次没有存活玩家时，所有镇民中毒直到明天黄昏［+1/-1外来者］"}]},"pages/群星_战争祭司.html":{"name":"战争祭司","englishName":"","background":["我的回合，我的回合，还是我的回合。"],"roles":[{"name":"战争祭司","team":"townsfolk","ability":"每局游戏限一次，在夜晚时*，你可以选择一名除你以外未选择过的存活玩家，然后重复此流程，直到最后两次选择的玩家类型相同。[+1外来者]"}]},"pages/群星_水占师.html":{"name":"水占师","englishName":"","background":["“水是一门语言，每一道波纹都是问题的答案。不过，哪个问题呢？”"],"roles":[{"name":"水占师","team":"townsfolk","ability":"一名镇民醉酒。每个夜晚，如果他的能力未正常生效（从上个黎明到你被唤醒时）,你得知一名邪恶玩家，否则得知一名善良玩家。"}]},"pages/群星_深渊.html":{"name":"深渊","englishName":"","background":["“我吞噬靠近我的亡魂。每有一个邻座坠落，我便获得一份新的力量。深渊在凝视你，而你，无处可逃。”"],"roles":[{"name":"深渊","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。每有一个与你相邻的玩家死亡，你获得一个不在场的爪牙能力。"}]},"pages/群星_煽动者.html":{"name":"煽动者","englishName":"","background":["“大伙快来看呐，这鱼肚子里面有个纸条！”"],"roles":[{"name":"煽动者","team":"minion","ability":"你存活/死亡时，镇民产生的信息对错翻转。[+0/+1外来者]"}]},"pages/群星_猫猫军团.html":{"name":"猫猫军团","englishName":"Cat Legion","background":["“我们人多势众，连影子都结伴而行。”"],"roles":[{"name":"猫猫军团","team":"townsfolk","ability":"你顺时针上最近的猫猫军团是你的同伴。 每个夜晚，你会得知同伴邻近的两名存活的玩家中是否有邪恶玩家。[+0~2猫猫军团]"}]},"pages/群星_电梯管理员.html":{"name":"电梯管理员","englishName":"","background":["“每次邀请，都是秘密的启程。你选择的楼层，将决定今夜看到怎样的风景。电梯门开了，请进。”"],"roles":[{"name":"电梯管理员","team":"townsfolk","ability":"每个白天，你可以邀请一名未邀请过的其他存活玩家秘密选择剧本的一行，当晚你得知该行有多少名角色在场。"}]},"pages/群星_盒中猫.html":{"name":"盒中猫","englishName":"","background":["“我猛地睁开双眼，就在书桌上的紫色盒子上，出现了一只蓝色的猫咪，但猫咪在我看到它的瞬间就消失了，只剩空盒子静静地立在那里。但那只猫咪的每一个细节都印在我的脑海中，它充满了生机，透出一种冰雪的灵气。”"],"roles":[{"name":"盒中猫","team":"townsfolk","ability":"你即将死亡时转变为一个相同角色类型的不在场角色，并在死亡后保留能力。[说书人决定你的角色类型（非恶魔）]"}]},"pages/群星_神杖之父.html":{"name":"神杖之父","englishName":"","background":["“是的，就是你，是我最优秀的主人！”"],"roles":[{"name":"神杖之父","team":"minion","ability":"你和每个恶魔角色都有一个相克规则：这给他们带来独特的增强。"}]},"pages/群星_穿越者.html":{"name":"穿越者","englishName":"","background":["“我已不知过去了多少岁月。漫长的时间里，我一直在等待那个人的出现。”"],"roles":[{"name":"穿越者","team":"outsider","ability":"你拥有一个剧本外的角色能力。每局游戏限一次，存活爪牙可以公开猜测你是穿越者，如果猜对，你的阵营落败。[+0~1外来者]"}]},"pages/群星_罐中胎儿.html":{"name":"罐中胎儿","englishName":"","background":["“Hoch oben am himmel，über der kargen Erde”"],"roles":[{"name":"罐中胎儿","team":"minion","ability":"每个黄昏，被处决的玩家可以公开为你挑选两个其它爪牙能力：你拥有他们直到下个黄昏；没有人为你挑选时：你秘密挑选。"}]},"pages/群星_羽信使.html":{"name":"羽信使","englishName":"","background":["我听见风在低语..."],"roles":[{"name":"羽信使","team":"townsfolk","ability":"在你的首个夜晚，你会得知与你距离最远的邪恶角色。"}]},"pages/群星_考古学家.html":{"name":"考古学家","englishName":"","background":["尘土之下埋藏着说书人的秘密。"],"roles":[{"name":"考古学家","team":"townsfolk","ability":"在房间里找到说书人留下的线索，即可获得奖励。"}]},"pages/群星_脑控者.html":{"name":"脑控者","englishName":"","background":[],"roles":[{"name":"脑控者","team":"fabled","ability":"你可以决定“可能”事件的结果。说书人可以推脱他的判定来源于你的指示，即使游戏已经结束。"}]},"pages/群星_蛹.html":{"name":"蛹","englishName":"","background":["“没有人知道茧里藏着什么——连茧自己，也是刚刚才决定的。”"],"roles":[{"name":"蛹","team":"minion","ability":"每个夜晚*，你要选择一个角色，如果该角色不在场，你变成该角色。如果你的角色类型因此改变，相同角色类型的一名玩家死亡。[爪牙都是蛹]"}]},"pages/群星_蛾母.html":{"name":"蛾母","englishName":"","background":["“我，即是蛾群。”"],"roles":[{"name":"蛾母","team":"minion","ability":"上个死亡的邪恶玩家保留能力并变成不在场的同类型角色，你“是该角色”，但最后一天不能发动。"}]},"pages/群星_重力.html":{"name":"重力","englishName":"","background":["“现在，群星都向我坠落。”"],"roles":[{"name":"重力","team":"demon","ability":"每个夜晚*，你要选择两名玩家：他们死亡。如果你不在场，恶魔可以阻止当晚全部死亡，变为重力。[一名爪牙失去能力]"}]},"pages/群星_阿努比斯.html":{"name":"阿努比斯","englishName":"","background":["“来测量你灵魂的重量吧！”"],"roles":[{"name":"阿努比斯","team":"townsfolk","ability":"每局游戏限一次，在夜晚时*，你可以选择两名玩家：他们中在角色列表靠上的玩家死亡。"}]},"pages/群星_颅相学家.html":{"name":"颅相学家","englishName":"Phrenology","background":["“颅骨不会撒谎，撒谎的是解读颅相的人。”"],"roles":[{"name":"颅相学家","team":"townsfolk","ability":"每个夜晚，你要选择一个角色类型（与前两晚不同）和一名除你以外的玩家：你会被善良玩家当作相应类型的角色和阵营，然后你会得知你们角色类型是否相同。"}]},"pages/群星_领航员.html":{"name":"领航员","englishName":"","background":["“迷乎云梦者，必指往南方，不识西东与之共夜航。”从古代牵星引路，到大航海时代晚期制霸海疆，罗盘和六分仪指引着齿轮与轰鸣的蒸汽机的航向，也引领着那个辉煌荣耀的时代的方向。"],"roles":[{"name":"领航员","team":"townsfolk","ability":"每个夜晚*，以钟为罗盘，上个处决指针为南，你得知某个方位有邪恶。如果该玩家为邪恶，指针视为北。"}]},"pages/群星_魅影.html":{"name":"魅影","englishName":"","background":["“邪恶不朽。我，就是不朽。”"],"roles":[{"name":"魅影","team":"demon","ability":"死于处决的邪恶玩家保留能力。每个夜晚*，你要选择一名玩家：他死亡。在一名死亡玩家被处决后，他的阵营落败，在此之前邪恶阵营不会落败。"}]},"pages/群星_鸽多.html":{"name":"鸽多","englishName":"Goodo","background":["“鸽多先生让我告诉你们，他今晚不来了，但是明天准来。”"],"roles":[{"name":"鸽多","team":"outsider","ability":"你拥有一种在游戏结束时加入获胜阵营的方法（即使你已死亡），但你不知道是什么。每个白天，你可以拜访说书人获得关于这个方法的线索。"}]},"pages/腹语师.html":{"name":"腹语师","englishName":"Ventriloquist","background":["“来来来，各位看官都围过来！这是我的老搭档查理，他那张嘴啊，能把驴都说羞了。不过别担心，各位——开口说话的一直是我……对吧？”"],"roles":[{"name":"腹语师","team":"loric","ability":"如果一名玩家在被提名时“疯狂”地证明自己是一个新的角色，他可能不会死于当天的处决。"}]},"pages/舞蛇人.html":{"name":"舞蛇人","englishName":"Snake Charmer","background":["“这位老爷……虽然我的烟斗是金色的，虽然我只要一首曲子就能驯服最狂野的灯神，但我只是一个卑贱的舞蛇人罢了，哎……听天由命吧。俗话说，人心不足蛇吞象。但不是我，这位老爷……真的不是我。”"],"roles":[{"name":"舞蛇人","team":"townsfolk","ability":"每个夜晚，你要选择一名存活的玩家：如果你选中了恶魔，你和他交换角色和阵营，然后他中毒。"}]},"pages/船长_Skipper.html":{"name":"船长","englishName":"Skipper","background":["\"献给波塞冬的祭品，会让我的罗盘指向恶魔的藏身地，左或右，比海图更清晰。而献祭叛徒的代价是一杯神罚的苦酒。小伙子们，天亮前记得叫醒我！\""],"roles":[{"name":"船长","team":"townsfolk","ability":"每个夜晚*，你会得知恶魔更接近当天被处决玩家的左侧还是右侧。如果邪恶玩家被处决，你醉酒直到下个黎明。"}]},"pages/色孽_Slaanesh.html":{"name":"色孽","englishName":"Slaanesh","background":["\"跪下吧，不是为了求饶，是为了领受。我是你梦里不敢醒来的那一部分，我每向你走近一步，地上就开出一朵艳丽的花，那些花以欢愉浇灌、以情欲为根，它的香气能让人忘掉一切。你们管这叫‘堕落’？我只觉得可笑。来，把手给我。让我告诉你——克制是谎言，自律是枷锁，唯有沉沦，才是你这副血肉之躯的完美归宿。\""],"roles":[{"name":"色孽","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡，且你可以让他得知你是色孽。最近一名得知你是色孽的玩家胜负条件与你相同，即使你已死亡。"}]},"pages/艺伎_Geisha.html":{"name":"艺伎","englishName":"Geisha","background":["_\"__住我隔壁的妹妹，为一个男人跳了河。捞上来的时候，嘴角还在笑着。别人都说她傻，说她疯。我没吭声。我知道，她不是疯，她只是算明白了。妈妈教过我们：楼里的姑娘动真情就是倒贴。可那妹妹说——不动真情，才是真的倒贴，贴进去一辈子。活着和活过，差一个字，就差着一辈子。她活过了，就值了。\"_"],"roles":[{"name":"艺伎","team":"townsfolk","ability":"在你存活与死亡的首个夜晚，你会分别得知一名存活玩家：他们的阵营对立。"}]},"pages/艺术家.html":{"name":"艺术家","englishName":"Artist","background":["“天啊！多么美妙的作品！我的作品……用你们的话怎么说来着……对，璀璨夺目！栩栩如生！没错！”"],"roles":[{"name":"艺术家","team":"townsfolk","ability":"每局游戏限一次，在白天时，你可以私下询问说书人一个是非问题，你会得知该问题的答案。"}]},"pages/茶艺师.html":{"name":"茶艺师","englishName":"Tea Lady","background":["“若你感到寒冷，茶能使你温暖。","若你感到愤怒，茶能使你冷静。","若你感到沮丧，茶能使你振奋。","若你感到激动，茶能使你镇定。”"],"roles":[{"name":"茶艺师","team":"townsfolk","ability":"如果与你邻近的两名存活的玩家是善良的，他们不会死亡。"}]},"pages/莽夫.html":{"name":"莽夫","englishName":"Goon","background":["“是的，老大。我跟那个家伙好好解释过了。他不愿意再听我解释一遍。不不，老大，我不需要医生——只是刀伤而已。明天早上就好了。”"],"roles":[{"name":"莽夫","team":"outsider","ability":"每个夜晚，首个使用其自身能力选择了你的玩家会醉酒直到下个黄昏。你会转变为他的阵营。"}]},"pages/萨满_Shaman.html":{"name":"萨满","englishName":"Shaman","background":["\"渴望力量？我给。渴望自由？我也给。但代价是丢掉人形。跪下吧，让我把你们的灵魂塞进羊的皮囊。颤抖吧，你们会发现自己长出了毛，四脚着地，脑子里只剩下咀嚼和逃命。别担心迷路——我为你们准备的牲圈，就在前方。\""],"roles":[{"name":"萨满","team":"minion","ability":"每局游戏限一次，在夜晚时*，你可以选择四个不同类型的角色：对每个不在场的角色，一名同类型的玩家会变成该角色。"}]},"pages/落难少女.html":{"name":"落难少女","englishName":"Damsel","background":["“别摸头发，亲爱的。”"],"roles":[{"name":"落难少女","team":"outsider","ability":"所有爪牙都知道落难少女在场。每局游戏限一次，任意爪牙可以公开猜测你是落难少女，如果猜对，你的阵营落败。"}]},"pages/蘑菇仔_Myconid.html":{"name":"蘑菇仔","englishName":"Myconid","background":["\"死掉的蘑菇，会长蘑菇。死掉的坏人，也会长蘑菇。\""],"roles":[{"name":"蘑菇仔","team":"outsider","ability":"你与爪牙会在死于处决后保留能力。"}]},"pages/蛊雕.html":{"name":"蛊雕","englishName":"Hekwing","background":[],"roles":[{"name":"蛊雕","team":"minion","ability":"每个夜晚，你要选择左或右：将你的飞行标记从当前位置移动到这个方向上的下一名存活善良玩家。他中毒且可能被当作邪恶阵营和爪牙角色，你会知道他原本的角色。"}]},"pages/街头风琴手.html":{"name":"街头风琴手","englishName":"Organ Grinder","background":["“如果你想让别人听信你的花言巧语，那么就搭配上一段音乐吧。”","（英文维基上的背景描述与角色详解中的不同，此处也一并贴出。见下）","“曲柄划圆吱呀吱，舞步渐狂心渐痴。”"],"roles":[{"name":"街头风琴手","team":"minion","ability":"所有玩家在投票时闭眼，且票数会秘密统计。对你的提名只在你投票时才会统计票数。"}]},"pages/见闻家_Witness.html":{"name":"见闻家","englishName":"Witness","background":["\"我见过镇民在烛光下祈祷，也见过他们在墙根写下诅咒；我见过外来者带着礼物敲门，也见过他们偷挖墓地里的棺椁；我见过爪牙跪舔主人的皮鞋，也见过他们跪在神像前忏悔；我见过恶魔的双手沾满了鲜血，也见过它们为婴儿的哭声感伤。你以为我在分辨善恶？不，我只是在看同一面镜子，映射出两种不同的光。\""],"roles":[{"name":"见闻家","team":"townsfolk","ability":"每个白天，你可以从说书人处得知一条正确信息（关于某种角色类型）。如果该类型的玩家数量异常，你改为得知错误信息。"}]},"pages/解谜大师.html":{"name":"解谜大师","englishName":"Puzzlemaster","background":["“当一个人开始认为某件事只不过是另一件事时，那么他通常都处在错误的边缘。耐心，耐心。不要把‘只不过’和‘应该’，‘是’和‘不是’混为一谈。”"],"roles":[{"name":"解谜大师","team":"outsider","ability":"一名玩家醉酒，即使你已死亡。每局游戏限一次，你可以猜测谁是那个醉酒的玩家，如果猜对了，你会得知谁是恶魔，但如果猜错了，你会得知错误的“谁是恶魔”信息。"}]},"pages/讷神.html":{"name":"讷神","englishName":"God of Ug","background":["“我的孩子们是被祝福的，因为他们能在简单之物之中看见美。”"],"roles":[{"name":"讷神","team":"loric","ability":"会有一顶讷帽。当玩家戴着讷帽的时候，只能说单音节词，但投票算作两票。如果违反规则，讷帽会被转移。"}]},"pages/诡诈杰克.html":{"name":"诡诈杰克","englishName":"Knaves","background":["“处处皆可为门，餐餐皆可为宴。”"],"roles":[{"name":"诡诈杰克","team":"loric","ability":"场上有两位说书人：一人说真话，一人说假话。每局游戏限一次，他们可能会在黄昏互换。"}]},"pages/诺-达鲺.html":{"name":"诺-达鲺","englishName":"No Dashii","background":["“彼因汝之罪孽，吾已嗅汝之恶臭满溢全身。时日曷丧？予及汝皆亡。竖子命如草芥，以吾之力，使汝终末于深海，终于此良夜。”"],"roles":[{"name":"诺-达鲺","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。与你邻近的两名镇民中毒。"}]},"pages/调查员.html":{"name":"调查员","englishName":"Investigator","background":["“这真是个散步的好夜晚，您说呢，莫罗佐夫先生？","还是我应该称呼您为……莫罗佐夫男爵？”"],"roles":[{"name":"调查员","team":"townsfolk","ability":"在你的首个夜晚，你会得知两名玩家和一个爪牙角色：这两名玩家之一是该角色（或者你会得知没有爪牙在场）。"}]},"pages/调音师_Tuner.html":{"name":"调音师","englishName":"Tuner","background":["“离调和弦中有一丝爪牙的味道…而这突如其来的微分音，分明是异乡人慌乱的心跳。”"],"roles":[{"name":"调音师","team":"townsfolk","ability":"在你的首个夜晚，你会得知一个外来者角色和一个爪牙角色。其中有且只有一个角色在场。"}]},"pages/调香师_Perfumer.html":{"name":"调香师","englishName":"Perfumer","background":["\"今夜的香水我准备了两种：一种如情书般坦白，另一种...（突然靠近）像捕兽夹上的玫瑰。亲爱的，你猜你闻到的是哪一种？\""],"roles":[{"name":"调香师","team":"townsfolk","ability":"每局游戏限一次，在夜晚时，你可以选择一名玩家或一个邪恶角色：他会得知调香师在场。"}]},"pages/谜语人_Riddler.html":{"name":"谜语人","englishName":"Riddler","background":["\"不会吧不会吧，不会真有人猜不到吧？\""],"roles":[{"name":"谜语人","team":"townsfolk","ability":"每个白天，你可以从说书人处得知一条谜语。谜语的谜底指向一个在场角色。"}]},"pages/贞洁者.html":{"name":"贞洁者","englishName":"Virgin","background":["“我是纯洁的。就让那些无罪之人匍匐在地，替我受苦吧。我的名誉不应被你恶毒的指控所玷污。”"],"roles":[{"name":"贞洁者","team":"townsfolk","ability":"当你首次被提名时，如果提名你的玩家是镇民，他立刻被处决。"}]},"pages/贤者.html":{"name":"贤者","englishName":"Sage","background":["“这书山卷海中一定隐藏着秘密，我非常确信！这些秘密就隐藏在这一字一句之间等待着我们发掘。小子！再帮我多拿点蜡烛！还有墨水！虽然这些笔记有些晦涩，但有关恶魔的谜语很快就会被揭晓。”"],"roles":[{"name":"贤者","team":"townsfolk","ability":"如果恶魔杀死了你，在当晚你会被唤醒并得知两名玩家，其中一名是杀死你的那个恶魔。"}]},"pages/贵族.html":{"name":"贵族","englishName":"Noble","background":["“讽刺的确是最不足挂齿的机智。尽管如此，先生，回应你的批评，就是一种机智。”"],"roles":[{"name":"贵族","team":"townsfolk","ability":"在你的首个夜晚，你会得知三名玩家：其中有且只有一名玩家是邪恶的。"}]},"pages/赌徒.html":{"name":"赌徒","englishName":"Gambler","background":["“正面，我赢。","反面，你输。”"],"roles":[{"name":"赌徒","team":"townsfolk","ability":"每个夜晚*，你要选择一名玩家并猜测他的角色：如果你猜错了，你会死亡。"}]},"pages/赏金猎人.html":{"name":"赏金猎人","englishName":"Bounty Hunter","background":["“我一个人在这铺满腐败恶臭的街道上行走着。邪恶不请自来，在我的鼻腔里蠕动，将厌恶点燃，将期待烧光。这个令人不悦的地方一天比一天更加病态。而我……我会是这些罪恶的解药。”"],"roles":[{"name":"赏金猎人","team":"townsfolk","ability":"在你的首个夜晚，你会得知一名邪恶玩家。每当你得知的玩家死亡，你会在当晚得知另一名邪恶玩家。[会有一名镇民转变为邪恶阵营]"}]},"pages/赶尸人.html":{"name":"赶尸人","englishName":"Corpse Walker","background":["“你须待到天黑再赶路，切莫让人发现你的肚子里都是稻草。”"],"roles":[{"name":"赶尸人","team":"minion","ability":"与你邻近的两名镇民玩家会在其首次死亡时被当作仍然存活。[-1外来者]"}]},"pages/超感者_Sensate.html":{"name":"超感者","englishName":"Sensate","background":["\"黑暗的视觉，我替光明收下了。我不是先知，我不会预言，我只是借用了恶魔的眼睛，拆穿他的把戏，送他上路。\""],"roles":[{"name":"超感者","team":"townsfolk","ability":"每个夜晚，恶魔要选择一名除你以外的存活玩家：恶魔和你会得知他是什么角色。"}]},"pages/达摩_Daruma.html":{"name":"达摩","englishName":"Daruma","background":["\"大家都在这儿吗？你们在做什么呀？今日是什么日子？屋子里藏着什么秘密？没人愿意同我说说话吗？多说一句也无妨吗？说出口会生出祸事吗？我只是随便问问不行吗？\""],"roles":[{"name":"达摩","team":"minion","ability":"如果其他玩家回答了你的问题，他可能会死亡。如果你回答了其他玩家的问题，你可能会死亡。你不会死于其他原因。"}]},"pages/近卫_Vanguard.html":{"name":"近卫","englishName":"Vanguard","background":["_\"__喂，你看上去好像很厉害。但你有一个致命弱点——你在害怕。因为你发现，无论你绕到哪个角度，我都挡在前面。__\"_"],"roles":[{"name":"近卫","team":"townsfolk","ability":"审判日降临前的每个夜晚*，你要选择：你当晚不会死亡；或与你邻近的两名存活玩家当晚不会死亡。"}]},"pages/送报童_Paperboy.html":{"name":"送报童","englishName":"Paperboy","background":["“铛铛！今日头条！今日头条！”"],"roles":[{"name":"送报童","team":"townsfolk","ability":"每个白天，你可以从说书人处获取一条新闻，如果你公开宣读了该新闻，当晚你会得知它是否为事实。"}]},"pages/送葬者.html":{"name":"送葬者","englishName":"Undertaker","background":["“嗯……看看我们发现了什么？左靴到足跟都有磨损，靴尖下还有些硝石屑。这是军人才会有的装束。”"],"roles":[{"name":"送葬者","team":"townsfolk","ability":"每个夜晚*，你会得知今天白天死于处决的玩家的角色。"}]},"pages/逆臣.html":{"name":"逆臣","englishName":"Turncoat","background":["“尔遣使遗尔舅祖总兵书，朕已洞悉。将军之心，犹豫未决。朕恐将军失次机会，殊可惜耳。”"],"roles":[{"name":"逆臣","team":"outsider","ability":"在你的首个夜晚，你要选择除你以外的一名玩家：如果他先死于处决，你转变为邪恶；如果你先死于处决，他转变为邪恶。"}]},"pages/逆蝶_Crosswing.html":{"name":"逆蝶","englishName":"Crosswing","background":["\"世人总说翅膀是奔向光明的信物，却不知，有些翅膀生来就是丈量阴影的尺度。被轻触的灵魂啊，不必惊慌，不必追觅。你只是，恰好站在了我与光明的间隙里。\""],"roles":[{"name":"逆蝶","team":"minion","ability":"在第X个夜晚，你要选择是否令与你距离为X的玩家中毒直到下个黄昏。"}]},"pages/通灵师_Psychic.html":{"name":"通灵师","englishName":"Psychic","background":["_\"__我的天赋让我能闻到灵魂的气味。善者的灵魂像雨后的青草，带着晨露的清甜；恶者的灵魂则像烧焦的皮革，混杂着血腥与硫磺。昨夜离世的那位，他的气味正在我鼻腔里扩散……请喷了香水的女士和没洗澡的男士离远一些，这样我才能准确地告诉你们，他究竟是羔羊，还是豺狼。\"_"],"roles":[{"name":"通灵师","team":"townsfolk","ability":"每个夜晚*，你要选择一名玩家：如果他已死亡，你会得知他的阵营。"}]},"pages/造谣者.html":{"name":"造谣者","englishName":"Gossip","background":["“巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉巴拉。巴拉。”"],"roles":[{"name":"造谣者","team":"townsfolk","ability":"每个白天，你可以公开发表一个声明。如果该声明正确，在当晚会有一名玩家死亡。"}]},"pages/道士.html":{"name":"道士","englishName":"Dawnseal","background":["“定其心神，方可言道。”"],"roles":[{"name":"道士","team":"townsfolk","ability":"每个夜晚*，你要选择一名玩家：如果他是恶魔，你死亡，并且当晚不会再有其他玩家死亡。"}]},"pages/遗忘之门.html":{"name":"遗忘之门","englishName":"Tor","background":["“雷鸣是我的言语，闪电是我的剑。","我是永恒的守门者，吞噬一切妄闯禁域的愚者。","我的圣志昭然：净化尘世的污虫，将其困缚于星光织成的网中，","在那天与地交汇的山巅，守望永恒的真理。”"],"roles":[{"name":"遗忘之门","team":"loric","ability":"玩家不知道自己的角色和阵营。当他们死亡时才会得知这些信息。"}]},"pages/邪术师_Warlock.html":{"name":"邪术师","englishName":"Warlock","background":["_\"__这份契约从来不是交易，而是一场彻底的献祭。我赌上完整的宿命死亡，任凭肉身日后腐朽归尘，任由灵魂承受永世沉沦的责罚，才换来这一身恶魔之力。看见我周身流转的黑焰了吗？每一簇跳动的暗火，都是我来世坠入地狱必受酷刑的预演。切莫前来招惹，早已亲历过永死煎熬的人，绝不会对凡尘世间留存半分慈悲。__\"_"],"roles":[{"name":"邪术师","team":"townsfolk","ability":"如果恶魔杀死了你，此后的每个夜晚，你要选择一名玩家：他死亡。"}]},"pages/郎中.html":{"name":"郎中","englishName":"Herb Doctor","background":["“脉浮而阳气不足，气不收敛，发散在外。”"],"roles":[{"name":"郎中","team":"townsfolk","ability":"每个夜晚，你要选择一名玩家：你会得知一个与他能力相关的词语。"}]},"pages/酒保.html":{"name":"酒保","englishName":"Bartender","background":["“客官，再饮一杯吧。”"],"roles":[{"name":"酒保","team":"outsider","ability":"与你邻近的善良玩家之一醉酒，即使你已死亡。"}]},"pages/酒娘_Alewife.html":{"name":"酒娘","englishName":"Alewife","background":["_\"__我这特选呀，可不是随便什么人都能喝的。只有像您这样的大人物进了门，我才舍得从地窖里端出来。您快尝一口——保管浑身都是力气！不过可别急，慢慢喝。喝得太快，这酒的劲儿上来，我可扶不起您。__\"_"],"roles":[{"name":"酒娘","team":"townsfolk","ability":"爪牙被处决时，不会死亡但会醉酒。"}]},"pages/酒鬼.html":{"name":"酒鬼","englishName":"Drunk","background":["“我是个只在社交场合里~嗝儿~喝酒的人，亲爱的。","但无可否认，我是一个非常~嗝儿~擅长社交的人。”","（英文维基上的背景描述与角色详解中的不同，此处也一并贴出。见下）","“这完全合乎~嗝儿~逻辑。我知道的是狄亚哈特小姐是个占卜师。狄亚哈特夫人则发誓詹金斯是她的管家。得出这样的推论非常~嗝儿~简单。”"],"roles":[{"name":"酒鬼","team":"outsider","ability":"你不知道你是酒鬼。你以为你是一个镇民角色，但其实你不是。"}]},"pages/酿酒师.html":{"name":"酿酒师","englishName":"Brewer","background":["“酒后胡言，不过笑耳。”"],"roles":[{"name":"酿酒师","team":"minion","ability":"每个夜晚，你要选择一个善良角色并给出相应的信息形式：该角色通过自身能力获取信息时，改为得知你给出的信息，直到下个黄昏。[-1外来者]"}]},"pages/钟表匠.html":{"name":"钟表匠","englishName":"Clockmaker","background":["“不要打扰我。时钟的滴答声必须延续下去，它的每一圈循环都象征着生命，它的每一圈循环都包含着世间万物——世间的所有答案——它是一个无比神圣的机器。好了，我必须工作了。”"],"roles":[{"name":"钟表匠","team":"townsfolk","ability":"在你的首个夜晚，你会得知恶魔与爪牙之间最近的距离。（邻座的玩家距离为1）"}]},"pages/钦天监.html":{"name":"钦天监","englishName":"Stargazer","background":["“天降异象，荧惑守心。”"],"roles":[{"name":"钦天监","team":"townsfolk","ability":"在你的首个夜晚，你会得知离你最近的邪恶玩家位于你的哪一侧（左/右/相同）。如果与你邻近的玩家中有邪恶阵营，你会得知错误信息作为替代。"}]},"pages/锦衣卫.html":{"name":"锦衣卫","englishName":"Brocadier","background":["“赴汤蹈火，在所不辞！”"],"roles":[{"name":"锦衣卫","team":"townsfolk","ability":"每个夜晚*，你要选择一名玩家：如果他在下个黄昏前死亡，你代替他死亡。"}]},"pages/镇长.html":{"name":"镇长","englishName":"Mayor","background":["“我们必须抛开分歧，停止这种毫无意义的杀戮。","毕竟，我们都是纳税人。嗯，我是说我们中的绝大多数。”"],"roles":[{"name":"镇长","team":"townsfolk","ability":"如果只有三名玩家存活且白天没有人被处决，你的阵营获胜。如果你在夜晚即将死亡，可能会有一名其他玩家代替你死亡。"}]},"pages/镜像双子.html":{"name":"镜像双子","englishName":"Evil Twin","background":["“我不是小美！我是小梅！她才是小美！小美才是那个坏人，不是我！”"],"roles":[{"name":"镜像双子","team":"minion","ability":"你与一名对立阵营的玩家互相知道对方是什么角色。如果其中善良玩家被处决，邪恶阵营获胜。如果你们都存活，善良阵营无法获胜。"}]},"pages/间谍.html":{"name":"间谍","englishName":"Spy","background":["“每个调酒大师心中明白","配方没有麻烦来得更快","双面间谍是麻烦的主菜”"],"roles":[{"name":"间谍","team":"minion","ability":"每个夜晚，你能查看魔典。你可能会被当作善良阵营、镇民角色或外来者角色，即使你已死亡。"}]},"pages/阴阳师.html":{"name":"阴阳师","englishName":"Yin-Yang Diviner","background":["“玄武大帝在眼前，神归庙，鬼归坟，妖魔鬼怪归山林，玄武真君急急如律令！”"],"roles":[{"name":"阴阳师","team":"townsfolk","ability":"在你的首个夜晚，你会得知两个善良角色和两个邪恶角色，其中有且只有两个角色在场。"}]},"pages/阴阳师_Onmyoji.html":{"name":"阴阳师","englishName":"Onmyoji","background":["\"天地山泽·雷风水火，八卦相错……成！\""],"roles":[{"name":"阴阳师","team":"townsfolk","ability":"每个夜晚，你会得知一名玩家：他与你上个夜晚得知的玩家阵营不同。"}]},"pages/陌客.html":{"name":"陌客","englishName":"Recluse","background":["“侬康康窝咦锅惹，咋锅就怼窝恁锅粗暴。介样叭行。麻绳添酒嘿料，泥滴燕绳恨舔没，窝这哈圆酿泥料！侬晓得伐！窝叭象载康岛泥鸟，辣过饿魔阔能揍载窝家边乱晃。呔！窝揍斯弄个以斯！”"],"roles":[{"name":"陌客","team":"outsider","ability":"你可能会被当作邪恶阵营、爪牙角色或恶魔角色，即使你已死亡。"}]},"pages/限.html":{"name":"限","englishName":"Xaan","background":["“他们接连倒下。一个，又一个。两个，三个，五个。”"],"roles":[{"name":"限","team":"minion","ability":"在等同于初始外来者数量的夜晚，所有镇民玩家中毒直到下个黄昏。[外来者数量任意]"}]},"pages/集骨者.html":{"name":"集骨者","englishName":"Bone Collector","background":["“我收集了很多东西。头发、牙齿、衣服、诗歌片段以及失散恋人的美梦。还有我的秘密艺术品，你想看的话那可得给点小费，一点点就可以。如果你能给我带来一些月圆之夜死于悲痛的贵妇人的血，你就会得到你想要的答案。”"],"roles":[{"name":"集骨者","team":"traveller","ability":"每局游戏限一次，在夜晚时*，你可以选择一名死亡的玩家：他重新获得能力直到下个黄昏。"}]},"pages/雪女_Yuki-onna.html":{"name":"雪女","englishName":"Yuki-onna","background":["\"情断香销月似钩，痴魂逐雪向冥幽。冰风吊影心难定，冻雨侵衣恨未收。怨结寒霜穿肌骨，恨作长绳锁罪尤。生死相缠无了日，爱恨成囚永不休。\""],"roles":[{"name":"雪女","team":"minion","ability":"在你存活与死亡的首个夜晚，你要分别选择一名玩家：他中毒。"}]},"pages/雪怪_Yeti.html":{"name":"雪怪","englishName":"Yeti","background":["\"风会替我清扫足迹，每一片新雪都是封印。\""],"roles":[{"name":"雪怪","team":"outsider","ability":"每局游戏限一次，恶魔可以公开猜测你是雪怪，如果猜中，当天他被处决时你会代替他被处决。如果白天没人被处决，你的阵营落败。"}]},"pages/革命者.html":{"name":"革命者","englishName":"Revolutionary","background":["“团结，假装的。分裂，就拖延。”"],"roles":[{"name":"革命者","team":"fabled","ability":"公开声明一对邻座玩家本局游戏一直保持同一阵营。每局游戏限一次，他们中的一人可能被当作其他的角色/阵营。"}]},"pages/食人族.html":{"name":"食人族","englishName":"Cannibal","background":["“我讨厌小丑的味道。吃起来会让我想笑。”"],"roles":[{"name":"食人族","team":"townsfolk","ability":"你拥有上个死于处决的玩家的能力。如果该玩家属于邪恶阵营，你中毒直到下个善良玩家死于处决。"}]},"pages/食人魔.html":{"name":"食人魔","englishName":"Ogre","background":["“<咽口水>","<咧嘴笑>","</咽口水>”"],"roles":[{"name":"食人魔","team":"outsider","ability":"在你的首个夜晚，你要选择除你以外的一名玩家：你转变为他的阵营，即使你已醉酒或中毒，但你不知道你转变后的阵营。"}]},"pages/饕餮.html":{"name":"饕餮","englishName":"Tao Tie","background":["“有兽焉，其状如羊身人面，其目在腋下，虎齿人爪，其音如婴儿，名曰狍鸮，是食人。”"],"roles":[{"name":"饕餮","team":"demon","ability":"每个夜晚*，你要选择任意数量的非旅行者玩家或一名旅行者玩家：如果他们的角色类型均不相同，他们死亡。[+1外来者]"}]},"pages/首席律师.html":{"name":"首席律师","englishName":"Big Wig","background":["“虚荣会问：‘这受欢迎吗？’","懦弱会问：‘这够安全吗？’","良知会问：‘这是对的吗？’","那我们之中，谁敢问一句：","‘这是真的吗？’”"],"roles":[{"name":"首席律师","team":"loric","ability":"每个被提名者要选择一名玩家：在投票前，只有他可以发言，并且他要“疯狂”地证明被提名者是善良的，否则他可能死亡。"}]},"pages/驱魔人.html":{"name":"驱魔人","englishName":"Exorcist","background":["“每一个不洁之灵，每一份撒旦之力，每一次炼狱敌人的猛袭，每一个军团，每一个崇拜恶魔的组织和教派，以我主耶稣基督的名义和力量，将你们驱逐。我命令你们，远离上帝的教堂，远离上帝按祂的形貌所创造并受神圣羔羊的宝血所救赎的灵魂。”"],"roles":[{"name":"驱魔人","team":"townsfolk","ability":"每个夜晚*，你要选择一名玩家（与上个夜晚不同）：如果你选中了恶魔，他会得知你是驱魔人，但他当晚不会因其自身能力而被唤醒。"}]},"pages/驿使.html":{"name":"驿使","englishName":"Estafette","background":["“烽火急书，定要快马加鞭。”"],"roles":[{"name":"驿使","team":"townsfolk","ability":"每个白天，你可以公开声明一个角色。在当晚，你会得知该角色是否在场。如果你因此得知了否，你失去此能力。"}]},"pages/骑士.html":{"name":"骑士","englishName":"Knight","background":["“当有人倒下时，他也就谋杀了世界上的某个部分。”"],"roles":[{"name":"骑士","team":"townsfolk","ability":"在你的首个夜晚，你会得知两名非恶魔玩家。"}]},"pages/骗人精.html":{"name":"骗人精","englishName":"Fibbin","background":["“嘻嘻嘻，哈，嘻嘻。”"],"roles":[{"name":"骗人精","team":"fabled","ability":"每局游戏限一次，一名善良玩家可能会得知“有问题”的信息。"}]},"pages/骚客_Versifier.html":{"name":"骚客","englishName":"Versifier","background":["\"月皎惊乌栖不定，更漏将残，辘轳牵金井。\""],"roles":[{"name":"骚客","team":"minion","ability":"每个夜晚，你会得知一个字（均出自同一句诗词）。首次有玩家吟诵这句诗词时，他立即被处决，即使你已死亡。"}]},"pages/骷髅王_Skeleton_King.html":{"name":"骷髅王","englishName":"Skeleton King","background":["_“__我的耐心比你的生命更短。最后一次机会——低头，献上你的忠诚，我会赐与你膝盖接触地面的权利。我的王座前从不缺跪着的人，缺的是足够聪明的人。你的骨头看起来够硬，但我见过更硬的，不过都被我碾成了齑粉。最后一次，降，还是碎？”_"],"roles":[{"name":"骷髅王","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。当你以通常条件获胜时，曾上交投票标记的镇民也会获胜。[+1外来者]"}]},"pages/魔像.html":{"name":"魔像","englishName":"Golem","background":["“要魔像帮忙？魔像来碾碎！魔像帮了忙。”"],"roles":[{"name":"魔像","team":"outsider","ability":"每局游戏你只能发起提名一次。当你发起提名时，如果被你提名的玩家不是恶魔，他死亡。"}]},"pages/魔术师.html":{"name":"魔术师","englishName":"Magician","background":["“1…2…唵嘛呢…3…4…叭咪吽…（嗖！）","是的，正如你们所见，女士们先生们，梵斯沃船长的那袋金子不见了！没了！无迹可循！感谢诸位，晚安啦！”"],"roles":[{"name":"魔术师","team":"townsfolk","ability":"恶魔会以为你是爪牙。爪牙会以为你是恶魔。"}]},"pages/魔鬼代言人.html":{"name":"魔鬼代言人","englishName":"Devil's Advocate","background":["“如果异议被驳回，我的委托人将进行无罪申辩，理由是控方不遵守法规第27章B条——针对动词进行非正确或误导性的词形变化。昨晚有九名陪审团成员死亡，这个事实只不过是表面证据，正如威尔斯诉图勒案所开创的先例，这是无罪释放的进一步理由。”"],"roles":[{"name":"魔鬼代言人","team":"minion","ability":"每个夜晚，你要选择一名存活的玩家（与上个夜晚不同）：如果明天白天他被处决，他不会死亡。"}]},"pages/鸩.html":{"name":"鸩","englishName":"Zhen","background":["“甘如醴，毒如砒。”"],"roles":[{"name":"鸩","team":"townsfolk","ability":"每局游戏限一次，在夜晚时*，你可以选择一个镇民角色：如果他在场，他醉酒并死亡。"}]},"pages/鹰身女妖.html":{"name":"鹰身女妖","englishName":"Harpy","background":["“我从未见过如此光明的一日，阴森利爪不再笼罩着我。”"],"roles":[{"name":"鹰身女妖","team":"minion","ability":"每个夜晚，你要选择两名玩家：明天第一名玩家需要“疯狂”地证明第二名玩家是邪恶的，否则他们可能会死亡。"}]},"pages/麻脸巫婆.html":{"name":"麻脸巫婆","englishName":"Pit-Hag","background":["“绕釜环行火融融，毒肝腐脏寘其中。","蛤蟆蛰眠寒石底，三十一日夜相继；","汗出淋漓化毒浆，投之鼎釜沸为汤。”"],"roles":[{"name":"麻脸巫婆","team":"minion","ability":"每个夜晚*，你要选择一名玩家和一个角色，如果该角色不在场，他变成该角色。如果因此创造了一个恶魔，当晚的死亡由说书人决定。"}]},"pages/麻醉师_Narcotizer.html":{"name":"麻醉师","englishName":"Narcotizer","background":["_“__亲爱的，你喜欢利多卡因还是乙醚？噢...我什么都没带，要不今天用这个榔头凑合一下？我保证不会弄疼你。”_"],"roles":[{"name":"麻醉师","team":"minion","ability":"每个夜晚，你要选择一名玩家：他中毒直到你改变选择。因你中毒的存活玩家恢复健康时，会得知麻醉师在场。"}]},"pages/麻风侏儒_Leper_Gnome.html":{"name":"麻风侏儒","englishName":"Leper Gnome","background":["“过来！拥抱我！你到底在怕什么！”"],"roles":[{"name":"麻风侏儒","team":"minion","ability":"使用自身能力选择你的镇民玩家会立即变成麻风侏儒，然后你失去所有能力。你的胜负条件与邪恶玩家相同，即使你已死亡。"}]},"pages/黑帮.html":{"name":"黑帮","englishName":"Gangster","background":["“我喜欢你的鞋子。不过要是你遭遇了什么小小的意外，不小心弄坏了它们，那可就丢人了。既然你提到了，其实我也挺喜欢你的袖扣的。”"],"roles":[{"name":"黑帮","team":"traveller","ability":"每个白天限一次，你可以杀死与你邻近的两名存活的玩家中的一名，但需要另一边那个存活的玩家同意。"}]},"pages/黑帮律师_Mob_lawyer.html":{"name":"黑帮律师","englishName":"Mob lawyer","background":["\"您好，我的当事人。最近的新闻您可曾看过？不妨由我念与您听听：‘您的女儿在旅店做侍童，时常私拿店中财物；您的妻子每周潜入贵族猎场，违禁采摘果蔬；您近些年来呈报的什一税，亦多有瞒报动手脚之嫌。’我并无他意，当事人。只要明日庭上，您句句依这纸上所言供述，方才这些事，我自会当作从未听闻。\""],"roles":[{"name":"黑帮律师","team":"outsider","ability":"每个夜晚，你会得知一名玩家：下个白天，如果你和他中有人被处决，另一人可能会替代其被处决。"}]},"pages/黑骑士_Dark_Knight.html":{"name":"黑骑士","englishName":"Dark Knight","background":["“生不过是一场骗局，亡灵。我会念出你的名字，削去你的留恋，然后带你一起品尝这生灵消亡的美妙滋味。”"],"roles":[{"name":"黑骑士","team":"minion","ability":"每个夜晚*，你会得知当天死亡的外来者玩家并要猜测他的角色：如果猜中，会有一名玩家死亡。[+1外来者]"}]},"pages/龙卷_Tornado.html":{"name":"龙卷","englishName":"Tornado","background":["\"你们的刀？太钝。你们的箭？太慢。你们的眼睛？大概只能捕捉到我的脚印吧——前提是我愿意在地上留下脚印。别误会，我才不是怕你们，只是懒得被碰到。被凡人摸到衣角什么的，脏死了。\""],"roles":[{"name":"龙卷","team":"demon","ability":"每个夜晚*，你要选择一名玩家：他死亡。每个黄昏*，你会与你顺时针方向上最近的存活邪恶玩家交换角色。"}]}};
